# 4. DUAL-BROKER ADAPTER ENGINE (SCHWAB & WEBULL)
# ==========================================
def get_schwab_token_remaining_hours():
    """Returns remaining lifetime (in hours) of the 7-day Schwab Refresh Token,
    or None if the token file does not exist or lacks creation_timestamp."""
    if not os.path.exists(SCHWAB_TOKEN_PATH):
        return None
    try:
        with open(SCHWAB_TOKEN_PATH, "r", encoding="utf-8") as f:
            tok_data = json.load(f)
        created_ts = tok_data.get("creation_timestamp")
        if created_ts is not None:
            expires_ts = float(created_ts) + (7 * 86400)
            return (expires_ts - time.time()) / 3600.0
    except Exception:
        pass
    return None


def prompt_schwab_oauth_url_dialog(auth_url=""):
    """Displays an always-on-top GUI popup with clickable link, clear numbered
    instructions, and clipboard auto-detection for the Schwab 7-day OAuth URL."""
    result = {"url": ""}
    login_url = auth_url or "https://api.schwabapi.com"
    pf_win = globals().get("active_preflight_win")
    if pf_win is not None:
        try:
            if not pf_win.winfo_exists():
                pf_win = None
        except Exception:
            pf_win = None
    parent = pf_win or getattr(tk, "_default_root", None)
    is_standalone = parent is None

    dlg = tk.Tk() if is_standalone else tk.Toplevel(parent)
    dlg.withdraw()
    if not is_standalone:
        dlg.grab_set()

    dlg.title("Schwab 7-Day Security Login — Step-by-Step")
    dlg.config(bg="#0d1117", padx=24, pady=18)
    dlg.resizable(False, False)
    dlg.attributes("-topmost", True)

    hdr_row = tk.Frame(dlg, bg="#0d1117")
    hdr_row.pack(fill="x", pady=(0, 8))
    tk.Label(
        hdr_row,
        text="🔐 SCHWAB 7-DAY SECURITY LOGIN (STEP-BY-STEP)",
        font=("Arial", 12, "bold"),
        fg="#5dade2",
        bg="#0d1117",
        anchor="w",
    ).pack(side="left")
    tk.Label(
        hdr_row,
        text="🔒 7-DAY TOKEN RENEWAL",
        font=("Arial", 8, "bold"),
        fg="#7dd3fc",
        bg="#142334",
        padx=8,
        pady=3,
    ).pack(side="right", padx=(12, 0))

    steps_outer = tk.Frame(
        dlg, bg="#131922", bd=0, highlightthickness=1, highlightbackground="#243040"
    )
    steps_outer.pack(fill="x", pady=(0, 12))
    NeonBarCanvas(
        steps_outer, core_color="#38bdf8", card_bg="#131922", glow_on=True
    ).pack(side="left", fill="y")
    steps_frame = tk.Frame(
        steps_outer, bg="#131922", padx=18, pady=14
    )
    steps_frame.pack(side="left", fill="both", expand=True)

    def _add_login_step_line(parent_f, segments, pady=(0, 2)):
        row = tk.Frame(parent_f, bg="#131922")
        row.pack(fill="x", pady=pady)
        for seg_txt, seg_fg, seg_font, seg_bg in segments:
            tk.Label(
                row,
                text=seg_txt,
                font=seg_font,
                fg=seg_fg,
                bg=seg_bg or "#131922",
                padx=5 if seg_bg else 0,
                pady=1 if seg_bg else 0,
                anchor="w",
            ).pack(side="left")

    _s_fnt = ("Arial", 10, "bold")
    _s_bld = ("Arial", 10, "bold")
    _c_fnt = ("Consolas", 10, "bold")

    _add_login_step_line(
        steps_frame,
        [
            (" STEP 1 ", "#7dd3fc", _c_fnt, "#1a2636"),
            ("  Log into Charles Schwab in the browser window that just opened and click ", "#dce4ee", _s_fnt, None),
            (" Approve ", "#6ee7b7", _c_fnt, "#112a20"),
            (".", "#dce4ee", _s_fnt, None),
        ],
        pady=(0, 4),
    )

    link_lbl = tk.Label(
        steps_frame,
        text="🌐 Click Here to Open / Re-Open the Charles Schwab Login Page in Your Browser ↗",
        font=("Arial", 10, "bold underline"),
        fg="#38bdf8",
        bg="#131922",
        cursor="hand2",
        anchor="w",
    )
    link_lbl.pack(fill="x", padx=8, pady=(0, 8))
    link_lbl.bind("<Button-1>", lambda _e: webbrowser.open(login_url))

    tk.Frame(steps_frame, bg="#222d3d", height=1).pack(fill="x", pady=(0, 8))

    _add_login_step_line(
        steps_frame,
        [
            (" STEP 2 ", "#7dd3fc", _c_fnt, "#1a2636"),
            ("  Your browser will redirect to a blank ", "#dce4ee", _s_fnt, None),
            (" This site can't be reached (127.0.0.1) ", "#fde68a", _c_fnt, "#33220c"),
            (" page — ", "#dce4ee", _s_fnt, None),
            (" 100% Normal! ", "#6ee7b7", _c_fnt, "#112a20"),
        ],
        pady=(0, 8),
    )

    tk.Frame(steps_frame, bg="#222d3d", height=1).pack(fill="x", pady=(0, 8))

    _add_login_step_line(
        steps_frame,
        [
            (" STEP 3 ", "#7dd3fc", _c_fnt, "#1a2636"),
            ("  Copy the full ", "#dce4ee", _s_fnt, None),
            (" https://127.0.0.1/?code=... ", "#6ee7b7", _c_fnt, "#112a20"),
            (" URL from your browser address bar", "#dce4ee", _s_fnt, None),
        ],
        pady=(0, 2),
    )
    _add_login_step_line(
        steps_frame,
        [
            ("           — this window ", "#94a3b8", _s_fnt, None),
            (" auto-detects it directly from your clipboard! ", "#7dd3fc", _s_bld, None),
        ],
        pady=(0, 0),
    )

    tk.Label(
        dlg,
        text="Redirected Browser URL (https://127.0.0.1/?code=...):",
        font=("Arial", 10, "bold"),
        fg="#dce4ee",
        bg="#0d1117",
        anchor="w"
    ).pack(fill="x", pady=(2, 4))

    url_entry = tk.Entry(
        dlg,
        font=("Consolas", 10, "bold"),
        width=74,
        bg="#12202e",
        fg="#e2e8f0",
        insertbackground="#e2e8f0",
        bd=0,
        highlightthickness=1,
        highlightbackground="#294760",
        highlightcolor="#38bdf8"
    )
    url_entry.pack(fill="x", pady=(0, 6), ipady=4)
    url_entry.focus_set()

    status_lbl = tk.Label(
        dlg,
        text="⏳ Waiting for https://127.0.0.1/?code=... URL (auto-fills as soon as you copy it in your browser)...",
        font=("Arial", 9, "bold"),
        fg="#f5b041",
        bg="#0d1117",
        anchor="w"
    )
    status_lbl.pack(fill="x", pady=(0, 10))

    def is_valid_redirect(text):
        t = (text or "").strip()
        return t.startswith("https://127.0.0.1") and "code=" in t

    def paste_from_clipboard():
        try:
            clip = dlg.clipboard_get().strip()
        except Exception:
            clip = ""
        if clip:
            url_entry.delete(0, "end")
            url_entry.insert(0, clip)
            if is_valid_redirect(clip):
                status_lbl.config(
                    text="✓ Valid Schwab redirect URL pasted! Click 'Complete Schwab Login >>' below.",
                    fg="#58d68d"
                )
            else:
                status_lbl.config(
                    text="⚠️ Pasted text does not start with https://127.0.0.1/?code=... — check your browser address bar.",
                    fg="#eb7067"
                )

    clip_after_state = {"id": None}

    def poll_clipboard():
        clip_after_state["id"] = None
        if not dlg.winfo_exists():
            return
        curr = url_entry.get().strip()
        if not is_valid_redirect(curr):
            try:
                clip = dlg.clipboard_get().strip()
                if is_valid_redirect(clip):
                    url_entry.delete(0, "end")
                    url_entry.insert(0, clip)
                    status_lbl.config(
                        text="✓ Redirect URL auto-detected from your clipboard! Click 'Complete Schwab Login >>' below.",
                        fg="#58d68d"
                    )
            except Exception:
                pass
        if dlg.winfo_exists():
            clip_after_state["id"] = dlg.after(450, poll_clipboard)

    clip_after_state["id"] = dlg.after(450, poll_clipboard)

    def _close_schwab_dlg(_event=None):
        aid = clip_after_state.get("id")
        clip_after_state["id"] = None
        if aid is not None:
            try:
                dlg.after_cancel(aid)
            except Exception:
                pass
        try:
            dlg.destroy()
        except Exception:
            pass

    cancel_login = _close_schwab_dlg
    dlg.protocol("WM_DELETE_WINDOW", cancel_login)

    def submit_url(event=None):
        val = url_entry.get().strip()
        if not is_valid_redirect(val):
            messagebox.showwarning(
                "Invalid Redirect URL",
                "Please copy and paste the FULL redirect URL from your browser's address bar.\n\n"
                "It must start with:\nhttps://127.0.0.1/?code=...",
                parent=dlg
            )
            return
        result["url"] = val
        _close_schwab_dlg()

    url_entry.bind("<Return>", submit_url)

    btn_row = tk.Frame(dlg, bg="#0d1117", pady=6)
    btn_row.pack(fill="x")

    make_stadium_button(
        btn_row,
        text="Cancel",
        font=("Arial", 10, "bold"),
        fill_color="#182230",
        border_color="#52657c",
        hover_fill="#223042",
        hover_border="#7a90ad",
        fg="#e2e8f0",
        canvas_bg="#0d1117",
        width=108,
        height=36,
        pad_x=28,
        glow_strength=0.38,
        command=cancel_login,
    ).pack(side="left")

    make_stadium_button(
        btn_row,
        text="📋 Paste from Clipboard",
        font=("Arial", 10, "bold"),
        fill_color="#142942",
        border_color="#38bdf8",
        hover_fill="#1c3859",
        hover_border="#7dd3fc",
        fg="#e0f2fe",
        canvas_bg="#0d1117",
        width=192,
        height=36,
        pad_x=28,
        glow_strength=0.45,
        command=paste_from_clipboard,
    ).pack(side="left", padx=10)

    make_stadium_button(
        btn_row,
        text="Complete Schwab Login >>",
        font=("Arial", 10, "bold"),
        fill_color="#105e35",
        border_color="#22ff88",
        hover_fill="#157a46",
        hover_border="#69f0ae",
        glow_color="#00e676",
        fg="#ffffff",
        canvas_bg="#0d1117",
        width=226,
        height=36,
        pad_x=32,
        glow_strength=0.65,
        command=submit_url,
    ).pack(side="right")

    center_dialog_over_parent(dlg, parent=parent)
    if is_standalone:
        dlg.mainloop()
    else:
        parent.wait_window(dlg)

    if not result["url"]:
        raise RuntimeError(
            "Schwab browser login was cancelled before pasting the redirect URL."
        )
    return result["url"]


def _compute_orders_cache_inv_sig(ad_obj, acct_k):
    """Returns `(pos_sig, settled_eq_sig)` for `acct_k` so `_get_orders_window_cached`,
    `_filled_since_cache`, and `_filled_today_cache` automatically invalidate cached
    `/orders` responses whenever open inventory or settled equity changes (including
    round-trips closed while holding ignored swing positions) between Pre-Flight sync
    and HUD Poll #1."""
    raw_pos_map = getattr(ad_obj, "_last_raw_pos_details", None)
    acct_pos = (
        raw_pos_map.get(acct_k, {})
        if isinstance(raw_pos_map, dict)
        else {}
    )
    pos_sig = tuple(
        sorted(
            (
                str(pk),
                round(float(pv.get("qty", 0.0) or 0.0), 6),
                round(float(pv.get("avg", 0.0) or 0.0), 4),
            )
            for pk, pv in (acct_pos or {}).items()
            if isinstance(pv, dict) and abs(float(pv.get("qty", 0.0) or 0.0)) > 1e-6
        )
    )
    open_pnl_sum = sum(
        float(pv.get("open_pnl", 0.0) or 0.0)
        for pv in (acct_pos or {}).values()
        if isinstance(pv, dict)
    )
    raw_eq_map = getattr(ad_obj, "_last_raw_adj_eq", None)
    raw_eq_v = (
        raw_eq_map.get(acct_k)
        if isinstance(raw_eq_map, dict)
        else None
    )
    settled_eq_sig = (
        (
            round(float(raw_eq_v), 2)
            if not pos_sig
            else round(float(raw_eq_v) - open_pnl_sum, 1)
        )
        if raw_eq_v is not None
        else None
    )
    return (pos_sig, settled_eq_sig)


class SchwabAdapter:
    name = "SCHWAB"

    def __init__(self, app_key, app_secret):
        self.app_key = app_key.strip()
        self.app_secret = app_secret.strip()
        self.client = None
        self.account_id = None
        self.accounts = []
        self._cache_lock = threading.Lock()
        self._orders_fetch_lock = threading.Lock()
        self._snapshot_gen = 0
        self.last_snapshot_was_cached = False
        self._last_flatten_outcome = "FLAT"
        self._post_flatten_opt_verify = None
        self._last_good_snapshot = {}
        self._last_raw_pos_details = {}
        self._last_raw_adj_eq = {}
        self._last_unrounded_true_live_eq = {}
        self._last_flat_rounding_tol = {}
        self._last_bucket_residual = {}
        self._last_bucket_residual_log_ts = 0.0
        self._last_open_eq = {}
        self._last_open_opt = {}
        self._last_intraday_cash_flow = {}
        self._last_snapshot_epoch = {}
        self._filled_since_cache = {}
        self._filled_today_cache = {}
        self._raw_orders_window_cache = {}
        self.last_preserved_close_qty = {}
        self.last_cancel_failed_syms = set()
        self.last_coverage_lookup_failed = False
        self._last_cov_saw_dead_pend = False
        self.last_positions_fetch_ok = False
        self._pending_flatten_cids = {}
        self._logged_short_sign_syms = set()
        self._rate_limit_until = 0.0
        self._last_429_log_ts = 0.0
        self._fast_auth_deferred = False
        self._trade_perm_cache = {}
        self.last_error = ""

    def _ensure_orders_cache_infra(self):
        if not hasattr(self, "_cache_lock") or self._cache_lock is None:
            self._cache_lock = threading.Lock()
        if not hasattr(self, "_orders_fetch_lock") or self._orders_fetch_lock is None:
            self._orders_fetch_lock = threading.Lock()
        if not hasattr(self, "_snapshot_gen"):
            self._snapshot_gen = 0
        if not isinstance(getattr(self, "_raw_orders_window_cache", None), dict):
            self._raw_orders_window_cache = {}
        if not isinstance(getattr(self, "_filled_since_cache", None), dict):
            self._filled_since_cache = {}
        if not isinstance(getattr(self, "_filled_today_cache", None), dict):
            self._filled_today_cache = {}

    def invalidate_cached_snapshots(self):
        self._ensure_orders_cache_infra()
        with self._cache_lock:
            self._snapshot_gen += 1
            self._last_good_snapshot.clear()
            self._last_open_eq.clear()
            self._last_open_opt.clear()
            self._filled_since_cache.clear()
            self._filled_today_cache.clear()
            self._raw_orders_window_cache.clear()

    def _prune_pending_flatten_cids(self, acct_id, live_qty_map):
        if not acct_id or not self._pending_flatten_cids:
            return
        now_ts = time.time()
        for k in list(self._pending_flatten_cids.keys()):
            if k[0] != acct_id:
                continue
            sym = k[1]
            pend = self._pending_flatten_cids.get(k)
            if not pend or (now_ts - float(pend[1])) >= 15.0:
                self._pending_flatten_cids.pop(k, None)
                continue
            pre_pos_q = float(pend[3]) if len(pend) > 3 else float(pend[2])
            curr_q = float(live_qty_map.get(sym, 0.0))
            if abs(curr_q) > 1e-6 and abs(curr_q - pre_pos_q) > 1e-6:
                self._pending_flatten_cids.pop(k, None)

    def get_last_raw_pos_details(self):
        return json.loads(
            json.dumps(self._last_raw_pos_details.get(self.account_id, {}))
        )

    def get_last_raw_positions_snapshot(self):
        return self.get_last_raw_pos_details(), self.get_last_raw_adj_eq()

    def get_last_raw_adj_eq(self):
        val = self._last_raw_adj_eq.get(self.account_id)
        return float(val) if val is not None else None

    def get_last_true_live_eq(self):
        val = self._last_unrounded_true_live_eq.get(self.account_id)
        if val is not None:
            return float(val)
        return self.get_last_raw_adj_eq()

    def get_flat_rounding_tolerance(self):
        return float(self._last_flat_rounding_tol.get(self.account_id, 0.0))

    def get_last_intraday_cash_flow(self):
        return float(self._last_intraday_cash_flow.get(self.account_id, 0.0))

    def get_last_snapshot_epoch(self):
        snap_map = getattr(self, "_last_snapshot_epoch", None)
        if isinstance(snap_map, dict):
            return float(snap_map.get(self.account_id, 0.0) or 0.0)
        if isinstance(snap_map, (int, float)):
            return float(snap_map)
        return 0.0

    def get_cached_trading_permission(self):
        entry = self._trade_perm_cache.get(self.account_id)
        if isinstance(entry, tuple) and len(entry) >= 2:
            if (
                len(entry) >= 3
                and entry[0] != "VERIFIED"
                and (time.time() - float(entry[2])) > 120.0
            ):
                self._trade_perm_cache.pop(self.account_id, None)
            else:
                return entry[0], entry[1]
        return ("UNCONFIRMED", "")

    def check_trading_permission_preview(self, force=False):
        """Runs a non-destructive 1-share DAY Limit BUY of SPY @ $1.00 preview
        probe via client.preview_order() and returns a 3-state tuple:
        ('VERIFIED' | 'BLOCKED' | 'UNCONFIRMED', detail_str)."""
        if not self.account_id or self.client is None or not hasattr(self.client, "preview_order"):
            return ("UNCONFIRMED", "Broker client or preview_order endpoint unavailable.")
        if not force:
            entry = self._trade_perm_cache.get(self.account_id)
            if isinstance(entry, tuple) and len(entry) >= 2:
                if (
                    len(entry) >= 3
                    and entry[0] != "VERIFIED"
                    and (time.time() - float(entry[2])) > 120.0
                ):
                    self._trade_perm_cache.pop(self.account_id, None)
                else:
                    return entry[0], entry[1]
        order_spec = {
            "session": "NORMAL",
            "duration": "DAY",
            "orderType": "LIMIT",
            "price": "1.00",
            "orderLegCollection": [
                {
                    "instruction": "BUY",
                    "instrument": {"assetType": "EQUITY", "symbol": "SPY"},
                    "quantity": 1,
                }
            ],
            "orderStrategyType": "SINGLE",
        }
        try:
            try:
                resp = self.client.preview_order(self.account_id, order_spec)
            except Exception as inner_e:
                if (
                    "token_invalid" in str(inner_e).lower()
                    and self.reconnect_session()
                ):
                    resp = self.client.preview_order(self.account_id, order_spec)
                else:
                    raise
            if getattr(resp, "status_code", None) == 401 and self.reconnect_session():
                resp = self.client.preview_order(self.account_id, order_spec)
            code = getattr(resp, "status_code", None)
            txt = ""
            try:
                txt = str(getattr(resp, "text", "") or "")
            except Exception:
                txt = ""
            state, detail = _classify_preview_order_result(
                http_status=code, body_text=txt
            )
        except Exception as e:
            state, detail = _classify_preview_order_result(
                http_status=None, body_text=str(e)
            )
        self._trade_perm_cache[self.account_id] = (state, detail, time.time())
        log_event(
            "SESSION",
            f"Schwab Trade API permission preview check: {state} ({detail[:100]})",
        )
        return state, detail

    def verify_accounts_live(self):
        """Verifies live Schwab API connectivity and refreshes self.accounts."""
        try:
            if self.client is None:
                return False
            try:
                resp = self.client.get_account_numbers()
            except Exception as inner_e:
                if (
                    "token_invalid" in str(inner_e).lower()
                    and self.reconnect_session()
                ):
                    resp = self.client.get_account_numbers()
                else:
                    raise
            if resp.status_code == 200:
                self._parse_accounts(resp.json())
                self._fast_auth_deferred = False
                return True
        except Exception as e:
            self.last_error = str(e)
        return False

    def authenticate(self, fast_cached_accounts=None, allow_interactive_oauth=True):
        try:
            from schwab.auth import client_from_manual_flow, client_from_token_file
        except ImportError:
            if not allow_interactive_oauth:
                raise DeferredAuthRequired(
                    "Schwab SDK (schwab-py) not installed — deferred during startup boot."
                )
            print("[SETUP] Installing required Schwab SDK (schwab-py)...")
            py_cli = sys.executable
            if py_cli.lower().endswith("pythonw.exe"):
                cand_py = py_cli[:-5] + ".exe"
                if os.path.exists(cand_py):
                    py_cli = cand_py
            subprocess.run(
                [
                    py_cli,
                    "-m",
                    "pip",
                    "install",
                    "--upgrade",
                    "schwab-py==1.5.1",
                    "authlib==1.8.0",
                    "httpx==0.28.1",
                ],
                check=False
            )
            from schwab.auth import client_from_manual_flow, client_from_token_file
        try:
            if os.path.exists(SCHWAB_TOKEN_PATH):
                rem_hrs = get_schwab_token_remaining_hours()
                if rem_hrs is not None and rem_hrs < 14.0:
                    if not allow_interactive_oauth:
                        raise DeferredAuthRequired(
                            f"Schwab sign-in needs a refresh ({max(0.0, rem_hrs):.1f}h left) — click API Keys / Reconnect when ready."
                        )
                    raise RuntimeError(
                        f"Schwab 7-day token has {max(0.0, rem_hrs):.1f}h remaining "
                        f"(<14h safety buffer) — refreshing proactively before session"
                    )
                self.client = client_from_token_file(
                    SCHWAB_TOKEN_PATH, self.app_key, self.app_secret
                )
                try:
                    self.client.set_timeout(4.5)
                except Exception:
                    pass
                if (
                    fast_cached_accounts
                    and isinstance(fast_cached_accounts, list)
                ):
                    self.accounts = [
                        dict(a)
                        for a in fast_cached_accounts
                        if isinstance(a, dict) and a.get("id")
                    ]
                    if self.accounts:
                        self._fast_auth_deferred = True
                        return True
                resp = self.client.get_account_numbers()
                if resp.status_code == 200:
                    self._parse_accounts(resp.json())
                    self._fast_auth_deferred = False
                    return True
                if resp.status_code in (400, 401, 403):
                    raise RuntimeError(
                        f"Schwab token rejected (HTTP {resp.status_code})"
                    )
                raise ConnectionError(
                    f"Schwab API temporary HTTP {resp.status_code}"
                )
        except Exception as e:
            if isinstance(e, DeferredAuthRequired):
                raise
            err_l = str(e).lower()
            tok_invalid_keys = [
                "safety buffer",
                "invalid_grant",
                "unsupported_token_type",
                "token rejected",
                "expired",
                "unauthorized",
                "http 401",
                "http 400",
            ]
            if allow_interactive_oauth:
                tok_invalid_keys.append("jsondecodeerror")
            is_token_invalid = any(k in err_l for k in tok_invalid_keys)
            if not is_token_invalid:
                log_event(
                    "WARN",
                    f"Schwab network/connection error during startup ({e}). "
                    f"Preserving saved token file.",
                )
                raise RuntimeError(
                    f"Network connection failed while reaching Schwab API ({e}).\n"
                    f"Your saved 7-day token was preserved — please check your internet connection and retry."
                ) from e
            if not allow_interactive_oauth:
                log_event(
                    "SESSION",
                    f"Saved Schwab token needs refresh ({e}); deferring interactive OAuth during startup boot.",
                )
                raise DeferredAuthRequired(
                    "Schwab sign-in needs a refresh — click API Keys / Reconnect when ready."
                ) from e
            log_event(
                "SESSION",
                f"Saved Schwab token expired or invalid ({e}). "
                f"Starting fresh OAuth flow..."
            )
            if os.path.exists(SCHWAB_TOKEN_PATH):
                try:
                    os.remove(SCHWAB_TOKEN_PATH)
                except Exception:
                    pass

        if not allow_interactive_oauth:
            raise DeferredAuthRequired(
                "Schwab sign-in required — click API Keys / Reconnect when ready."
            )

        print("\n=======================================================")
        print("  SCHWAB OAUTH LOGIN — OPENING BROWSER & PASTE DIALOG")
        print("=======================================================\n")

        opened = {"done": False, "url": ""}

        def try_open_url(text):
            match = re.search(
                r"(https://api\.schwabapi\.com/v1/oauth/authorize\S+)",
                str(text)
            )
            if match:
                opened["url"] = match.group(1)
                if not opened["done"]:
                    opened["done"] = True
                    webbrowser.open(opened["url"])

        class BrowserLogHandler(logging.Handler):
            def emit(self, record):
                try_open_url(record.getMessage())

        handler = BrowserLogHandler()
        logging.getLogger().addHandler(handler)
        orig_print = builtins.print
        orig_input = builtins.input

        def hooked_print(*args, **kwargs):
            orig_print(*args, **kwargs)
            try_open_url(" ".join(str(a) for a in args))

        def hooked_input(prompt=""):
            if prompt:
                orig_print(prompt)
                try_open_url(prompt)
            return prompt_schwab_oauth_url_dialog(opened.get("url", ""))

        builtins.print = hooked_print
        builtins.input = hooked_input
        try:
            self.client = client_from_manual_flow(
                self.app_key, self.app_secret, CALLBACK_URL, SCHWAB_TOKEN_PATH
            )
            if os.path.exists(SCHWAB_TOKEN_PATH):
                try:
                    self.client = client_from_token_file(
                        SCHWAB_TOKEN_PATH, self.app_key, self.app_secret
                    )
                except Exception:
                    pass
            try:
                self.client.set_timeout(4.5)
            except Exception:
                pass
        finally:
            builtins.print = orig_print
            builtins.input = orig_input
            logging.getLogger().removeHandler(handler)

        resp = self.client.get_account_numbers()
        if resp.status_code == 200:
            self._parse_accounts(resp.json())
            return True
        raise RuntimeError(
            f"Schwab get_account_numbers failed: HTTP {resp.status_code}"
        )

    def reconnect_session(self):
        """Rebuilds the underlying Schwab HTTP client from SCHWAB_TOKEN_PATH
        with a 4.5s timeout to flush stale TCP sockets after an internet drop."""
        try:
            if os.path.exists(SCHWAB_TOKEN_PATH):
                from schwab.auth import client_from_token_file
                new_client = client_from_token_file(
                    SCHWAB_TOKEN_PATH, self.app_key, self.app_secret
                )
                try:
                    new_client.set_timeout(4.5)
                except Exception:
                    pass
                self.client = new_client
                self._ensure_orders_cache_infra()
                with self._cache_lock:
                    self._snapshot_gen += 1
                    self._raw_orders_window_cache.clear()
                    self._filled_since_cache.clear()
                    self._filled_today_cache.clear()
                self._trade_perm_cache.pop(self.account_id, None)
                return True
        except Exception as e:
            self.last_error = str(e)
        return False

    def _parse_accounts(self, acct_list):
        self.accounts = []
        for item in acct_list:
            acc_num = str(item.get("accountNumber", ""))
            h_val = str(item.get("hashValue", ""))
            masked = f"...{acc_num[-4:]}" if len(acc_num) >= 4 else acc_num
            self.accounts.append({
                "id": h_val,
                "label": f"Schwab Account {masked}"
            })
        if self.accounts and not self.account_id:
            self.account_id = self.accounts[0]["id"]

    @staticmethod
    def _extract_schwab_order_id(resp):
        try:
            hdrs = getattr(resp, "headers", None) or {}
            loc = str(
                hdrs.get("location") or hdrs.get("Location") or ""
            ).strip()
            if loc:
                m = re.search(r"/orders/([^/?#]+)", loc)
                if m:
                    return m.group(1)
        except Exception:
            pass
        return ""

    @staticmethod
    def _order_ts_to_epoch(raw_ts):
        s = str(raw_ts or "").strip()
        if not s:
            return 0.0
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            elif re.search(r"[+-]\d{4}$", s):
                s = s[:-2] + ":" + s[-2:]
            dt = datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return float(dt.timestamp())
        except Exception:
            return 0.0

    def get_recent_exit_order_coverage(
        self, symbol, is_short=False, since_epoch=None, is_opt=False
    ):
        """Checks Schwab orders in UTC over the last 5 minutes for `symbol` in the
        closing direction. Returns (working_qty, recent_filled_qty) so post-timeout
        sweeps never double-submit an exit order that is already working or filled."""
        self.last_coverage_lookup_failed = False
        self._last_cov_saw_dead_pend = False
        if not self.client or not self.account_id or not symbol:
            self.last_coverage_lookup_failed = True
            return 0.0, 0.0
        now_utc = datetime.now(timezone.utc)
        lookback_sec = (
            max(1800.0, (time.time() - float(since_epoch)) + 120.0)
            if since_epoch is not None
            else 1800.0
        )
        from_utc = now_utc - timedelta(seconds=lookback_sec)
        try:
            try:
                resp = self.client.get_orders_for_account(
                    self.account_id,
                    from_entered_datetime=from_utc,
                    to_entered_datetime=now_utc,
                )
            except TypeError:
                resp = self.client.get_orders_for_account(self.account_id)
            if resp.status_code != 200:
                self.last_coverage_lookup_failed = True
                return 0.0, 0.0
            orders = resp.json()
            if not isinstance(orders, list):
                self.last_coverage_lookup_failed = True
                return 0.0, 0.0
        except Exception:
            self.last_coverage_lookup_failed = True
            return 0.0, 0.0

        active_statuses = {
            "WORKING",
            "QUEUED",
            "PENDING_ACTIVATION",
            "ACCEPTED",
            "NEW",
            "AWAITING_PARENT_ORDER",
            "AWAITING_CONDITION",
            "AWAITING_STOP_CONDITION",
            "AWAITING_MANUAL_REVIEW",
            "AWAITING_UR_OUT",
            "AWAITING_RELEASE_TIME",
            "PENDING_ACKNOWLEDGEMENT",
        }
        dead_statuses = {
            "CANCELED",
            "CANCELLED",
            "REJECTED",
            "EXPIRED",
            "REPLACED",
        }
        closing_instrs = (
            {"BUY", "BUY_TO_COVER", "BUY_TO_CLOSE"}
            if is_short
            else {"SELL", "SELL_TO_CLOSE"}
        )
        cutoff_epoch = (
            float(math.floor(float(since_epoch)))
            if since_epoch is not None
            else (time.time() - 180.0)
        )
        target_sym = str(symbol).strip()
        pend = self._pending_flatten_cids.get((self.account_id, target_sym))
        pend_oid = str(pend[0]).strip() if (pend and pend[0]) else ""
        working_qty = 0.0
        oco_groups = {}
        filled_qty = 0.0
        cov_seen_oids = set()

        def _flat_cov_orders(ord_list, oco_gid=None):
            out_items = []
            for item_o in ord_list or []:
                if not isinstance(item_o, dict):
                    continue
                oid_c = str(item_o.get("orderId") or "").strip()
                if oid_c:
                    if oid_c in cov_seen_oids:
                        continue
                    cov_seen_oids.add(oid_c)
                st_c = str(item_o.get("status") or "").upper()
                children_c = item_o.get("childOrderStrategies")
                strat_t = str(item_o.get("orderStrategyType") or "").upper()
                if item_o.get("orderLegCollection"):
                    out_items.append((item_o, oco_gid))
                if isinstance(children_c, list) and children_c:
                    if st_c in active_statuses and oid_c and strat_t != "OCO":
                        continue
                    next_gid = (
                        f"SC_COV_OCO_{oid_c or id(item_o)}"
                        if (strat_t == "OCO" or len(children_c) > 1)
                        else oco_gid
                    )
                    out_items.extend(_flat_cov_orders(children_c, next_gid))
            return out_items

        for o, sc_oco_gid in _flat_cov_orders(orders, None):
            st = str(o.get("status") or "").upper()
            oid_str = str(o.get("orderId") or "").strip()
            legs = o.get("orderLegCollection") or []
            if len(legs) != 1 or not isinstance(legs[0], dict):
                continue
            lg = legs[0]
            inst = lg.get("instrument") or {}
            leg_sym = str(inst.get("symbol") or "").strip()
            if leg_sym != target_sym:
                continue
            leg_atype = str(inst.get("assetType") or "").upper()
            if is_opt and leg_atype != "OPTION":
                continue
            if not is_opt and leg_atype == "OPTION":
                continue
            instr = str(lg.get("instruction") or "").upper()
            if instr not in closing_instrs:
                continue
            if pend_oid and oid_str == pend_oid and st in dead_statuses:
                self._last_cov_saw_dead_pend = True
            try:
                f_q = float(o.get("filledQuantity") or 0.0)
            except Exception:
                f_q = 0.0
            try:
                raw_leg_q = (
                    lg["quantity"]
                    if lg.get("quantity") is not None
                    else o.get("quantity")
                )
                leg_orig_q = float(raw_leg_q) if raw_leg_q is not None else 0.0
            except Exception:
                leg_orig_q = 0.0
            try:
                rem_q = float(
                    o.get("remainingQuantity")
                    if o.get("remainingQuantity") is not None
                    else max(0.0, leg_orig_q - f_q)
                )
            except Exception:
                rem_q = 0.0

            recent_f_q = 0.0
            has_fill_ts = False
            if f_q > 0:
                exec_leg_eps = []
                exec_recent_sum = 0.0
                exec_has_qty = False
                for act in o.get("orderActivityCollection") or []:
                    if not isinstance(act, dict):
                        continue
                    for ex_leg in act.get("executionLegs") or []:
                        if not isinstance(ex_leg, dict):
                            continue
                        ex_ep = self._order_ts_to_epoch(ex_leg.get("time"))
                        if ex_ep > 0.0:
                            exec_leg_eps.append(ex_ep)
                            raw_ex_q = ex_leg.get("quantity")
                            if raw_ex_q is not None:
                                try:
                                    ex_qv = float(raw_ex_q)
                                    exec_has_qty = True
                                    if ex_ep >= cutoff_epoch:
                                        exec_recent_sum += ex_qv
                                except Exception:
                                    pass
                if exec_leg_eps:
                    has_fill_ts = True
                    if exec_has_qty:
                        recent_f_q = min(f_q, exec_recent_sum)
                    elif max(exec_leg_eps) >= cutoff_epoch:
                        recent_f_q = f_q
                elif pend_oid and oid_str == pend_oid:
                    has_fill_ts = True
                    recent_f_q = f_q
                elif o.get("closeTime") is not None:
                    ep_c = self._order_ts_to_epoch(o.get("closeTime"))
                    if ep_c > 0.0:
                        has_fill_ts = True
                        if ep_c >= cutoff_epoch:
                            recent_f_q = f_q
                elif st == "FILLED" and o.get("enteredTime") is not None:
                    ep_e = self._order_ts_to_epoch(o.get("enteredTime"))
                    if ep_e > 0.0:
                        has_fill_ts = True
                        if ep_e >= cutoff_epoch:
                            recent_f_q = f_q

            if sc_oco_gid:
                b = oco_groups.setdefault(
                    sc_oco_gid,
                    {
                        "init_max": 0.0,
                        "work_max": 0.0,
                        "filled_all": 0.0,
                        "filled_recent": 0.0,
                        "all_fills_timed": True,
                    },
                )
                b["init_max"] = max(
                    b["init_max"],
                    leg_orig_q,
                    f_q + (rem_q if st in active_statuses else 0.0),
                )
                if st in active_statuses and rem_q > 0:
                    b["work_max"] = max(b["work_max"], rem_q)
                if f_q > 0:
                    if has_fill_ts:
                        b["filled_all"] += f_q
                        b["filled_recent"] += recent_f_q
                    else:
                        b["all_fills_timed"] = False
            else:
                if st in active_statuses and rem_q > 0:
                    working_qty += rem_q
                if f_q > 0:
                    if has_fill_ts:
                        filled_qty += recent_f_q
                    else:
                        ent_ep = self._order_ts_to_epoch(
                            o.get("closeTime") or o.get("enteredTime")
                        )
                        if (
                            (pend_oid and oid_str == pend_oid)
                            or ent_ep <= 0.0
                            or ent_ep >= cutoff_epoch
                        ):
                            filled_qty += f_q

        for b in oco_groups.values():
            i_max = b["init_max"]
            if b["all_fills_timed"] and i_max > 0:
                grp_working = min(
                    b["work_max"], max(0.0, i_max - b["filled_all"])
                )
                grp_filled_rec = min(b["filled_recent"], i_max)
            else:
                grp_working = min(b["work_max"], i_max) if i_max > 0 else b["work_max"]
                grp_filled_rec = (
                    min(b["filled_recent"], i_max) if i_max > 0 else b["filled_recent"]
                )
            working_qty += grp_working
            filled_qty += grp_filled_rec
        return working_qty, filled_qty

    def cancel_all_working_orders(
        self, preserve_market_close_map=None, cancel_options=True
    ):
        self.last_preserved_close_qty = {}
        self.last_cancel_failed_syms = set()
        cl = self.client
        acct_id = self.account_id
        if not cl or not acct_id:
            return False
        preserve_map = (
            dict(preserve_market_close_map)
            if isinstance(preserve_market_close_map, dict)
            else {}
        )
        now_utc = datetime.now(timezone.utc)
        raw_batches = []
        step1_ok = False
        step2_ok = False
        last_http_err = None

        # Step 1: Fast 120-hour (5-day, weekend-safe) query covering all active statuses & OCO children
        try:
            fast_start = now_utc - timedelta(hours=120)
            try:
                resp1 = cl.get_orders_for_account(
                    acct_id,
                    from_entered_datetime=fast_start,
                    to_entered_datetime=now_utc,
                )
            except (TypeError, ValueError):
                resp1 = cl.get_orders_for_account(acct_id)
            if getattr(resp1, "status_code", None) == 200:
                j1 = resp1.json()
                if isinstance(j1, list):
                    raw_batches.append(j1)
                    step1_ok = True
            else:
                last_http_err = getattr(resp1, "status_code", None)
        except Exception as e1:
            log_event(
                "ERROR",
                f"Schwab get_orders_for_account (120h) exception during cancel: {e1}",
            )

        # Step 2: Thread-bounded 58-day server-filtered WORKING GTC sweep (never mutates shared cl timeout)
        ord_status_enum = getattr(getattr(cl, "Order", None), "Status", None)
        working_enum_val = getattr(ord_status_enum, "WORKING", None)
        if working_enum_val is not None:
            s2_box = {"list": None, "code": None, "err": None, "type_err": False}
            gtc_start = now_utc - timedelta(days=58)

            def _run_s2():
                try:
                    r2 = cl.get_orders_for_account(
                        acct_id,
                        from_entered_datetime=gtc_start,
                        to_entered_datetime=now_utc,
                        status=working_enum_val,
                    )
                    s2_box["code"] = getattr(r2, "status_code", None)
                    if s2_box["code"] == 200:
                        j2 = r2.json()
                        if isinstance(j2, list):
                            s2_box["list"] = j2
                except TypeError:
                    s2_box["type_err"] = True
                except Exception as ex2:
                    s2_box["err"] = ex2

            t_s2 = threading.Thread(target=_run_s2, daemon=True)
            t_s2.start()
            t_s2.join(2.2)
            if isinstance(s2_box["list"], list):
                raw_batches.append(s2_box["list"])
                step2_ok = True
            elif not s2_box["type_err"]:
                self.last_coverage_lookup_failed = True
                s2_reason = (
                    "2.2s timeout"
                    if t_s2.is_alive()
                    else (
                        str(s2_box["err"])
                        if s2_box["err"] is not None
                        else f"HTTP {s2_box['code']}"
                    )
                )
                if not step1_ok:
                    if s2_box["code"] is not None:
                        last_http_err = s2_box["code"]
                    log_event(
                        "ERROR",
                        f"Schwab get_orders_for_account (58d WORKING) failed during cancel: {s2_reason}",
                    )
                else:
                    log_event(
                        "WARN",
                        f"Schwab 58d WORKING GTC order sweep incomplete ({s2_reason}); proceeding with 120h order set.",
                    )

        if not step1_ok and not step2_ok:
            if last_http_err is not None:
                log_event(
                    "ERROR",
                    f"Failed to query working orders: HTTP {last_http_err}",
                )
            return False

        active_statuses = {
            "WORKING",
            "QUEUED",
            "PENDING_ACTIVATION",
            "ACCEPTED",
            "NEW",
            "AWAITING_PARENT_ORDER",
            "AWAITING_CONDITION",
            "AWAITING_STOP_CONDITION",
            "AWAITING_MANUAL_REVIEW",
            "AWAITING_UR_OUT",
            "AWAITING_RELEASE_TIME",
            "PENDING_ACKNOWLEDGEMENT",
        }
        terminal_cascade_statuses = {
            "CANCELED",
            "CANCELLED",
            "PENDING_CANCEL",
            "FILLED",
            "EXPIRED",
            "REJECTED",
        }

        candidates = []
        seen_oids = set()
        seen_ptrs = set()

        def _collect_cancel_candidates(ord_list, oco_gid=None):
            for item_o in ord_list or []:
                if not isinstance(item_o, dict):
                    continue
                oid_s = str(item_o.get("orderId") or "").strip()
                if oid_s:
                    if oid_s in seen_oids:
                        continue
                    seen_oids.add(oid_s)
                else:
                    ptr_i = id(item_o)
                    if ptr_i in seen_ptrs:
                        continue
                    seen_ptrs.add(ptr_i)
                st_s = str(item_o.get("status") or "").upper()
                children = item_o.get("childOrderStrategies")
                if st_s in active_statuses and oid_s:
                    # Active parent/container has its own orderId; canceling it cascades to its children
                    candidates.append((item_o, oco_gid))
                elif isinstance(children, list) and children:
                    next_gid = (
                        f"SC_OCO_{oid_s or id(item_o)}"
                        if len(children) > 1
                        else oco_gid
                    )
                    _collect_cancel_candidates(children, next_gid)

        for batch in raw_batches:
            _collect_cancel_candidates(batch, None)

        cancelled_any = False
        preserved_any = False
        cancelled_oco_groups = set()
        for order, oco_gid in candidates:
            status = str(order.get("status") or "").upper()
            if status not in active_statuses:
                continue
            order_id = order.get("orderId")
            masked_oid = _mask_last4(order_id)
            legs = [
                lg
                for lg in (order.get("orderLegCollection") or [])
                if isinstance(lg, dict)
            ]
            if legs and all(
                is_position_ignored(
                    (lg.get("instrument") or {}).get("symbol", ""),
                    is_opt=(
                        str(
                            (lg.get("instrument") or {}).get(
                                "assetType", ""
                            )
                        ).upper()
                        == "OPTION"
                    ),
                )
                or (
                    not _manual_flatten_in_flight
                    and is_launch_grace_position(
                        (lg.get("instrument") or {}).get("symbol", ""),
                        is_opt=(
                            str(
                                (lg.get("instrument") or {}).get(
                                    "assetType", ""
                                )
                            ).upper()
                            == "OPTION"
                        ),
                    )
                )
                for lg in legs
            ):
                leg_syms = [
                    (lg.get("instrument") or {}).get("symbol", "")
                    for lg in legs
                ]
                log_event(
                    "FLATTEN",
                    f"Skipping working order {masked_oid} on ignored pre-existing ticker(s): {leg_syms}",
                )
                continue

            if not cancel_options and legs:
                all_opt_closing = all(
                    str(
                        (lg.get("instrument") or {}).get(
                            "assetType", ""
                        )
                    ).upper()
                    == "OPTION"
                    and str(lg.get("instruction") or "").upper()
                    in ("SELL_TO_CLOSE", "BUY_TO_CLOSE")
                    for lg in legs
                )
                if all_opt_closing:
                    preserved_any = True
                    log_event(
                        "FLATTEN",
                        f"Preserving protective/closing option order {masked_oid} ({status}) — "
                        f"Options Auto-Flatten not active for this sweep.",
                    )
                    continue

            order_type = str(order.get("orderType") or "").upper()
            single_leg = legs[0] if len(legs) == 1 else None
            leg_sym = (
                str(
                    (single_leg.get("instrument") or {}).get(
                        "symbol", ""
                    )
                ).strip()
                if single_leg
                else ""
            )
            leg_instr = (
                str(single_leg.get("instruction") or "").upper()
                if single_leg
                else ""
            )
            try:
                rem_q = float(
                    order.get("remainingQuantity")
                    or (single_leg or {}).get("quantity")
                    or order.get("quantity")
                    or 0.0
                )
            except Exception:
                rem_q = 0.0

            is_closing_dir = False
            if leg_sym and leg_sym in preserve_map:
                open_q = float(preserve_map[leg_sym])
                if open_q > 0 and leg_instr in (
                    "SELL",
                    "SELL_TO_CLOSE",
                ):
                    is_closing_dir = True
                elif open_q < 0 and leg_instr in (
                    "BUY",
                    "BUY_TO_COVER",
                    "BUY_TO_CLOSE",
                ):
                    is_closing_dir = True

            if (
                is_closing_dir
                and is_market_hours()
                and order_type == "MARKET"
            ):
                eff_q = rem_q if rem_q > 0 else abs(float(preserve_map[leg_sym]))
                self.last_preserved_close_qty[leg_sym] = (
                    self.last_preserved_close_qty.get(leg_sym, 0.0)
                    + eff_q
                )
                preserved_any = True
                log_event(
                    "FLATTEN",
                    f"Preserving working Schwab RTH Market close order {masked_oid} "
                    f"({leg_instr} {eff_q:g} {leg_sym}, {status}) — "
                    f"keeping halt/auction queue priority.",
                )
                continue

            log_event(
                "FLATTEN",
                f"Canceling Schwab order ID: {masked_oid} ({status})"
            )
            cancel_ok = False
            try:
                c_resp = cl.cancel_order(order_id, acct_id)
                c_code = getattr(c_resp, "status_code", None)
                log_event(
                    "FLATTEN",
                    f"Cancel response {masked_oid}: HTTP {c_code}"
                )
                if c_code in (200, 201, 202, 204):
                    cancelled_any = True
                    cancel_ok = True
                    if oco_gid:
                        cancelled_oco_groups.add(oco_gid)
                elif (
                    c_code in (400, 404, 409, 422)
                    and oco_gid
                    and oco_gid in cancelled_oco_groups
                ):
                    get_ord_fn = getattr(cl, "get_order", None)
                    cascade_confirmed = False
                    if callable(get_ord_fn):
                        try:
                            g_resp = get_ord_fn(order_id, acct_id)
                            if getattr(g_resp, "status_code", None) == 200:
                                g_st = str(
                                    (g_resp.json() or {}).get("status") or ""
                                ).upper()
                                cascade_confirmed = g_st in terminal_cascade_statuses
                        except Exception:
                            cascade_confirmed = False
                    else:
                        cascade_confirmed = True
                    if cascade_confirmed:
                        cancel_ok = True
                        log_event(
                            "FLATTEN",
                            f"Schwab order {masked_oid} already cascade-canceled via OCO sibling.",
                        )
            except Exception as ce:
                log_event(
                    "ERROR",
                    f"Schwab cancel_order {masked_oid} exception: {ce}",
                )
            if not cancel_ok:
                for lg in legs:
                    s_nm = str(
                        (lg.get("instrument") or {}).get(
                            "symbol", ""
                        )
                    ).strip()
                    if s_nm:
                        self.last_cancel_failed_syms.add(s_nm)
                if is_closing_dir and leg_sym:
                    eff_q = (
                        rem_q
                        if rem_q > 0
                        else abs(float(preserve_map[leg_sym]))
                    )
                    self.last_preserved_close_qty[leg_sym] = (
                        self.last_preserved_close_qty.get(leg_sym, 0.0)
                        + eff_q
                    )
        if cancelled_any:
            time.sleep(0.2)
        elif not preserved_any:
            log_event("FLATTEN", "No working orders found to cancel.")
        return cancelled_any

    @staticmethod
    def _order_ts_to_eastern_date(raw_ts):
        """Converts an ISO-8601 Schwab order timestamp (e.g. '2026-11-12T20:28:18+0000')
        into a YYYY-MM-DD date string in US/Eastern time."""
        s = str(raw_ts or "").strip()
        if not s:
            return ""
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            elif re.search(r"[+-]\d{4}$", s):
                s = s[:-2] + ":" + s[-2:]
            dt = datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return _utc_to_eastern_naive(dt).strftime("%Y-%m-%d")
        except Exception:
            return s[:10]

    def _get_orders_window_cached(self, window_tag="58d", ttl_sec=8.0):
        """Coalesces concurrent Schwab order-history queries behind a timeout-
        bounded single-flight lock and caches the raw JSON list for `ttl_sec`
        seconds keyed by `(account_id, _snapshot_gen, window_tag)` so
        Pre-Flight sync, fee-drift checks, and data_loop Poll #1 share one
        fetch while `reconnect_session()` / `invalidate_cached_snapshots()`
        always isolate stale responses."""
        self._ensure_orders_cache_infra()
        if not self.client or not self.account_id:
            return None
        win_tag = "36h" if str(window_tag) == "36h" else "58d"

        def _lookup_cached_locked(
            acct_k, gen_k, cl_obj, inv_sig, cur_snap_ep, now_t
        ):
            cand = self._raw_orders_window_cache.get((acct_k, gen_k, win_tag))
            if cand is None and win_tag == "36h":
                cand = self._raw_orders_window_cache.get((acct_k, gen_k, "58d"))
            if (
                isinstance(cand, tuple)
                and len(cand) >= 7
                and (now_t - float(cand[0])) < float(ttl_sec)
                and cand[2] is cl_obj
                and cand[3] is self._filled_since_cache
                and cand[4] is self._filled_today_cache
                and cand[5] == inv_sig
                and (
                    cur_snap_ep <= 0.0
                    or float(cand[1]) <= 0.0
                    or abs(cur_snap_ep - float(cand[1])) < float(ttl_sec)
                )
            ):
                return list(cand[6])
            return None

        acct_cur = str(self.account_id)
        inv_sig_cur = _compute_orders_cache_inv_sig(self, acct_cur)
        snap_ep_cur = self.get_last_snapshot_epoch()
        with self._cache_lock:
            hit = _lookup_cached_locked(
                acct_cur,
                self._snapshot_gen,
                self.client,
                inv_sig_cur,
                snap_ep_cur,
                time.time(),
            )
        if hit is not None:
            return hit

        acquired = self._orders_fetch_lock.acquire(timeout=6.0)
        try:
            with self._cache_lock:
                gen_before = self._snapshot_gen
                cl_before = self.client
                acct_before = str(self.account_id or "")
                fs_before = self._filled_since_cache
                ft_before = self._filled_today_cache
                inv_sig_before = _compute_orders_cache_inv_sig(self, acct_before)
                snap_ep_before = self.get_last_snapshot_epoch()
                hit2 = _lookup_cached_locked(
                    acct_before,
                    gen_before,
                    cl_before,
                    inv_sig_before,
                    snap_ep_before,
                    time.time(),
                )
            if hit2 is not None:
                return hit2
            if not cl_before or not acct_before:
                return None

            now_utc = datetime.now(timezone.utc)
            from_dt = (
                now_utc - timedelta(hours=36)
                if win_tag == "36h"
                else now_utc - timedelta(days=58)
            )
            to_dt = now_utc + timedelta(hours=1)
            t0 = time.monotonic()
            try:
                resp = cl_before.get_orders_for_account(
                    acct_before,
                    from_entered_datetime=from_dt,
                    to_entered_datetime=to_dt,
                    max_results=3000,
                )
            except TypeError:
                try:
                    resp = cl_before.get_orders_for_account(
                        acct_before,
                        from_entered_datetime=from_dt,
                        to_entered_datetime=to_dt,
                    )
                except TypeError:
                    resp = cl_before.get_orders_for_account(acct_before)
            if resp is None or getattr(resp, "status_code", None) != 200:
                return None
            orders = resp.json()
            if not isinstance(orders, list):
                return None
            dt_ms = (time.monotonic() - t0) * 1000.0
            try:
                resp_kb = len(getattr(resp, "content", b"") or b"") / 1024.0
            except Exception:
                resp_kb = 0.0
            if (
                dt_ms >= 250.0
                or first_poll_of_launch
                or not _initial_positions_verified
            ):
                log_event(
                    "PERF",
                    f"Schwab get_orders_for_account({win_tag}) fetched "
                    f"{len(orders)} order(s) ({resp_kb:.1f} KB) in {dt_ms:.0f}ms.",
                )
            if len(orders) >= 3000:
                log_event(
                    "WARN",
                    f"Schwab {win_tag} order query returned {len(orders)} orders "
                    f"(reached 3,000-order cap); oldest orders in window may be truncated.",
                )
            with self._cache_lock:
                if (
                    self._snapshot_gen == gen_before
                    and self.client is cl_before
                    and str(self.account_id or "") == acct_before
                ):
                    if len(self._raw_orders_window_cache) > 24:
                        self._raw_orders_window_cache.clear()
                    self._raw_orders_window_cache[(acct_before, gen_before, win_tag)] = (
                        time.time(),
                        snap_ep_before,
                        cl_before,
                        fs_before,
                        ft_before,
                        inv_sig_before,
                        list(orders),
                    )
            return orders
        except Exception:
            return None
        finally:
            if acquired:
                try:
                    self._orders_fetch_lock.release()
                except Exception:
                    pass

    def has_any_filled_orders_today(self):
        """Returns False ONLY when the broker API confirms zero orders have been
        filled (or partially filled) on today's US/Eastern calendar date.
        Defaults to True on any API error so baseline fee-drift absorption is
        100% fail-safe."""
        self._ensure_orders_cache_infra()
        if not self.client or not self.account_id:
            return True
        today_str = get_today_str()
        gen_cur = int(getattr(self, "_snapshot_gen", 0))
        cl_cur = self.client
        inv_sig_cur = _compute_orders_cache_inv_sig(self, str(self.account_id))
        cache_map = self._filled_today_cache
        c_key = (str(self.account_id), today_str)
        now_ts = time.time()
        cached = cache_map.get(c_key)
        if isinstance(cached, tuple) and len(cached) >= 5 and cached[2] is cl_cur:
            c_ts, c_val = float(cached[0]), bool(cached[1])
            if c_val:
                return True
            if (
                cached[3] == gen_cur
                and cached[4] == inv_sig_cur
                and (now_ts - c_ts) < 30.0
            ):
                return False
        try:
            orders = self._get_orders_window_cached("58d")
            if not isinstance(orders, list):
                return True
            for o in orders:
                if not isinstance(o, dict):
                    continue
                st = str(o.get("status") or "").upper()
                try:
                    filled_q = float(o.get("filledQuantity") or 0.0)
                except Exception:
                    filled_q = 0.0
                if filled_q <= 0.0 and st not in ("FILLED", "PARTIAL_FILLED"):
                    continue
                candidate_dates = set()
                for ts_key in ("closeTime", "enteredTime"):
                    d_str = self._order_ts_to_eastern_date(o.get(ts_key))
                    if d_str:
                        candidate_dates.add(d_str)
                for act in o.get("orderActivityCollection") or []:
                    if isinstance(act, dict):
                        for ex_leg in act.get("executionLegs") or []:
                            if isinstance(ex_leg, dict):
                                d_str = self._order_ts_to_eastern_date(
                                    ex_leg.get("time")
                                )
                                if d_str:
                                    candidate_dates.add(d_str)
                if today_str in candidate_dates:
                    if (
                        self.client is cl_cur
                        and int(getattr(self, "_snapshot_gen", 0)) == gen_cur
                    ):
                        cache_map[c_key] = (
                            now_ts,
                            True,
                            cl_cur,
                            gen_cur,
                            inv_sig_cur,
                        )
                    return True
            if (
                self.client is cl_cur
                and int(getattr(self, "_snapshot_gen", 0)) == gen_cur
            ):
                cache_map[c_key] = (
                    now_ts,
                    False,
                    cl_cur,
                    gen_cur,
                    inv_sig_cur,
                )
            return False
        except Exception:
            return True

    def has_non_ignored_closing_fills_since(
        self, since_epoch, was_flat_at_save=True
    ):
        """Returns True ONLY when the Schwab API confirms at least one non-ignored
        closing order (or any non-ignored fill if the session saved while in a
        trade) executed on today's ET date at or after `since_epoch`."""
        if (
            not self.client
            or not self.account_id
            or since_epoch is None
            or float(since_epoch) <= 0.0
        ):
            return False
        today_str = get_today_str()
        cutoff = float(since_epoch) - 2.0
        closing_instrs = {
            "SELL",
            "SELL_TO_CLOSE",
            "BUY_TO_COVER",
            "BUY_TO_CLOSE",
        }
        try:
            orders = self._get_orders_window_cached("58d")
            if not isinstance(orders, list):
                return False
            for o in orders:
                if not isinstance(o, dict):
                    continue
                st = str(o.get("status") or "").upper()
                try:
                    filled_q = float(o.get("filledQuantity") or 0.0)
                except Exception:
                    filled_q = 0.0
                if filled_q <= 0.0 and st not in ("FILLED", "PARTIAL_FILLED"):
                    continue
                fill_epochs = []
                fill_dates = set()
                for act in o.get("orderActivityCollection") or []:
                    if isinstance(act, dict):
                        for ex_leg in act.get("executionLegs") or []:
                            if isinstance(ex_leg, dict):
                                raw_t = ex_leg.get("time")
                                ep = self._order_ts_to_epoch(raw_t)
                                if ep > 0.0:
                                    fill_epochs.append(ep)
                                d_s = self._order_ts_to_eastern_date(raw_t)
                                if d_s:
                                    fill_dates.add(d_s)
                for ts_key in ("closeTime", "enteredTime"):
                    raw_t = o.get(ts_key)
                    ep = self._order_ts_to_epoch(raw_t)
                    if ep > 0.0 and not fill_epochs:
                        fill_epochs.append(ep)
                    d_s = self._order_ts_to_eastern_date(raw_t)
                    if d_s:
                        fill_dates.add(d_s)
                if today_str not in fill_dates:
                    continue
                if not fill_epochs or max(fill_epochs) < cutoff:
                    continue
                for lg in o.get("orderLegCollection") or []:
                    if not isinstance(lg, dict):
                        continue
                    inst = lg.get("instrument") or {}
                    leg_sym = str(inst.get("symbol") or "").strip()
                    if not leg_sym:
                        continue
                    leg_opt = (
                        str(inst.get("assetType") or "").upper() == "OPTION"
                    )
                    if is_position_ignored(leg_sym, is_opt=leg_opt):
                        continue
                    instr = str(lg.get("instruction") or "").upper()
                    if (not was_flat_at_save) or (instr in closing_instrs):
                        return True
            return False
        except Exception:
            return False

    def fetch_filled_orders_since(self, since_epoch, fast_recent_only=False):
        """Fetches normalized execution fills on today's ET date at or after
        `since_epoch` (with 58-day GTC lookback, optional `36h` fast-path for
        zero-delta flat launches, and recursive childOrderStrategies traversal).
        Returns a chronologically sorted list of fill dicts, or None on API failure."""
        self._ensure_orders_cache_infra()
        if (
            not self.client
            or not self.account_id
            or since_epoch is None
            or float(since_epoch) <= 0.0
        ):
            return None
        today_str = get_today_str()
        cutoff = float(since_epoch) - 2.0
        win_tag = "36h" if fast_recent_only else "58d"
        gen_start = int(getattr(self, "_snapshot_gen", 0))
        cl_start = self.client
        inv_sig = _compute_orders_cache_inv_sig(self, str(self.account_id))
        fs_cache = self._filled_since_cache
        fs_key = (
            str(self.account_id),
            today_str,
            round(cutoff, 0),
            gen_start,
            win_tag,
            inv_sig,
        )
        now_ts = time.time()
        fs_hit = fs_cache.get(fs_key)
        if (
            fs_hit is not None
            and len(fs_hit) >= 3
            and fs_hit[2] is self.client
            and (now_ts - float(fs_hit[0])) < 6.0
        ):
            return json.loads(json.dumps(fs_hit[1]))

        buy_instrs = {"BUY", "BUY_TO_COVER", "BUY_TO_OPEN", "BUY_TO_CLOSE"}
        sell_instrs = {"SELL", "SELL_SHORT", "SELL_TO_OPEN", "SELL_TO_CLOSE"}
        try:
            eff_ord_ttl = (
                60.0 if (_off_session_reconciled and fast_recent_only) else 8.0
            )
            sc_orders = self._get_orders_window_cached(
                win_tag, ttl_sec=eff_ord_ttl
            )
            if not isinstance(sc_orders, list):
                return None

            sc_flat = []
            sc_seen_oids = set()
            sc_seen_ptrs = set()

            def _collect_sc_orders(ord_list):
                for item_o in ord_list or []:
                    if not isinstance(item_o, dict):
                        continue
                    oid_val = str(item_o.get("orderId") or "").strip()
                    if oid_val:
                        if oid_val in sc_seen_oids:
                            continue
                        sc_seen_oids.add(oid_val)
                    else:
                        ptr = id(item_o)
                        if ptr in sc_seen_ptrs:
                            continue
                        sc_seen_ptrs.add(ptr)
                    sc_flat.append(item_o)
                    children = item_o.get("childOrderStrategies")
                    if isinstance(children, list) and children:
                        _collect_sc_orders(children)

            _collect_sc_orders(sc_orders)

            sc_out = []
            sc_seq = 0
            for o_idx, o in enumerate(sc_flat):
                st = str(o.get("status") or "").upper()
                oid_raw = str(o.get("orderId") or "").strip()
                raw_legs = [
                    lg
                    for lg in (o.get("orderLegCollection") or [])
                    if isinstance(lg, dict)
                ]
                if not raw_legs:
                    continue

                legs_by_id = {}
                parsed_legs = []
                any_unignored_leg = False
                for l_idx, lg in enumerate(raw_legs):
                    inst = lg.get("instrument") or {}
                    raw_sym = str(inst.get("symbol") or "").strip()
                    atype = str(inst.get("assetType") or "EQUITY").upper()
                    if atype not in ("EQUITY", "COLLECTIVE_INVESTMENT", "OPTION"):
                        continue
                    if not raw_sym:
                        continue
                    is_opt = atype == "OPTION"
                    if is_position_ignored(raw_sym, is_opt=is_opt):
                        continue
                    any_unignored_leg = True
                    instr = str(lg.get("instruction") or "").upper()
                    if instr in buy_instrs:
                        side_s = "BUY"
                    elif instr in sell_instrs:
                        side_s = "SELL"
                    else:
                        continue
                    l_meta = {
                        "raw_symbol": raw_sym,
                        "symbol": f"{raw_sym} (OPT)" if is_opt else raw_sym,
                        "asset_type": "OPTION" if is_opt else "EQUITY",
                        "multiplier": 100.0 if is_opt else 1.0,
                        "side": side_s,
                        "instruction": instr,
                        "leg_qty": float(lg.get("quantity") or 0.0),
                    }
                    parsed_legs.append(l_meta)
                    raw_lid = lg.get("legId")
                    if raw_lid is not None:
                        try:
                            legs_by_id[int(raw_lid)] = l_meta
                        except Exception:
                            pass
                    legs_by_id.setdefault(l_idx + 1, l_meta)

                if not any_unignored_leg or not parsed_legs:
                    continue

                used_exec_legs = False
                ex_counter = 0
                for act in o.get("orderActivityCollection") or []:
                    if not isinstance(act, dict):
                        continue
                    act_t = str(act.get("activityType") or "").upper()
                    if act_t and act_t != "EXECUTION":
                        continue
                    for ex_leg in act.get("executionLegs") or []:
                        if not isinstance(ex_leg, dict):
                            continue
                        ex_counter += 1
                        try:
                            ex_q = float(ex_leg.get("quantity") or 0.0)
                        except Exception:
                            ex_q = 0.0
                        if ex_q <= 0.0:
                            continue
                        used_exec_legs = True
                        raw_t = ex_leg.get("time")
                        d_s = self._order_ts_to_eastern_date(raw_t)
                        ep = self._order_ts_to_epoch(raw_t)
                        if d_s != today_str or ep <= 0.0 or ep < cutoff:
                            continue
                        matched_leg = None
                        ex_lid = ex_leg.get("legId")
                        if ex_lid is not None:
                            try:
                                matched_leg = legs_by_id.get(int(ex_lid))
                            except Exception:
                                matched_leg = None
                        if matched_leg is None and len(parsed_legs) == 1:
                            matched_leg = parsed_legs[0]
                        if matched_leg is None:
                            continue
                        ex_px = None
                        if ex_leg.get("price") is not None:
                            try:
                                cand_px = float(ex_leg.get("price"))
                                if cand_px > 0.0:
                                    ex_px = cand_px
                            except Exception:
                                ex_px = None
                        oid_use = oid_raw or f"IDX{o_idx}"
                        o_key = (
                            f"SC_EX:{oid_use}:{ex_lid if ex_lid is not None else 1}:"
                            f"{ex_counter}:{ep:.3f}:{ex_q:g}"
                        )
                        sc_seq += 1
                        sc_out.append(
                            {
                                "order_key": o_key,
                                "order_id": oid_raw,
                                "symbol": matched_leg["symbol"],
                                "raw_symbol": matched_leg["raw_symbol"],
                                "asset_type": matched_leg["asset_type"],
                                "multiplier": matched_leg["multiplier"],
                                "side": matched_leg["side"],
                                "instruction": matched_leg["instruction"],
                                "total_filled_qty": ex_q,
                                "price": ex_px,
                                "fill_epoch": ep,
                                "multi_leg_unknown": False,
                                "_seq": sc_seq,
                            }
                        )

                if not used_exec_legs:
                    try:
                        fq_top = float(o.get("filledQuantity") or 0.0)
                    except Exception:
                        fq_top = 0.0
                    if fq_top <= 0.0 and st not in ("FILLED", "PARTIAL_FILLED"):
                        continue
                    raw_t = o.get("closeTime") or o.get("enteredTime")
                    d_s = self._order_ts_to_eastern_date(raw_t)
                    ep = self._order_ts_to_epoch(raw_t)
                    if d_s != today_str or ep <= 0.0 or ep < cutoff:
                        continue
                    if len(parsed_legs) > 1 or len(raw_legs) > 1:
                        sc_seq += 1
                        ml_oid = oid_raw or f"ML_{ep:.3f}_{o_idx}"
                        sc_out.append(
                            {
                                "order_key": f"SC_ML:{ml_oid}",
                                "order_id": oid_raw,
                                "symbol": parsed_legs[0]["symbol"],
                                "raw_symbol": parsed_legs[0]["raw_symbol"],
                                "asset_type": parsed_legs[0]["asset_type"],
                                "multiplier": parsed_legs[0]["multiplier"],
                                "side": parsed_legs[0]["side"],
                                "instruction": parsed_legs[0]["instruction"],
                                "total_filled_qty": max(fq_top, 1.0),
                                "price": None,
                                "fill_epoch": ep,
                                "multi_leg_unknown": True,
                                "_seq": sc_seq,
                            }
                        )
                    else:
                        lg0 = parsed_legs[0]
                        eff_fq = fq_top if fq_top > 0.0 else max(lg0["leg_qty"], 0.0)
                        if eff_fq <= 0.0:
                            continue
                        fb_px = None
                        for px_k in ("averagePrice", "avgFillPrice", "avgPrice"):
                            if o.get(px_k) is not None:
                                try:
                                    c_px = float(o.get(px_k))
                                    if c_px > 0.0:
                                        fb_px = c_px
                                        break
                                except Exception:
                                    pass
                        synth_id = (
                            oid_raw
                            or f"SYNTH:{lg0['raw_symbol']}:{lg0['instruction']}:{raw_t}"
                        )
                        sc_seq += 1
                        sc_out.append(
                            {
                                "order_key": f"SC_ORD:{synth_id}",
                                "order_id": oid_raw,
                                "symbol": lg0["symbol"],
                                "raw_symbol": lg0["raw_symbol"],
                                "asset_type": lg0["asset_type"],
                                "multiplier": lg0["multiplier"],
                                "side": lg0["side"],
                                "instruction": lg0["instruction"],
                                "total_filled_qty": eff_fq,
                                "price": fb_px,
                                "fill_epoch": ep,
                                "multi_leg_unknown": False,
                                "_seq": sc_seq,
                            }
                        )

            sc_out.sort(key=lambda r: (float(r["fill_epoch"]), int(r["_seq"])))
            for r in sc_out:
                r.pop("_seq", None)
            with self._cache_lock:
                if (
                    int(getattr(self, "_snapshot_gen", 0)) == gen_start
                    and self.client is cl_start
                ):
                    self._filled_since_cache[fs_key] = (
                        time.time(),
                        json.loads(json.dumps(sc_out)),
                        cl_start,
                    )
            return sc_out
        except Exception:
            return None

    def get_open_equity_positions(
        self,
        allow_stale_cache=True,
        pace_for_verify=False,
        cache_empty_ok=False,
    ):
        """Returns ONLY Equity positions for Auto-Flatten, or None on API error."""
        snap_gen_at_start = self._snapshot_gen
        with self._cache_lock:
            cached = self._last_open_eq.get(self.account_id)
        if (
            allow_stale_cache
            and cached
            and (time.time() - cached[0]) < 0.45
            and (cached[1] or cache_empty_ok)
        ):
            return [
                item
                for item in cached[1]
                if not is_position_ignored(item[0], is_opt=False)
                and not is_uncloseable_fractional_qty(
                    self.account_id, item[0], item[1]
                )
            ]
        if (
            not pace_for_verify
            and allow_stale_cache
            and time.time() < self._rate_limit_until
            and cached
            and (time.time() - cached[0]) <= 2.5
            and (cached[1] or cache_empty_ok)
        ):
            return [
                item
                for item in cached[1]
                if not is_position_ignored(item[0], is_opt=False)
                and not is_uncloseable_fractional_qty(
                    self.account_id, item[0], item[1]
                )
            ]
        try:
            try:
                resp = self.client.get_account(
                    self.account_id, fields=self.client.Account.Fields.POSITIONS
                )
            except Exception as inner_e:
                if (
                    "token_invalid" in str(inner_e).lower()
                    and self.reconnect_session()
                ):
                    log_event(
                        "SESSION",
                        "Schwab in-memory token refreshed from disk after token_invalid."
                    )
                    resp = self.client.get_account(
                        self.account_id,
                        fields=self.client.Account.Fields.POSITIONS
                    )
                else:
                    raise
            if resp.status_code == 200:
                open_eq = []
                open_opt = []
                sec_acc = resp.json().get("securitiesAccount", {})
                for pos in sec_acc.get("positions", []):
                    inst = pos.get("instrument", {})
                    a_type = inst.get("assetType")
                    qty = (
                        pos.get("longQuantity", 0)
                        - pos.get("shortQuantity", 0)
                    )
                    if qty != 0:
                        sym = inst.get("symbol", "")
                        if a_type in ("EQUITY", "COLLECTIVE_INVESTMENT") and not is_position_ignored(
                            sym, is_opt=False
                        ) and not is_uncloseable_fractional_qty(
                            self.account_id, sym, qty
                        ):
                            open_eq.append((sym, qty))
                        elif a_type == "OPTION" and not is_position_ignored(
                            sym, is_opt=True
                        ):
                            open_opt.append((sym, qty))
                open_opt.sort(
                    key=lambda item: (0 if item[1] < 0 else 1, str(item[0]))
                )
                self._prune_pending_flatten_cids(
                    self.account_id,
                    {sym: qty for sym, qty in (open_eq + open_opt)},
                )
                self.last_positions_fetch_ok = True
                now_t = time.time()
                with self._cache_lock:
                    if self._snapshot_gen == snap_gen_at_start:
                        self._last_open_eq[self.account_id] = (now_t, list(open_eq))
                        self._last_open_opt[self.account_id] = (now_t, list(open_opt))
                return open_eq
            if resp.status_code == 429:
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
            log_event(
                "ERROR",
                f"get_open_equity_positions HTTP {resp.status_code}"
            )
        except Exception as e:
            err_s = str(e)
            if "429" in err_s or "too many requests" in err_s.lower():
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
            log_event(
                "ERROR",
                f"Schwab get_open_equity_positions exception: {e}"
            )
        self.last_positions_fetch_ok = False
        if allow_stale_cache:
            with self._cache_lock:
                cached = (
                    self._last_open_eq.get(self.account_id)
                    if self._snapshot_gen == snap_gen_at_start
                    else None
                )
            if cached and (time.time() - cached[0]) <= 10.0 and cached[1]:
                log_event(
                    "FLATTEN",
                    "Using cached Schwab open equity snapshot (<10s) after API error."
                )
                return [
                    item
                    for item in cached[1]
                    if not is_position_ignored(item[0], is_opt=False)
                    and not is_uncloseable_fractional_qty(
                        self.account_id, item[0], item[1]
                    )
                ]
        return None

    def get_open_option_positions(
        self,
        allow_stale_cache=True,
        pace_for_verify=False,
        reuse_paired_eq_read=False,
    ):
        """Returns ONLY Option positions (symbol, qty) sorted with short legs
        (qty < 0) first for BETA Options Auto-Flatten, or None on API error."""
        snap_gen_at_start = self._snapshot_gen
        with self._cache_lock:
            cached = self._last_open_opt.get(self.account_id)
        if (
            (allow_stale_cache or reuse_paired_eq_read)
            and cached
            and (time.time() - cached[0]) < 0.50
        ):
            return [
                item
                for item in cached[1]
                if not is_position_ignored(item[0], is_opt=True)
            ]
        if (
            not pace_for_verify
            and allow_stale_cache
            and time.time() < self._rate_limit_until
            and cached
            and (time.time() - cached[0]) <= 2.5
        ):
            return [
                item
                for item in cached[1]
                if not is_position_ignored(item[0], is_opt=True)
            ]
        try:
            try:
                resp = self.client.get_account(
                    self.account_id, fields=self.client.Account.Fields.POSITIONS
                )
            except Exception as inner_e:
                if (
                    "token_invalid" in str(inner_e).lower()
                    and self.reconnect_session()
                ):
                    log_event(
                        "SESSION",
                        "Schwab in-memory token refreshed from disk after token_invalid."
                    )
                    resp = self.client.get_account(
                        self.account_id,
                        fields=self.client.Account.Fields.POSITIONS
                    )
                else:
                    raise
            if resp.status_code == 200:
                open_eq = []
                open_opt = []
                sec_acc = resp.json().get("securitiesAccount", {})
                for pos in sec_acc.get("positions", []):
                    inst = pos.get("instrument", {})
                    a_type = inst.get("assetType")
                    qty = (
                        pos.get("longQuantity", 0)
                        - pos.get("shortQuantity", 0)
                    )
                    if qty != 0:
                        sym = inst.get("symbol", "")
                        if a_type in ("EQUITY", "COLLECTIVE_INVESTMENT") and not is_position_ignored(
                            sym, is_opt=False
                        ) and not is_uncloseable_fractional_qty(
                            self.account_id, sym, qty
                        ):
                            open_eq.append((sym, qty))
                        elif a_type == "OPTION" and not is_position_ignored(
                            sym, is_opt=True
                        ):
                            open_opt.append((inst["symbol"], qty))
                open_opt.sort(
                    key=lambda item: (0 if item[1] < 0 else 1, str(item[0]))
                )
                self._prune_pending_flatten_cids(
                    self.account_id,
                    {sym: qty for sym, qty in (open_eq + open_opt)},
                )
                self.last_positions_fetch_ok = True
                now_t = time.time()
                with self._cache_lock:
                    if self._snapshot_gen == snap_gen_at_start:
                        self._last_open_eq[self.account_id] = (now_t, list(open_eq))
                        self._last_open_opt[self.account_id] = (now_t, list(open_opt))
                return open_opt
            if resp.status_code == 429:
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
            log_event(
                "ERROR",
                f"Schwab get_open_option_positions HTTP {resp.status_code}"
            )
        except Exception as e:
            err_s = str(e)
            if "429" in err_s or "too many requests" in err_s.lower():
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
            log_event(
                "ERROR",
                f"Schwab get_open_option_positions exception: {e}"
            )
        self.last_positions_fetch_ok = False
        if allow_stale_cache:
            with self._cache_lock:
                cached = (
                    self._last_open_opt.get(self.account_id)
                    if self._snapshot_gen == snap_gen_at_start
                    else None
                )
            if cached and (time.time() - cached[0]) <= 10.0 and cached[1]:
                log_event(
                    "FLATTEN",
                    "Using cached Schwab open option snapshot (<10s) after API error."
                )
                return [
                    item
                    for item in cached[1]
                    if not is_position_ignored(item[0], is_opt=True)
                ]
        return None

    def submit_option_liquidation_batch(self, open_opt_positions):
        """Submits single-leg RTH Market orders to close open option positions
        (BUY_TO_CLOSE on short legs first, then SELL_TO_CLOSE on long legs)."""
        submitted_ok = {}
        if not open_opt_positions:
            return submitted_ok
        if not is_market_hours():
            log_event(
                "GUARDRAIL",
                f"Cannot submit Schwab option market flatten outside RTH "
                f"(9:30 AM – 4:00 PM ET): {open_opt_positions}"
            )
            return submitted_ok
        from schwab.orders.options import (
            option_buy_to_close_market,
            option_sell_to_close_market,
        )
        self.invalidate_cached_snapshots()
        sorted_opts = sorted(
            open_opt_positions,
            key=lambda item: (0 if item[1] < 0 else 1, str(item[0])),
        )
        for item in sorted_opts:
            symbol = str(item[0]).strip()
            qty = float(item[1])
            abs_q = int(abs(qty))
            if abs_q <= 0:
                continue
            attempt_ts = time.time()
            pend = self._pending_flatten_cids.get((self.account_id, symbol))
            if pend and (attempt_ts - float(pend[1])) < 15.0:
                pend_sub_q = float(pend[2])
                pend_pos_q = float(pend[3]) if len(pend) > 3 else pend_sub_q
                pend_acc = bool(pend[4]) if len(pend) > 4 else False
                w_q, f_q = self.get_recent_exit_order_coverage(
                    symbol,
                    is_short=(qty < 0),
                    since_epoch=pend[1],
                    is_opt=True,
                )
                same_stale_pos = abs(qty - pend_pos_q) <= 1e-6
                if w_q >= (abs_q - 1e-6) or (
                    same_stale_pos
                    and (
                        (w_q + f_q) >= (abs_q - 1e-6)
                        or (
                            (pend_acc or self.last_coverage_lookup_failed)
                            and not self._last_cov_saw_dead_pend
                        )
                    )
                ):
                    log_event(
                        "FLATTEN",
                        f"Skipping duplicate Schwab option close on {symbol} "
                        f"(already working={w_q:g}, filled={f_q:g}).",
                    )
                    submitted_ok[symbol] = float(max(w_q + f_q, pend_sub_q))
                    continue

            self._pending_flatten_cids[(self.account_id, symbol)] = (
                "",
                attempt_ts,
                float(abs_q),
                float(qty),
                False,
            )
            try:
                if qty < 0:
                    log_event(
                        "ORDER_OUT",
                        f"Submitting Schwab RTH Option Market BUY_TO_CLOSE (BETA): "
                        f"{abs_q} {symbol}"
                    )
                    spec = option_buy_to_close_market(symbol, abs_q).build()
                    r = self.client.place_order(self.account_id, spec)
                    raw_oid = self._extract_schwab_order_id(r)
                    oid = _mask_last4(raw_oid)
                    log_event(
                        "ORDER_RESP",
                        f"Schwab Option Buy-to-Close {symbol} ({oid}) -> HTTP {r.status_code}"
                    )
                    if r.status_code in (200, 201, 202):
                        self._pending_flatten_cids[(self.account_id, symbol)] = (
                            raw_oid,
                            attempt_ts,
                            float(abs_q),
                            float(qty),
                            True,
                        )
                        submitted_ok[symbol] = float(abs_q)
                    else:
                        self._pending_flatten_cids.pop(
                            (self.account_id, symbol), None
                        )
                else:
                    log_event(
                        "ORDER_OUT",
                        f"Submitting Schwab RTH Option Market SELL_TO_CLOSE (BETA): "
                        f"{abs_q} {symbol}"
                    )
                    spec = option_sell_to_close_market(symbol, abs_q).build()
                    r = self.client.place_order(self.account_id, spec)
                    raw_oid = self._extract_schwab_order_id(r)
                    oid = _mask_last4(raw_oid)
                    log_event(
                        "ORDER_RESP",
                        f"Schwab Option Sell-to-Close {symbol} ({oid}) -> HTTP {r.status_code}"
                    )
                    if r.status_code in (200, 201, 202):
                        self._pending_flatten_cids[(self.account_id, symbol)] = (
                            raw_oid,
                            attempt_ts,
                            float(abs_q),
                            float(qty),
                            True,
                        )
                        submitted_ok[symbol] = float(abs_q)
                    else:
                        self._pending_flatten_cids.pop(
                            (self.account_id, symbol), None
                        )
            except Exception as e:
                log_event(
                    "ERROR",
                    f"Schwab option place_order exception ({symbol}): {e}"
                )
                w_q, f_q = self.get_recent_exit_order_coverage(
                    symbol,
                    is_short=(qty < 0),
                    since_epoch=attempt_ts,
                    is_opt=True,
                )
                if (w_q + f_q) > 0:
                    log_event(
                        "FLATTEN",
                        f"Verified timed-out Schwab option close on {symbol} is live/filled "
                        f"(working={w_q:g}, filled={f_q:g}); suppressing duplicate.",
                    )
                    submitted_ok[symbol] = float(w_q + f_q)
                elif not self.last_coverage_lookup_failed:
                    self._pending_flatten_cids.pop(
                        (self.account_id, symbol), None
                    )
        self.invalidate_cached_snapshots()
        return submitted_ok

    def submit_liquidation_batch(self, open_positions):
        from schwab.orders.common import Session, Duration
        from schwab.orders.equities import (
            equity_sell_market,
            equity_buy_to_cover_market,
            equity_sell_limit,
            equity_buy_to_cover_limit
        )
        submitted_ok = {}
        if not open_positions:
            return submitted_ok
        self.invalidate_cached_snapshots()

        use_market = is_market_hours()
        quotes_data = {}

        if not use_market:
            symbols = [sym for sym, _ in open_positions]
            try:
                q_resp = self.client.get_quotes(symbols)
                if q_resp.status_code == 200:
                    quotes_data = q_resp.json()
            except Exception as e:
                log_event("ERROR", f"Quote lookup error during flatten: {e}")

        for symbol, qty in open_positions:
            symbol = str(symbol).strip()
            try:
                f_qty = float(qty)
            except Exception:
                continue
            if abs(f_qty) <= 1e-9:
                continue
            if is_uncloseable_fractional_qty(self.account_id, symbol, f_qty):
                continue

            abs_total = abs(f_qty)
            whole_q = int(abs_total)
            is_pure_fractional = (whole_q == 0 and 0.0 < abs_total < 1.0)

            if is_pure_fractional and not use_market:
                mark_uncloseable_fractional_sym(self.account_id, symbol, f_qty)
                continue

            order_qty = round(abs_total, 4) if is_pure_fractional else whole_q
            if order_qty <= 0:
                continue

            attempt_ts = time.time()
            pend = self._pending_flatten_cids.get((self.account_id, symbol))
            if pend and (attempt_ts - float(pend[1])) < 15.0:
                pend_sub_q = float(pend[2])
                pend_pos_q = float(pend[3]) if len(pend) > 3 else pend_sub_q
                pend_acc = bool(pend[4]) if len(pend) > 4 else False
                pend_use_mkt = bool(pend[5]) if len(pend) > 5 else use_market
                w_q, f_q = self.get_recent_exit_order_coverage(
                    symbol,
                    is_short=(f_qty < 0),
                    since_epoch=pend[1],
                    is_opt=False,
                )
                same_stale_pos = abs(f_qty - pend_pos_q) <= 1e-6
                if w_q >= (order_qty - 1e-6) or (
                    same_stale_pos
                    and (
                        (w_q + f_q) >= (order_qty - 1e-6)
                        or (
                            (pend_acc or self.last_coverage_lookup_failed)
                            and pend_use_mkt == use_market
                            and not self._last_cov_saw_dead_pend
                        )
                    )
                ):
                    log_event(
                        "FLATTEN",
                        f"Skipping duplicate Schwab exit order on {symbol} "
                        f"(already working={w_q:g}, filled={f_q:g}).",
                    )
                    submitted_ok[symbol] = float(max(w_q + f_q, pend_sub_q))
                    continue

            self._pending_flatten_cids[(self.account_id, symbol)] = (
                "",
                attempt_ts,
                float(order_qty),
                float(f_qty),
                False,
                bool(use_market),
            )
            try:
                if use_market:
                    if f_qty > 0:
                        log_event(
                            "ORDER_OUT",
                            f"Submitting RTH DAY Market Sell: {order_qty:g} {symbol}"
                        )
                        spec = equity_sell_market(symbol, order_qty).build()
                        r = self.client.place_order(self.account_id, spec)
                        raw_oid = self._extract_schwab_order_id(r)
                        oid = _mask_last4(raw_oid)
                        log_event(
                            "ORDER_RESP",
                            f"Market Sell {symbol} ({oid}) -> HTTP {r.status_code}"
                        )
                        if r.status_code in (200, 201, 202):
                            self._pending_flatten_cids[
                                (self.account_id, symbol)
                            ] = (
                                raw_oid,
                                attempt_ts,
                                float(order_qty),
                                float(f_qty),
                                True,
                                bool(use_market),
                            )
                            submitted_ok[symbol] = float(order_qty)
                        else:
                            self._pending_flatten_cids.pop(
                                (self.account_id, symbol), None
                            )
                            if is_pure_fractional:
                                mark_uncloseable_fractional_sym(
                                    self.account_id, symbol, f_qty
                                )
                    elif f_qty < 0:
                        log_event(
                            "ORDER_OUT",
                            f"Submitting RTH DAY Buy-to-Cover: {order_qty:g} {symbol}"
                        )
                        spec = equity_buy_to_cover_market(
                            symbol, order_qty
                        ).build()
                        r = self.client.place_order(self.account_id, spec)
                        raw_oid = self._extract_schwab_order_id(r)
                        oid = _mask_last4(raw_oid)
                        log_event(
                            "ORDER_RESP",
                            f"Buy-to-Cover {symbol} ({oid}) -> HTTP {r.status_code}"
                        )
                        if r.status_code in (200, 201, 202):
                            self._pending_flatten_cids[
                                (self.account_id, symbol)
                            ] = (
                                raw_oid,
                                attempt_ts,
                                float(order_qty),
                                float(f_qty),
                                True,
                                bool(use_market),
                            )
                            submitted_ok[symbol] = float(order_qty)
                        else:
                            self._pending_flatten_cids.pop(
                                (self.account_id, symbol), None
                            )
                            if is_pure_fractional:
                                mark_uncloseable_fractional_sym(
                                    self.account_id, symbol, f_qty
                                )
                else:
                    q_info = quotes_data.get(symbol, {}).get("quote", {})
                    if f_qty > 0:
                        bid = (
                            q_info.get("bidPrice")
                            or q_info.get("lastPrice")
                            or q_info.get("mark")
                        )
                        if not bid or bid <= 0:
                            self._pending_flatten_cids.pop(
                                (self.account_id, symbol), None
                            )
                            log_event(
                                "ERROR", f"No valid bid found for {symbol}!"
                            )
                            continue
                        lim_price = calc_ext_limit_price(
                            float(bid), is_sell=True
                        )
                        lim_price_str = format_limit_price_str(lim_price)
                        log_event(
                            "ORDER_OUT",
                            f"Submitting EXT DAY_EXT Limit Sell: {whole_q} {symbol} "
                            f"@ ${lim_price_str} (Live Bid: ${bid})"
                        )
                        spec = (
                            equity_sell_limit(symbol, whole_q, lim_price_str)
                            .set_session(Session.SEAMLESS)
                            .set_duration(Duration.DAY)
                            .build()
                        )
                        r = self.client.place_order(self.account_id, spec)
                        if r.status_code == 400:
                            spec_gtc = (
                                equity_sell_limit(
                                    symbol, whole_q, lim_price_str
                                )
                                .set_session(Session.SEAMLESS)
                                .set_duration(Duration.GOOD_TILL_CANCEL)
                                .build()
                            )
                            r = self.client.place_order(
                                self.account_id, spec_gtc
                            )
                        raw_oid = self._extract_schwab_order_id(r)
                        oid = _mask_last4(raw_oid)
                        log_event(
                            "ORDER_RESP",
                            f"EXT Limit Sell {symbol} ({oid}) -> HTTP {r.status_code}"
                        )
                        if r.status_code in (200, 201, 202):
                            self._pending_flatten_cids[
                                (self.account_id, symbol)
                            ] = (
                                raw_oid,
                                attempt_ts,
                                float(whole_q),
                                float(f_qty),
                                True,
                                bool(use_market),
                            )
                            submitted_ok[symbol] = float(whole_q)
                        else:
                            self._pending_flatten_cids.pop(
                                (self.account_id, symbol), None
                            )
                    elif f_qty < 0:
                        ask = (
                            q_info.get("askPrice")
                            or q_info.get("lastPrice")
                            or q_info.get("mark")
                        )
                        if not ask or ask <= 0:
                            self._pending_flatten_cids.pop(
                                (self.account_id, symbol), None
                            )
                            log_event(
                                "ERROR", f"No valid ask found for {symbol}!"
                            )
                            continue
                        lim_price = calc_ext_limit_price(
                            float(ask), is_sell=False
                        )
                        lim_price_str = format_limit_price_str(lim_price)
                        log_event(
                            "ORDER_OUT",
                            f"Submitting EXT DAY_EXT Limit Cover: {whole_q} {symbol} "
                            f"@ ${lim_price_str} (Live Ask: ${ask})"
                        )
                        spec = (
                            equity_buy_to_cover_limit(
                                symbol, whole_q, lim_price_str
                            )
                            .set_session(Session.SEAMLESS)
                            .set_duration(Duration.DAY)
                            .build()
                        )
                        r = self.client.place_order(self.account_id, spec)
                        if r.status_code == 400:
                            spec_gtc = (
                                equity_buy_to_cover_limit(
                                    symbol, whole_q, lim_price_str
                                )
                                .set_session(Session.SEAMLESS)
                                .set_duration(Duration.GOOD_TILL_CANCEL)
                                .build()
                            )
                            r = self.client.place_order(
                                self.account_id, spec_gtc
                            )
                        raw_oid = self._extract_schwab_order_id(r)
                        oid = _mask_last4(raw_oid)
                        log_event(
                            "ORDER_RESP",
                            f"EXT Limit Cover {symbol} ({oid}) -> HTTP {r.status_code}"
                        )
                        if r.status_code in (200, 201, 202):
                            self._pending_flatten_cids[
                                (self.account_id, symbol)
                            ] = (
                                raw_oid,
                                attempt_ts,
                                float(whole_q),
                                float(f_qty),
                                True,
                                bool(use_market),
                            )
                            submitted_ok[symbol] = float(whole_q)
                        else:
                            self._pending_flatten_cids.pop(
                                (self.account_id, symbol), None
                            )
            except Exception as e:
                log_event(
                    "ERROR",
                    f"Schwab equity place_order exception ({symbol}): {e}"
                )
                if is_pure_fractional:
                    self._pending_flatten_cids.pop(
                        (self.account_id, symbol), None
                    )
                    mark_uncloseable_fractional_sym(
                        self.account_id, symbol, f_qty
                    )
                    continue
                w_q, f_q = self.get_recent_exit_order_coverage(
                    symbol,
                    is_short=(f_qty < 0),
                    since_epoch=attempt_ts,
                    is_opt=False,
                )
                if (w_q + f_q) > 0:
                    log_event(
                        "FLATTEN",
                        f"Verified timed-out Schwab exit order on {symbol} is live/filled "
                        f"(working={w_q:g}, filled={f_q:g}); suppressing duplicate.",
                    )
                    submitted_ok[symbol] = float(w_q + f_q)
                elif not self.last_coverage_lookup_failed:
                    self._pending_flatten_cids.pop(
                        (self.account_id, symbol), None
                    )
        self.invalidate_cached_snapshots()
        return submitted_ok

    def fetch_account_data(self):
        """Returns (adj_eq, is_flat, open_pnl, pos_details, has_options)
        tracking BOTH Equities (1x) and Options (100x)."""
        self.last_snapshot_was_cached = False
        snap_gen_at_start = self._snapshot_gen
        start_acct_id = self.account_id
        now_ts = time.time()
        if now_ts < self._rate_limit_until:
            with self._cache_lock:
                cached_snap = (
                    self._last_good_snapshot.get(start_acct_id)
                    if self._snapshot_gen == snap_gen_at_start
                    else None
                )
            if cached_snap and (now_ts - cached_snap[0]) <= 15.0:
                self.last_snapshot_was_cached = True
                return cached_snap[1]
            self.last_error = "HTTP 429"
            return None, True, 0.0, {}, False

        try:
            try:
                resp = self.client.get_account(
                    start_acct_id, fields=self.client.Account.Fields.POSITIONS
                )
            except Exception as inner_e:
                if (
                    "token_invalid" in str(inner_e).lower()
                    and self.reconnect_session()
                ):
                    log_event(
                        "SESSION",
                        "Schwab in-memory token refreshed from disk after token_invalid."
                    )
                    resp = self.client.get_account(
                        start_acct_id,
                        fields=self.client.Account.Fields.POSITIONS
                    )
                else:
                    raise
            if self.account_id != start_acct_id or broker_reconfig_in_progress:
                return None, True, 0.0, {}, False
            if resp.status_code == 200:
                self.last_error = ""
                data = resp.json().get("securitiesAccount", {})
                init_balances = data.get("initialBalances", {}) or {}
                balances = data.get("currentBalances", {}) or {}
                raw_eq_true = float(balances.get("liquidationValue", 0))
                init_cr = float(init_balances.get("cashReceipts") or 0.0)
                init_pend = float(init_balances.get("pendingDeposits") or 0.0)
                curr_cr = float(balances.get("cashReceipts") or 0.0)
                curr_pend = float(balances.get("pendingDeposits") or 0.0)
                cr_delta = curr_cr - init_cr
                new_pend = max(0.0, curr_pend - init_pend)
                intraday_cf = round(
                    (cr_delta + new_pend)
                    if cr_delta < 0.0
                    else max(cr_delta, new_pend),
                    2,
                )
                self._last_intraday_cash_flow[start_acct_id] = intraday_cf
                raw_eq = raw_eq_true - get_unanchored_cash_flow(intraday_cf)

                positions = data.get("positions", [])
                open_assets = []
                open_eq_cache = []
                open_opt_cache = []
                has_options = False
                for pos in positions:
                    a_type = pos.get("instrument", {}).get("assetType")
                    if a_type in ("EQUITY", "COLLECTIVE_INVESTMENT", "OPTION"):
                        net_q = (
                            pos.get("longQuantity", 0)
                            - pos.get("shortQuantity", 0)
                        )
                        if net_q != 0:
                            sym_p = pos.get("instrument", {}).get("symbol", "")
                            if a_type != "OPTION" and is_uncloseable_fractional_qty(
                                start_acct_id, sym_p, net_q
                            ):
                                continue
                            if a_type == "OPTION":
                                has_options = True
                                open_opt_cache.append((sym_p, net_q))
                            else:
                                open_eq_cache.append((sym_p, net_q))
                            open_assets.append((pos, net_q, a_type))

                open_opt_cache.sort(
                    key=lambda item: (0 if item[1] < 0 else 1, str(item[0]))
                )
                self._prune_pending_flatten_cids(
                    start_acct_id,
                    {sym: qty for sym, qty in (open_eq_cache + open_opt_cache)},
                )
                self.last_positions_fetch_ok = True
                now_snap_t = time.time()

                if not open_assets:
                    if (
                        self.account_id != start_acct_id
                        or broker_reconfig_in_progress
                    ):
                        return None, True, 0.0, {}, False
                    self._last_raw_pos_details[start_acct_id] = {}
                    self._last_unrounded_true_live_eq[start_acct_id] = raw_eq_true
                    self._last_flat_rounding_tol[start_acct_id] = 0.0
                    self._last_bucket_residual.pop(start_acct_id, None)
                    self._last_raw_adj_eq[start_acct_id] = _round_cents(raw_eq)
                    if hasattr(self, "_last_snapshot_epoch") and isinstance(
                        self._last_snapshot_epoch, dict
                    ):
                        self._last_snapshot_epoch[start_acct_id] = now_snap_t
                    (
                        adj_eq,
                        is_flat,
                        tot_open_pnl,
                        filt_pos,
                        has_opt,
                        filt_eq,
                        filt_opt,
                    ) = _apply_ignored_positions_to_snapshot(
                        raw_eq, {}, [], []
                    )
                    flat_res = (adj_eq, is_flat, tot_open_pnl, filt_pos, has_opt)
                    with self._cache_lock:
                        if self._snapshot_gen == snap_gen_at_start:
                            self._last_open_eq[start_acct_id] = (now_snap_t, filt_eq)
                            self._last_open_opt[start_acct_id] = (
                                now_snap_t,
                                filt_opt,
                            )
                            self._last_good_snapshot[start_acct_id] = (
                                time.time(), flat_res
                            )
                    return flat_res

                symbols = [
                    p[0]["instrument"]["symbol"] for p in open_assets
                ]
                total_open_pnl = 0.0
                total_live_mkt_val = 0.0
                total_acct_mkt_val = 0.0
                pos_details = {}

                try:
                    q_resp = self.client.get_quotes(symbols)
                    q_data = (
                        q_resp.json() if q_resp.status_code == 200 else {}
                    )
                except Exception as qe:
                    log_event("ERROR", f"Live quote fetch error: {qe}")
                    q_data = {}

                if (
                    self.account_id != start_acct_id
                    or broker_reconfig_in_progress
                ):
                    return None, True, 0.0, {}, False

                for pos, net_q, a_type in open_assets:
                    sym = pos["instrument"]["symbol"]
                    is_opt = (a_type == "OPTION")
                    norm_a_type = "OPTION" if is_opt else "EQUITY"
                    mult = 100.0 if is_opt else 1.0
                    qty_val = (
                        int(net_q)
                        if float(net_q).is_integer()
                        else round(float(net_q), 6)
                    )
                    acct_mkt_val = float(pos.get("marketValue", 0.0))
                    avg_price = float(
                        pos.get("averageLongPrice")
                        or pos.get("averageShortPrice")
                        or pos.get("averagePrice")
                        or 0.0
                    )

                    quote_info = q_data.get(sym, {}).get("quote", {})
                    if is_opt:
                        live_price = (
                            quote_info.get("mark")
                            or quote_info.get("lastPrice")
                            or quote_info.get("bidPrice")
                        )
                    else:
                        live_price = sanitize_equity_live_price(
                            raw_last=quote_info.get("lastPrice"),
                            bid=quote_info.get("bidPrice"),
                            ask=quote_info.get("askPrice"),
                            mark=quote_info.get("mark"),
                            net_qty=net_q
                        )

                    acct_lp = (
                        abs(acct_mkt_val / (net_q * mult))
                        if net_q != 0 else avg_price
                    )
                    if live_price is not None and float(live_price) > 0:
                        lp = round(float(live_price), 4)
                    else:
                        lp = round(float(acct_lp), 4)

                    live_mkt_val = qty_val * lp * mult
                    total_live_mkt_val += live_mkt_val
                    total_acct_mkt_val += acct_mkt_val

                    if is_opt:
                        conf_lp = lp
                    else:
                        conf_lp = round(
                            float(
                                compute_book_confirmed_price(
                                    lp=lp,
                                    bid=quote_info.get("bidPrice"),
                                    ask=quote_info.get("askPrice"),
                                    mark=quote_info.get("mark"),
                                    acct_lp=acct_lp,
                                    net_qty=net_q,
                                )
                            ),
                            4,
                        )

                    pos_open_pnl = (
                        (lp - avg_price) * qty_val * mult
                        if avg_price > 0 else 0.0
                    )
                    conf_open_pnl = (
                        (conf_lp - avg_price) * qty_val * mult
                        if avg_price > 0 else pos_open_pnl
                    )
                    total_open_pnl += pos_open_pnl
                    tag = f"{sym} (OPT)" if is_opt else sym
                    sec_st = str(
                        quote_info.get("securityStatus")
                        or quote_info.get("tradeStatus")
                        or ""
                    ).strip().upper()
                    is_sym_halted = sec_st in (
                        "HALTED",
                        "HALT",
                        "PAUSED",
                        "SUSPENDED",
                    )
                    pos_details[tag] = {
                        "symbol": sym,
                        "raw_symbol": sym,
                        "qty": qty_val,
                        "avg": round(avg_price, 4),
                        "last": lp,
                        "open_pnl": round(pos_open_pnl, 2),
                        "confirmed_open_pnl": round(conf_open_pnl, 2),
                        "asset_type": norm_a_type,
                        "halted": is_sym_halted,
                    }

                has_cb_mkt_fields = any(
                    k in balances
                    for k in (
                        "longMarketValue",
                        "shortMarketValue",
                        "longOptionMarketValue",
                        "shortOptionMarketValue",
                    )
                )
                cb_eq_opt_mkt_val = (
                    float(balances.get("longMarketValue") or 0.0)
                    - abs(float(balances.get("shortMarketValue") or 0.0))
                    + float(balances.get("longOptionMarketValue") or 0.0)
                    - abs(float(balances.get("shortOptionMarketValue") or 0.0))
                )
                mf_val = float(balances.get("mutualFundValue") or 0.0)
                if (
                    mf_val != 0.0
                    and any(
                        a_t == "COLLECTIVE_INVESTMENT"
                        for _, _, a_t in open_assets
                    )
                    and abs((cb_eq_opt_mkt_val + mf_val) - total_acct_mkt_val)
                    < abs(cb_eq_opt_mkt_val - total_acct_mkt_val)
                ):
                    cb_eq_opt_mkt_val += mf_val

                used_cb_mkt_fields = bool(
                    has_cb_mkt_fields
                    and (
                        abs(cb_eq_opt_mkt_val) >= 0.01
                        or abs(total_acct_mkt_val) < 0.01
                    )
                )
                ref_bal_mkt_val = (
                    cb_eq_opt_mkt_val
                    if used_cb_mkt_fields
                    else total_acct_mkt_val
                )
                true_live_eq = raw_eq_true + (
                    total_live_mkt_val - ref_bal_mkt_val
                )
                unrounded_adj_eq = raw_eq + (
                    total_live_mkt_val - ref_bal_mkt_val
                )
                flat_tol = (
                    0.02
                    if used_cb_mkt_fields
                    else max(
                        0.01,
                        min(
                            0.05,
                            math.floor((len(pos_details) + 1) * 0.5) / 100.0,
                        ),
                    )
                )

                if (
                    self.account_id != start_acct_id
                    or broker_reconfig_in_progress
                ):
                    return None, True, 0.0, {}, False

                self._last_raw_pos_details[start_acct_id] = json.loads(
                    json.dumps(pos_details)
                )
                self._last_unrounded_true_live_eq[start_acct_id] = true_live_eq
                self._last_flat_rounding_tol[start_acct_id] = flat_tol
                self._last_raw_adj_eq[start_acct_id] = _round_cents(
                    unrounded_adj_eq
                )
                if hasattr(self, "_last_snapshot_epoch") and isinstance(
                    self._last_snapshot_epoch, dict
                ):
                    self._last_snapshot_epoch[start_acct_id] = now_snap_t
                (
                    adj_eq,
                    is_flat,
                    tot_open_pnl,
                    filt_pos,
                    has_opt,
                    filt_eq,
                    filt_opt,
                ) = _apply_ignored_positions_to_snapshot(
                    unrounded_adj_eq, pos_details, open_eq_cache, open_opt_cache
                )
                if is_flat and len(pos_details) > 0:
                    bucket_res = _round_cents(raw_eq_true - ref_bal_mkt_val)
                    prev_res = self._last_bucket_residual.get(start_acct_id)
                    self._last_bucket_residual[start_acct_id] = bucket_res
                    if prev_res is not None:
                        res_delta = _round_cents(bucket_res - prev_res)
                        if (
                            0.005 <= abs(res_delta) <= (flat_tol + 1e-9)
                            and (
                                time.time() - self._last_bucket_residual_log_ts
                            )
                            >= 300.0
                        ):
                            self._last_bucket_residual_log_ts = time.time()
                            log_event(
                                "SESSION",
                                f"Broker multi-field balance rounding residual shifted by "
                                f"{format_dollar(res_delta)} across ignored holdings "
                                f"(held steady within ±${flat_tol:.2f} flat deadband).",
                            )
                else:
                    self._last_bucket_residual.pop(start_acct_id, None)

                open_res = (
                    adj_eq,
                    is_flat,
                    tot_open_pnl,
                    filt_pos,
                    has_opt
                )
                with self._cache_lock:
                    if self._snapshot_gen == snap_gen_at_start:
                        self._last_open_eq[start_acct_id] = (now_snap_t, filt_eq)
                        self._last_open_opt[start_acct_id] = (now_snap_t, filt_opt)
                        self._last_good_snapshot[start_acct_id] = (
                            time.time(), open_res
                        )
                return open_res
            elif resp.status_code == 429:
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
                if (time.time() - self._last_429_log_ts) >= 30.0:
                    self._last_429_log_ts = time.time()
                    log_event(
                        "WARN",
                        "Schwab rate limit (HTTP 429) — backing off 2.5s and holding last snapshot."
                    )
                with self._cache_lock:
                    cached_snap = (
                        self._last_good_snapshot.get(start_acct_id)
                        if self._snapshot_gen == snap_gen_at_start
                        else None
                    )
                if cached_snap and (time.time() - cached_snap[0]) <= 15.0:
                    self.last_snapshot_was_cached = True
                    return cached_snap[1]
                self.last_error = "HTTP 429"
            else:
                self.last_error = f"HTTP {resp.status_code}"
                log_event(
                    "ERROR", f"Schwab get_account returned HTTP {resp.status_code}"
                )
        except Exception as e:
            err_s = str(e)
            if "429" in err_s or "too many requests" in err_s.lower():
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
                if (time.time() - self._last_429_log_ts) >= 30.0:
                    self._last_429_log_ts = time.time()
                    log_event(
                        "WARN",
                        "Schwab rate limit (HTTP 429) — backing off 2.5s and holding last snapshot."
                    )
                with self._cache_lock:
                    cached_snap = (
                        self._last_good_snapshot.get(start_acct_id)
                        if self._snapshot_gen == snap_gen_at_start
                        else None
                    )
                if cached_snap and (time.time() - cached_snap[0]) <= 15.0:
                    self.last_snapshot_was_cached = True
                    return cached_snap[1]
            self.last_error = err_s
            log_event("ERROR", f"Schwab account fetch exception: {e}")
        return None, True, 0.0, {}, False


WEBULL_POS_MIN_INTERVAL_SEC = 1.15


class WebullAdapter:
    name = "WEBULL"

    def __init__(self, app_key, app_secret):
        self.app_key = app_key.strip()
        self.app_secret = app_secret.strip()
        self.api_client = None
        self.trade_client = None
        self.data_client = None
        self.account_id = None
        self.accounts = []
        self._logged_accounts = set()
        self._prev_pos_qty_map = {}
        self._last_pos_call_ts = 0.0
        self._last_dl_pos_call_ts = 0.0
        self._pos_pace_lock = threading.Lock()
        self._next_pos_slot_ts = 0.0
        self._cache_lock = threading.Lock()
        self._orders_fetch_lock = threading.Lock()
        self._snapshot_gen = 0
        self.last_snapshot_was_cached = False
        self._last_flatten_outcome = "FLAT"
        self._post_flatten_opt_verify = None
        self._last_good_snapshot = {}
        self._last_raw_pos_details = {}
        self._last_raw_adj_eq = {}
        self._last_unrounded_true_live_eq = {}
        self._last_flat_rounding_tol = {}
        self._last_bucket_residual = {}
        self._last_bucket_residual_log_ts = 0.0
        self._last_open_eq = {}
        self._last_open_opt = {}
        self._last_intraday_cash_flow = {}
        self._last_snapshot_epoch = {}
        self._filled_since_cache = {}
        self._filled_today_cache = {}
        self._raw_orders_window_cache = {}
        self.last_preserved_close_qty = {}
        self.last_cancel_failed_syms = set()
        self.last_coverage_lookup_failed = False
        self._last_cov_saw_dead_pend = False
        self.last_positions_fetch_ok = False
        self._pending_flatten_cids = {}
        self._logged_short_sign_syms = set()
        self._rate_limit_until = 0.0
        self._last_429_log_ts = 0.0
        self._fast_auth_deferred = False
        self._trade_perm_cache = {}
        self.last_error = ""

    def _ensure_orders_cache_infra(self):
        if not hasattr(self, "_cache_lock") or self._cache_lock is None:
            self._cache_lock = threading.Lock()
        if not hasattr(self, "_orders_fetch_lock") or self._orders_fetch_lock is None:
            self._orders_fetch_lock = threading.Lock()
        if not hasattr(self, "_snapshot_gen"):
            self._snapshot_gen = 0
        if not isinstance(getattr(self, "_raw_orders_window_cache", None), dict):
            self._raw_orders_window_cache = {}
        if not isinstance(getattr(self, "_filled_since_cache", None), dict):
            self._filled_since_cache = {}
        if not isinstance(getattr(self, "_filled_today_cache", None), dict):
            self._filled_today_cache = {}

    def invalidate_cached_snapshots(self):
        self._ensure_orders_cache_infra()
        with self._cache_lock:
            self._snapshot_gen += 1
            self._last_good_snapshot.clear()
            self._last_open_eq.clear()
            self._last_open_opt.clear()
            self._filled_since_cache.clear()
            self._filled_today_cache.clear()
            self._raw_orders_window_cache.clear()

    def _reserve_pos_slot(self, own_gap=None, owner="verify"):
        """Serializes Webull `/account/position` requests across `data_loop`
        and flatten/watchdog threads under `_pos_pace_lock`, stamping
        `_last_pos_call_ts` on claim and re-checking mid-sleep 429 backoffs."""
        if own_gap is None:
            own_gap = WEBULL_POS_MIN_INTERVAL_SEC
        while True:
            with self._pos_pace_lock:
                now_p = time.time()
                if self._last_pos_call_ts <= 0.0:
                    self._next_pos_slot_ts = 0.0
                    self._last_dl_pos_call_ts = 0.0
                dl_due = (
                    (self._last_dl_pos_call_ts + float(own_gap))
                    if (owner == "dl" and self._last_dl_pos_call_ts > 0.0)
                    else 0.0
                )
                last_due = (
                    (self._last_pos_call_ts + WEBULL_POS_MIN_INTERVAL_SEC)
                    if self._last_pos_call_ts > 0.0
                    else 0.0
                )
                due = max(
                    now_p,
                    self._next_pos_slot_ts,
                    self._rate_limit_until,
                    last_due,
                    dl_due,
                )
                wait_s = due - now_p
                if wait_s <= 0.005:
                    self._last_pos_call_ts = now_p
                    self._next_pos_slot_ts = now_p + WEBULL_POS_MIN_INTERVAL_SEC
                    if owner == "dl":
                        self._last_dl_pos_call_ts = now_p
                    return
            chunk_s = min(wait_s, 0.25)
            t_pre_sl = time.time()
            _touch_data_loop_heartbeat()
            time.sleep(chunk_s)
            t_post_sl = time.time()
            _touch_data_loop_heartbeat()
            if chunk_s >= 0.10 and (t_post_sl - t_pre_sl) < (chunk_s * 0.4):
                with self._pos_pace_lock:
                    now_f = time.time()
                    self._last_pos_call_ts = now_f
                    self._next_pos_slot_ts = now_f + WEBULL_POS_MIN_INTERVAL_SEC
                    if owner == "dl":
                        self._last_dl_pos_call_ts = now_f
                    return

    def _pace_position_verify_call(self):
        self._reserve_pos_slot(
            own_gap=WEBULL_POS_MIN_INTERVAL_SEC, owner="verify"
        )

    def _prune_pending_flatten_cids(self, acct_id, live_qty_map):
        if not acct_id or not self._pending_flatten_cids:
            return
        now_ts = time.time()
        for k in list(self._pending_flatten_cids.keys()):
            if k[0] != acct_id:
                continue
            sym = k[1]
            pend = self._pending_flatten_cids.get(k)
            if not pend or (now_ts - float(pend[1])) >= 15.0:
                self._pending_flatten_cids.pop(k, None)
                continue
            pre_pos_q = float(pend[3]) if len(pend) > 3 else float(pend[2])
            curr_q = float(live_qty_map.get(sym, 0.0))
            if abs(curr_q) > 1e-6 and abs(curr_q - pre_pos_q) > 1e-6:
                self._pending_flatten_cids.pop(k, None)

    def get_last_raw_pos_details(self):
        return json.loads(
            json.dumps(self._last_raw_pos_details.get(self.account_id, {}))
        )

    def get_last_raw_positions_snapshot(self):
        return self.get_last_raw_pos_details(), self.get_last_raw_adj_eq()

    def get_last_raw_adj_eq(self):
        val = self._last_raw_adj_eq.get(self.account_id)
        return float(val) if val is not None else None

    def get_last_true_live_eq(self):
        val = self._last_unrounded_true_live_eq.get(self.account_id)
        if val is not None:
            return float(val)
        return self.get_last_raw_adj_eq()

    def get_flat_rounding_tolerance(self):
        return float(self._last_flat_rounding_tol.get(self.account_id, 0.0))

    def get_last_intraday_cash_flow(self):
        return float(self._last_intraday_cash_flow.get(self.account_id, 0.0))

    def get_last_snapshot_epoch(self):
        snap_map = getattr(self, "_last_snapshot_epoch", None)
        if isinstance(snap_map, dict):
            return float(snap_map.get(self.account_id, 0.0) or 0.0)
        if isinstance(snap_map, (int, float)):
            return float(snap_map)
        return 0.0

    def get_cached_trading_permission(self):
        entry = self._trade_perm_cache.get(self.account_id)
        if isinstance(entry, tuple) and len(entry) >= 2:
            if (
                len(entry) >= 3
                and entry[0] != "VERIFIED"
                and (time.time() - float(entry[2])) > 120.0
            ):
                self._trade_perm_cache.pop(self.account_id, None)
            else:
                return entry[0], entry[1]
        return ("UNCONFIRMED", "")

    def check_trading_permission_preview(self, force=False):
        """Runs a non-destructive 1-share DAY Limit BUY of SPY @ $1.00 preview
        probe via trade_client.order_v3.preview_order() (or order_v2) and
        returns a 3-state tuple:
        ('VERIFIED' | 'BLOCKED' | 'UNCONFIRMED', detail_str)."""
        if not self.account_id or self.trade_client is None:
            return ("UNCONFIRMED", "Webull trade_client or account_id unavailable.")
        if not force:
            entry = self._trade_perm_cache.get(self.account_id)
            if isinstance(entry, tuple) and len(entry) >= 2:
                if (
                    len(entry) >= 3
                    and entry[0] != "VERIFIED"
                    and (time.time() - float(entry[2])) > 120.0
                ):
                    self._trade_perm_cache.pop(self.account_id, None)
                else:
                    return entry[0], entry[1]
        preview_item = {
            "client_order_id": uuid.uuid4().hex[:24],
            "symbol": "SPY",
            "instrument_type": "EQUITY",
            "market": "US",
            "order_type": "LIMIT",
            "limit_price": "1.00",
            "side": "BUY",
            "quantity": "1",
            "time_in_force": "DAY",
            "support_trading_session": "CORE",
            "entrust_type": "QTY",
        }

        def _invoke_webull_preview():
            self._pace_position_verify_call()
            try:
                r = None
                if (
                    self.api_client is not None
                    and hasattr(self.api_client, "get_response")
                    and "webull" in type(self.api_client).__module__.lower()
                ):
                    try:
                        from webull.trade.request.v3.preview_order_request import (
                            PreviewOrderRequest,
                        )

                        req = PreviewOrderRequest()
                        req.set_account_id(account_id=self.account_id)
                        req.set_new_orders(new_orders=[preview_item])
                        req.add_header("category", "US_EQUITY")
                        r = self.api_client.get_response(req)
                    except Exception as inner_v3_req_e:
                        if hasattr(inner_v3_req_e, "http_status") or hasattr(
                            inner_v3_req_e, "error_code"
                        ):
                            raise
                        r = None
                if r is None:
                    if hasattr(self.trade_client, "order_v3") and hasattr(
                        self.trade_client.order_v3, "preview_order"
                    ):
                        r = self.trade_client.order_v3.preview_order(
                            self.account_id, [preview_item]
                        )
                    elif hasattr(self.trade_client, "order_v2") and hasattr(
                        self.trade_client.order_v2, "preview_order"
                    ):
                        r = self.trade_client.order_v2.preview_order(
                            self.account_id, [preview_item]
                        )
                    else:
                        return ("_NO_METHOD_", None)
                return ("_OK_", r)
            finally:
                with self._pos_pace_lock:
                    self._last_pos_call_ts = time.time()

        try:
            try:
                tag, resp = _invoke_webull_preview()
            except Exception as first_e:
                err_low = str(first_e).lower()
                st_first = getattr(first_e, "http_status", None)
                if (
                    (
                        st_first == 401
                        or "401" in err_low
                        or "unauthorized" in err_low
                        or "token" in err_low
                    )
                    and self.reconnect_session()
                ):
                    preview_item["client_order_id"] = uuid.uuid4().hex[:24]
                    tag, resp = _invoke_webull_preview()
                else:
                    raise
            if tag == "_NO_METHOD_":
                return (
                    "UNCONFIRMED",
                    "Webull preview_order method unavailable on trade_client.",
                )
            if c_resp_code(resp) == 401 and self.reconnect_session():
                preview_item["client_order_id"] = uuid.uuid4().hex[:24]
                tag, resp = _invoke_webull_preview()
                if tag == "_NO_METHOD_":
                    return (
                        "UNCONFIRMED",
                        "Webull preview_order method unavailable on trade_client.",
                    )
            code = c_resp_code(resp)
            if code == 429:
                with self._pos_pace_lock:
                    self._rate_limit_until = max(
                        self._rate_limit_until, time.time() + 2.5
                    )
            txt = ""
            try:
                txt = str(getattr(resp, "text", "") or "")
            except Exception:
                txt = ""
            state, detail = _classify_preview_order_result(
                http_status=code, body_text=txt
            )
        except Exception as e:
            http_st = getattr(e, "http_status", None)
            err_cd = getattr(e, "error_code", "") or ""
            err_ms = getattr(e, "error_msg", "") or ""
            full_txt = f"{err_ms} {str(e)}".strip()
            low_e = f"{err_cd} {full_txt}".lower()
            if (
                http_st == 429
                or "429" in low_e
                or "too_many_requests" in low_e
                or "too many requests" in low_e
            ):
                with self._pos_pace_lock:
                    self._rate_limit_until = max(
                        self._rate_limit_until, time.time() + 2.5
                    )
            state, detail = _classify_preview_order_result(
                http_status=http_st, body_text=full_txt, error_code=err_cd
            )
        self._trade_perm_cache[self.account_id] = (state, detail, time.time())
        log_event(
            "SESSION",
            f"Webull Trade API permission preview check: {state} ({detail[:100]})",
        )
        return state, detail

    def _parse_webull_accounts(self, payload):
        raw_list = (
            payload if isinstance(payload, list)
            else payload.get("data", payload.get("accounts", []))
        )
        self.accounts = []
        for item in raw_list:
            aid = str(
                item.get("account_id")
                or item.get("sec_account_id")
                or item.get("id")
                or ""
            )
            atype = (
                item.get("account_type")
                or item.get("account_class")
                or item.get("type")
                or "TRADING"
            )
            anum = str(item.get("account_number") or aid)
            masked = f"...{anum[-4:]}" if len(anum) >= 4 else anum
            if aid:
                self.accounts.append({
                    "id": aid,
                    "label": f"Webull {atype} ({masked})"
                })
        if self.accounts and not self.account_id:
            self.account_id = self.accounts[0]["id"]

    def verify_accounts_live(self):
        """Verifies live Webull API connectivity and refreshes self.accounts."""
        try:
            res = self._call_get_account_list()
            if res.status_code == 200:
                self._parse_webull_accounts(res.json())
                self._fast_auth_deferred = False
                return True
        except Exception as e:
            self.last_error = str(e)
        return False

    def authenticate(self, fast_cached_accounts=None, allow_interactive_oauth=True):
        logging.getLogger("webull").setLevel(logging.CRITICAL)
        logging.getLogger("webull.core").setLevel(logging.CRITICAL)
        try:
            import six  # noqa: F401
            import jmespath  # noqa: F401
            from webull.core.client import ApiClient
            from webull.trade.trade_client import TradeClient
        except ImportError:
            if not allow_interactive_oauth:
                raise DeferredAuthRequired(
                    "Webull SDK (webull-openapi-python-sdk) not installed — deferred during startup boot."
                )
            print("[SETUP] Installing required Webull OpenAPI SDK & dependencies...")
            py_cli = sys.executable
            if py_cli.lower().endswith("pythonw.exe"):
                cand_py = py_cli[:-5] + ".exe"
                if os.path.exists(cand_py):
                    py_cli = cand_py
            subprocess.run(
                [
                    py_cli, "-m", "pip", "install", "--upgrade",
                    "six", "jmespath", "protobuf", "paho-mqtt",
                    "requests", "urllib3", "certifi", "cryptography", "cachetools"
                ],
                check=False
            )
            subprocess.run(
                [
                    py_cli, "-m", "pip", "install", "--upgrade",
                    "--no-deps", "--ignore-requires-python",
                    "webull-openapi-python-sdk==3.0.4"
                ],
                check=False
            )
            from webull.core.client import ApiClient
            from webull.trade.trade_client import TradeClient
        try:
            self.api_client = ApiClient(
                self.app_key,
                self.app_secret,
                "us",
                connect_timeout=3.5,
                timeout=4.5,
            )
        except TypeError:
            self.api_client = ApiClient(self.app_key, self.app_secret, "us")
            self.api_client._connect_timeout = 3.5
            self.api_client._read_timeout = 4.5
        self.api_client._stream_logger_set = True
        self.api_client._file_logger_set = True
        if hasattr(self.api_client, "set_token_dir"):
            self.api_client.set_token_dir(os.path.join(USER_HOME, "conf"))
        self.api_client.add_endpoint("us", "api.webull.com")
        self.trade_client = TradeClient(self.api_client)
        try:
            from webull.data.data_client import DataClient
            self.data_client = DataClient(self.api_client)
        except Exception:
            self.data_client = None
        logging.getLogger("webull").setLevel(logging.CRITICAL)
        logging.getLogger("webull.core").setLevel(logging.CRITICAL)

        if fast_cached_accounts and isinstance(fast_cached_accounts, list):
            self.accounts = [
                dict(a)
                for a in fast_cached_accounts
                if isinstance(a, dict) and a.get("id")
            ]
            if self.accounts:
                if not self.account_id:
                    self.account_id = self.accounts[0]["id"]
                self._fast_auth_deferred = True
                return True

        res = self._call_get_account_list()
        if res.status_code == 200:
            self._parse_webull_accounts(res.json())
            self._fast_auth_deferred = False
            return True
        raise RuntimeError(
            f"Webull authentication failed (HTTP {res.status_code}): {res.text}"
        )

    def reconnect_session(self):
        """Refreshes Webull client timeout state (or rebuilds ApiClient/TradeClient
        atomically on auth/token errors) without clobbering the active in-memory
        access token if a reconnect attempt times out mid-outage."""
        try:
            err_l = str(getattr(self, "last_error", "") or "").lower()
            needs_full_reinit = (
                self.api_client is None
                or self.trade_client is None
                or any(
                    k in err_l
                    for k in (
                        "401",
                        "403",
                        "unauthorized",
                        "token",
                        "expired",
                        "sign",
                    )
                )
            )
            if not needs_full_reinit:
                self.api_client._connect_timeout = 3.5
                self.api_client._read_timeout = 4.5
                if not self.api_client.get_token():
                    tok_file = os.path.join(USER_HOME, "conf", "token.txt")
                    if os.path.exists(tok_file):
                        try:
                            with open(tok_file, "r", encoding="utf-8") as tf:
                                saved_tok = tf.readline().strip()
                            if saved_tok:
                                self.api_client.set_token(saved_tok)
                        except Exception:
                            pass
                return True

            from webull.core.client import ApiClient
            from webull.trade.trade_client import TradeClient
            old_tok = (
                self.api_client.get_token()
                if self.api_client is not None
                else None
            )
            try:
                new_api = ApiClient(
                    self.app_key,
                    self.app_secret,
                    "us",
                    connect_timeout=3.5,
                    timeout=4.5,
                )
            except TypeError:
                new_api = ApiClient(self.app_key, self.app_secret, "us")
                new_api._connect_timeout = 3.5
                new_api._read_timeout = 4.5
            new_api._stream_logger_set = True
            new_api._file_logger_set = True
            if hasattr(new_api, "set_token_dir"):
                new_api.set_token_dir(os.path.join(USER_HOME, "conf"))
            new_api.add_endpoint("us", "api.webull.com")
            if old_tok and not new_api.get_token():
                new_api.set_token(old_tok)
            new_trade = TradeClient(new_api)
            self.api_client = new_api
            self.trade_client = new_trade
            try:
                from webull.data.data_client import DataClient
                self.data_client = DataClient(new_api)
            except Exception:
                self.data_client = None
            self._ensure_orders_cache_infra()
            with self._cache_lock:
                self._snapshot_gen += 1
                self._raw_orders_window_cache.clear()
                self._filled_since_cache.clear()
                self._filled_today_cache.clear()
            self._trade_perm_cache.pop(self.account_id, None)
            return True
        except Exception as e:
            self.last_error = str(e)
            return False

    def _call_get_account_list(self):
        if hasattr(self.trade_client, "account_v2"):
            return self.trade_client.account_v2.get_account_list()
        return self.trade_client.get_account_list()

    def _call_get_balance(self, acct_id=None):
        target_id = acct_id or self.account_id
        if hasattr(self.trade_client, "account_v2"):
            return self.trade_client.account_v2.get_account_balance(target_id)
        return self.trade_client.get_account_balance(target_id)

    def _call_get_positions(self, acct_id=None):
        target_id = acct_id or self.account_id
        try:
            if hasattr(self.trade_client, "account_v2"):
                return self.trade_client.account_v2.get_account_position(target_id)
            return self.trade_client.get_account_position(target_id)
        finally:
            self._last_pos_call_ts = time.time()

    def _normalize_webull_equity_qty(self, p, sym=""):
        try:
            qty = float(p.get("quantity") or p.get("position") or 0.0)
        except Exception:
            qty = 0.0
        side_hint = str(
            p.get("side") or p.get("position_side") or ""
        ).upper()
        if qty > 0 and side_hint == "SHORT":
            qty = -abs(qty)
            if sym and sym not in self._logged_short_sign_syms:
                self._logged_short_sign_syms.add(sym)
                log_event(
                    "GUARDRAIL",
                    f"Normalized Webull short equity quantity sign via side='{side_hint}' for {sym}: {qty:g}",
                )
        return qty

    def _fetch_all_open_orders_webull(self):
        """Fetches all open orders on Webull (using list_order_open pagination
        up to 10 pages before canceling, with fallback to get_order_open)."""
        if not self.trade_client or not self.account_id:
            return None
        collected = []
        seen_ids = set()

        def _append_from_payload(payload):
            items = (
                payload
                if isinstance(payload, list)
                else payload.get("data", payload.get("orders", []))
                if isinstance(payload, dict)
                else []
            )
            if not isinstance(items, list):
                return [], None
            added = []
            for item in items:
                if not isinstance(item, dict):
                    continue
                sub_ords = item.get("orders")
                own_cid = item.get("client_order_id") or item.get("order_id")
                if isinstance(sub_ords, list) and sub_ords and not own_cid:
                    wb_gid = (
                        f"WB_OCO_{item.get('combo_id') or id(item)}"
                        if len(sub_ords) > 1
                        else None
                    )
                    for sub_it in sub_ords:
                        if not isinstance(sub_it, dict):
                            continue
                        s_oid = str(
                            sub_it.get("client_order_id")
                            or sub_it.get("order_id")
                            or id(sub_it)
                        )
                        if s_oid not in seen_ids:
                            seen_ids.add(s_oid)
                            sub_cp = dict(sub_it)
                            if wb_gid:
                                sub_cp["_wb_oco_gid"] = wb_gid
                            collected.append(sub_cp)
                            added.append(sub_cp)
                else:
                    oid = str(own_cid or id(item))
                    if oid not in seen_ids:
                        seen_ids.add(oid)
                        collected.append(item)
                        added.append(item)
            next_k = None
            if isinstance(payload, dict):
                next_k = (
                    payload.get("pagination_key")
                    or payload.get("next_pagination_key")
                    or payload.get("next_page_token")
                )
            return added, next_k

        used_list_v3 = False
        if hasattr(self.trade_client, "order_v3") and hasattr(
            self.trade_client.order_v3, "list_order_open"
        ):
            try:
                page_key = None
                seen_page_keys = set()
                for _ in range(10):
                    if page_key:
                        if page_key in seen_page_keys:
                            break
                        seen_page_keys.add(page_key)
                        r_p = self.trade_client.order_v3.list_order_open(
                            self.account_id, pagination_key=page_key
                        )
                    else:
                        r_p = self.trade_client.order_v3.list_order_open(
                            self.account_id
                        )
                    if r_p is None or getattr(r_p, "status_code", None) != 200:
                        break
                    used_list_v3 = True
                    added_page, next_k = _append_from_payload(r_p.json())
                    if not added_page:
                        break
                    if not next_k and len(added_page) >= 20:
                        last_o = added_page[-1]
                        next_k = last_o.get("pagination_key")
                    if not next_k:
                        break
                    page_key = str(next_k)
            except Exception:
                pass

        if used_list_v3:
            return collected

        res = None
        if hasattr(self.trade_client, "order_v3") and hasattr(
            self.trade_client.order_v3, "get_order_open"
        ):
            try:
                res = self.trade_client.order_v3.get_order_open(
                    account_id=self.account_id, page_size=100
                )
            except TypeError:
                res = self.trade_client.order_v3.get_order_open(
                    account_id=self.account_id
                )
        elif hasattr(self.trade_client, "order_v2") and hasattr(
            self.trade_client.order_v2, "get_order_open"
        ):
            try:
                res = self.trade_client.order_v2.get_order_open(
                    account_id=self.account_id, page_size=100
                )
            except TypeError:
                res = self.trade_client.order_v2.get_order_open(
                    account_id=self.account_id
                )
        elif hasattr(self.trade_client, "get_open_orders"):
            res = self.trade_client.get_open_orders(self.account_id)

        if res is not None and getattr(res, "status_code", None) == 200:
            _append_from_payload(res.json())
            return collected
        return None

    def get_recent_exit_order_coverage(
        self, symbol, is_short=False, since_epoch=None, is_opt=False
    ):
        """Checks Webull open orders and any recent pending client_order_id for
        `symbol` in the closing direction. Returns (working_qty, recent_filled_qty)."""
        self.last_coverage_lookup_failed = False
        self._last_cov_saw_dead_pend = False
        if not self.trade_client or not self.account_id or not symbol:
            self.last_coverage_lookup_failed = True
            return 0.0, 0.0
        target_sym = str(symbol).strip()
        closing_side = "BUY" if is_short else "SELL"
        working_qty = 0.0
        oco_groups = {}
        filled_qty = 0.0
        seen_cids = set()
        open_lookup_ok = False
        detail_lookup_ok = False
        cutoff = (
            float(math.floor(float(since_epoch)))
            if since_epoch is not None
            else (time.time() - 180.0)
        )

        try:
            open_orders_raw = self._fetch_all_open_orders_webull()
            if open_orders_raw is not None:
                open_lookup_ok = True
            open_orders = open_orders_raw or []
            for o in open_orders:
                if not isinstance(o, dict):
                    continue
                o_itype = str(
                    o.get("instrument_type")
                    or o.get("asset_type")
                    or "EQUITY"
                ).upper()
                o_is_opt = ("OPT" in o_itype) or bool(o.get("legs"))
                if is_opt != o_is_opt:
                    continue
                if o_is_opt:
                    o_meta = self._parse_option_contract_meta(o)
                    o_sym = o_meta.get("display_sym") or o_meta.get(
                        "raw_symbol", ""
                    )
                else:
                    o_sym = (
                        o.get("symbol")
                        or (o.get("ticker") or {}).get("symbol")
                        or ""
                    )
                if str(o_sym or "").strip() != target_sym:
                    continue
                o_side = str(o.get("side") or o.get("action") or "").upper()
                if o_side != closing_side:
                    continue
                cid = str(
                    o.get("client_order_id") or o.get("order_id") or ""
                ).strip()
                if cid:
                    seen_cids.add(cid)
                try:
                    raw_fq = (
                        o["filled_quantity"]
                        if o.get("filled_quantity") is not None
                        else o["filled_qty"]
                        if o.get("filled_qty") is not None
                        else o.get("total_filled_quantity")
                    )
                    f_q = float(raw_fq) if raw_fq is not None else 0.0
                except Exception:
                    f_q = 0.0
                try:
                    raw_orig = (
                        o["total_quantity"]
                        if o.get("total_quantity") is not None
                        else o.get("quantity")
                    )
                    orig_q = float(raw_orig) if raw_orig is not None else 0.0
                except Exception:
                    orig_q = 0.0
                try:
                    raw_rem = (
                        o["remain_quantity"]
                        if o.get("remain_quantity") is not None
                        else o.get("unfilled_quantity")
                    )
                    rem_q = (
                        float(raw_rem)
                        if raw_rem is not None
                        else max(0.0, orig_q - f_q)
                    )
                except Exception:
                    rem_q = 0.0

                fill_ep = self._webull_ts_to_epoch(
                    o.get("filled_time") or o.get("update_time")
                )
                has_fill_ts = fill_ep > 0.0
                wb_gid_cov = o.get("_wb_oco_gid")
                if wb_gid_cov:
                    b = oco_groups.setdefault(
                        wb_gid_cov,
                        {
                            "init_max": 0.0,
                            "work_max": 0.0,
                            "filled_all": 0.0,
                            "filled_recent": 0.0,
                            "all_fills_timed": True,
                        },
                    )
                    b["init_max"] = max(b["init_max"], orig_q, rem_q + f_q)
                    if rem_q > 0:
                        b["work_max"] = max(b["work_max"], rem_q)
                    if f_q > 0:
                        if has_fill_ts:
                            b["filled_all"] += f_q
                            if fill_ep >= cutoff:
                                b["filled_recent"] += f_q
                        else:
                            b["all_fills_timed"] = False
                else:
                    if rem_q > 0:
                        working_qty += rem_q
                    if f_q > 0 and has_fill_ts and fill_ep >= cutoff:
                        filled_qty += f_q
            for b in oco_groups.values():
                i_max = b["init_max"]
                if b["all_fills_timed"] and i_max > 0:
                    grp_working = min(
                        b["work_max"], max(0.0, i_max - b["filled_all"])
                    )
                    grp_filled_rec = min(b["filled_recent"], i_max)
                else:
                    grp_working = (
                        min(b["work_max"], i_max) if i_max > 0 else b["work_max"]
                    )
                    grp_filled_rec = (
                        min(b["filled_recent"], i_max)
                        if i_max > 0
                        else b["filled_recent"]
                    )
                working_qty += grp_working
                filled_qty += grp_filled_rec
        except Exception:
            pass

        pend = self._pending_flatten_cids.get((self.account_id, target_sym))
        need_detail_lookup = bool(
            pend and pend[0] not in seen_cids and float(pend[1]) >= cutoff
        )
        if need_detail_lookup:
            cid = pend[0]
            d_obj = None
            try:
                if hasattr(self.trade_client, "order_v3") and hasattr(
                    self.trade_client.order_v3, "get_order_detail"
                ):
                    d_res = self.trade_client.order_v3.get_order_detail(
                        self.account_id, cid
                    )
                elif hasattr(self.trade_client, "order") and hasattr(
                    self.trade_client.order, "query_order_detail"
                ):
                    d_res = self.trade_client.order.query_order_detail(
                        self.account_id, cid
                    )
                else:
                    d_res = None
                if (
                    d_res is not None
                    and getattr(d_res, "status_code", None) == 200
                ):
                    detail_lookup_ok = True
                    d_json = d_res.json()
                    cand = (
                        d_json.get("data", d_json)
                        if isinstance(d_json, dict)
                        else {}
                    )
                    if isinstance(cand, dict):
                        d_obj = cand
            except Exception:
                pass

            if d_obj is None:
                try:
                    t_res = None
                    if hasattr(self.trade_client, "order") and hasattr(
                        self.trade_client.order, "list_today_orders"
                    ):
                        t_res = self.trade_client.order.list_today_orders(
                            self.account_id, page_size=100
                        )
                    elif hasattr(self.trade_client, "order_v3") and hasattr(
                        self.trade_client.order_v3, "list_order_history"
                    ):
                        t_res = self.trade_client.order_v3.list_order_history(
                            self.account_id
                        )
                    if (
                        t_res is not None
                        and getattr(t_res, "status_code", None) == 200
                    ):
                        detail_lookup_ok = True
                        t_json = t_res.json()
                        t_list = (
                            t_json
                            if isinstance(t_json, list)
                            else t_json.get(
                                "data", t_json.get("orders", [])
                            )
                            if isinstance(t_json, dict)
                            else []
                        )
                        if isinstance(t_list, list):
                            for item_o in t_list:
                                if not isinstance(item_o, dict):
                                    continue
                                if (
                                    str(
                                        item_o.get("client_order_id")
                                        or item_o.get("order_id")
                                        or ""
                                    ).strip()
                                    == str(cid).strip()
                                ):
                                    d_obj = item_o
                                    break
                except Exception:
                    pass

            if isinstance(d_obj, dict):
                st = str(
                    d_obj.get("status")
                    or d_obj.get("order_status")
                    or ""
                ).upper()
                if st in ("CANCELED", "CANCELLED", "REJECTED", "EXPIRED", "FAILED"):
                    self._last_cov_saw_dead_pend = True
                try:
                    fq = float(
                        d_obj.get("filled_quantity")
                        or d_obj.get("filled_qty")
                        or d_obj.get("total_filled_quantity")
                        or 0.0
                    )
                except Exception:
                    fq = 0.0
                try:
                    rq = float(
                        d_obj.get("remain_quantity")
                        or d_obj.get("unfilled_quantity")
                        or 0.0
                    )
                except Exception:
                    rq = 0.0
                if st in (
                    "WORKING",
                    "NEW",
                    "SUBMITTED",
                    "PENDING",
                    "PARTIAL_FILLED",
                    "PARTIALLY_FILLED",
                    "QUEUED",
                ):
                    working_qty += (
                        rq if rq > 0 else max(0.0, float(pend[2]) - fq)
                    )
                if fq > 0 or st == "FILLED":
                    filled_qty += fq if fq > 0 else float(pend[2])

        if not open_lookup_ok or (need_detail_lookup and not detail_lookup_ok):
            self.last_coverage_lookup_failed = True
        return working_qty, filled_qty

    def cancel_all_working_orders(
        self, preserve_market_close_map=None, cancel_options=True
    ):
        self.last_preserved_close_qty = {}
        self.last_cancel_failed_syms = set()
        preserve_map = (
            dict(preserve_market_close_map)
            if isinstance(preserve_market_close_map, dict)
            else {}
        )
        try:
            orders = self._fetch_all_open_orders_webull()
            if orders is not None:
                cancelled_any = False
                preserved_any = False
                wb_cancelled_oco_groups = set()
                wb_cascade_candidates = []
                for o in orders:
                    cid = (
                        o.get("client_order_id")
                        or o.get("order_id")
                    )
                    if cid:
                        masked_cid = _mask_last4(cid)
                        o_itype = str(
                            o.get("instrument_type")
                            or o.get("asset_type")
                            or "EQUITY"
                        ).upper()
                        o_is_opt = ("OPT" in o_itype) or bool(o.get("legs"))
                        if o_is_opt:
                            o_meta = self._parse_option_contract_meta(o)
                            o_sym = o_meta.get("display_sym") or o_meta.get(
                                "raw_symbol", ""
                            )
                        else:
                            o_sym = (
                                o.get("symbol")
                                or (o.get("ticker") or {}).get("symbol")
                                or ""
                            )
                        o_sym = str(o_sym or "").strip()
                        if o_sym and (
                            is_position_ignored(o_sym, is_opt=o_is_opt)
                            or (
                                not _manual_flatten_in_flight
                                and is_launch_grace_position(
                                    o_sym, is_opt=o_is_opt
                                )
                            )
                        ):
                            log_event(
                                "FLATTEN",
                                f"Skipping working Webull order {masked_cid} on ignored/exempt pre-existing ticker: {o_sym}",
                            )
                            continue

                        if not cancel_options and o_is_opt:
                            o_intent = str(
                                o.get("position_intent") or ""
                            ).upper()
                            o_legs = [
                                lg
                                for lg in (o.get("legs") or [])
                                if isinstance(lg, dict)
                            ]
                            if o_legs:
                                all_opt_closing = all(
                                    str(
                                        lg.get("position_intent") or o_intent
                                    ).upper()
                                    in ("SELL_TO_CLOSE", "BUY_TO_CLOSE")
                                    for lg in o_legs
                                )
                            else:
                                all_opt_closing = o_intent in (
                                    "SELL_TO_CLOSE",
                                    "BUY_TO_CLOSE",
                                )
                            if all_opt_closing:
                                preserved_any = True
                                log_event(
                                    "FLATTEN",
                                    f"Preserving protective/closing Webull option order {masked_cid} — "
                                    f"Options Auto-Flatten not active for this sweep.",
                                )
                                continue

                        o_type = str(
                            o.get("order_type") or o.get("orderType") or ""
                        ).upper()
                        o_side = str(
                            o.get("side") or o.get("action") or ""
                        ).upper()
                        try:
                            o_qty = float(
                                o.get("remain_quantity")
                                or o.get("unfilled_quantity")
                                or o.get("quantity")
                                or o.get("total_quantity")
                                or 0.0
                            )
                        except Exception:
                            o_qty = 0.0

                        is_closing_dir = False
                        if o_sym and o_sym in preserve_map:
                            open_q = float(preserve_map[o_sym])
                            if open_q > 0 and o_side == "SELL":
                                is_closing_dir = True
                            elif open_q < 0 and o_side == "BUY":
                                is_closing_dir = True

                        if (
                            is_closing_dir
                            and is_market_hours()
                            and o_type in ("MARKET", "MKT")
                        ):
                            eff_q = (
                                o_qty
                                if o_qty > 0
                                else abs(float(preserve_map[o_sym]))
                            )
                            self.last_preserved_close_qty[o_sym] = (
                                self.last_preserved_close_qty.get(o_sym, 0.0)
                                + eff_q
                            )
                            preserved_any = True
                            log_event(
                                "FLATTEN",
                                f"Preserving working Webull RTH Market close order {masked_cid} "
                                f"({o_side} {eff_q:g} {o_sym}) — "
                                f"keeping halt/auction queue priority.",
                            )
                            continue

                        log_event(
                            "FLATTEN", f"Canceling Webull order ID: {masked_cid}"
                        )
                        cancel_ok = False
                        deferred_cascade = False
                        try:
                            if hasattr(self.trade_client, "order_v3"):
                                c_res = (
                                    self.trade_client.order_v3.cancel_order(
                                        self.account_id, cid
                                    )
                                )
                            else:
                                c_res = self.trade_client.cancel_order(
                                    self.account_id, cid
                                )
                            code = c_resp_code(c_res)
                            log_event(
                                "FLATTEN",
                                f"Cancel response {masked_cid}: HTTP {code}"
                            )
                            wb_gid = o.get("_wb_oco_gid")
                            if code in (200, 201, 202, 204, "OK"):
                                cancelled_any = True
                                cancel_ok = True
                                if wb_gid:
                                    wb_cancelled_oco_groups.add(wb_gid)
                            elif (
                                code in (400, 404, 409, 422)
                                and wb_gid
                                and wb_gid in wb_cancelled_oco_groups
                            ):
                                deferred_cascade = True
                                wb_cascade_candidates.append(
                                    (
                                        str(cid).strip(),
                                        masked_cid,
                                        o_sym,
                                        is_closing_dir,
                                        o_qty,
                                    )
                                )
                        except Exception as ce:
                            log_event(
                                "ERROR",
                                f"Webull cancel_order {masked_cid} exception: {ce}",
                            )
                        if not cancel_ok and not deferred_cascade:
                            if o_sym:
                                self.last_cancel_failed_syms.add(o_sym)
                            if is_closing_dir and o_sym:
                                eff_q = (
                                    o_qty
                                    if o_qty > 0
                                    else abs(float(preserve_map[o_sym]))
                                )
                                self.last_preserved_close_qty[o_sym] = (
                                    self.last_preserved_close_qty.get(
                                        o_sym, 0.0
                                    )
                                    + eff_q
                                )
                if wb_cascade_candidates:
                    recheck_open = None
                    try:
                        recheck_open = self._fetch_all_open_orders_webull()
                    except Exception:
                        recheck_open = None
                    still_open_cids = {
                        str(
                            ro.get("client_order_id")
                            or ro.get("order_id")
                            or ""
                        ).strip()
                        for ro in (recheck_open or [])
                        if isinstance(ro, dict)
                    }
                    for (
                        c_cid,
                        c_masked,
                        c_sym,
                        c_is_cl,
                        c_qty,
                    ) in wb_cascade_candidates:
                        if (
                            recheck_open is not None
                            and c_cid
                            and c_cid not in still_open_cids
                        ):
                            cancelled_any = True
                            log_event(
                                "FLATTEN",
                                f"Webull order {c_masked} confirmed cascade-canceled via OCO sibling.",
                            )
                        else:
                            log_event(
                                "WARN",
                                f"Webull OCO sibling {c_masked} returned HTTP 400/404 and remains open/unverified — marking cancel failed!",
                            )
                            if c_sym:
                                self.last_cancel_failed_syms.add(c_sym)
                            if c_is_cl and c_sym:
                                eff_cq = (
                                    c_qty
                                    if c_qty > 0
                                    else abs(float(preserve_map.get(c_sym, 0.0)))
                                )
                                self.last_preserved_close_qty[c_sym] = (
                                    self.last_preserved_close_qty.get(
                                        c_sym, 0.0
                                    )
                                    + eff_cq
                                )
                if cancelled_any:
                    time.sleep(0.2)
                elif not preserved_any:
                    log_event("FLATTEN", "No working Webull orders to cancel.")
                return cancelled_any
        except Exception as e:
            log_event("ERROR", f"Webull cancel working orders exception: {e}")
        return False

    def _get_orders_window_cached(self, ttl_sec=8.0):
        """Coalesces concurrent Webull order-history queries behind a timeout-
        bounded single-flight lock and caches the raw today order list for
        `ttl_sec` seconds keyed by `(account_id, _snapshot_gen, today_str)`
        while isolating `reconnect_session()` / `invalidate_cached_snapshots()`."""
        self._ensure_orders_cache_infra()
        if not self.trade_client or not self.account_id:
            return None
        today_str = get_today_str()

        def _lookup_wb_locked(
            acct_k, gen_k, tc_obj, inv_sig, cur_snap_ep, now_t
        ):
            cand = self._raw_orders_window_cache.get((acct_k, gen_k, today_str))
            if (
                isinstance(cand, tuple)
                and len(cand) >= 7
                and (now_t - float(cand[0])) < float(ttl_sec)
                and cand[2] is tc_obj
                and cand[3] is self._filled_since_cache
                and cand[4] is self._filled_today_cache
                and cand[5] == inv_sig
                and (
                    cur_snap_ep <= 0.0
                    or float(cand[1]) <= 0.0
                    or abs(cur_snap_ep - float(cand[1])) < float(ttl_sec)
                )
            ):
                return list(cand[6])
            return None

        acct_cur = str(self.account_id)
        inv_sig_cur = _compute_orders_cache_inv_sig(self, acct_cur)
        snap_ep_cur = self.get_last_snapshot_epoch()
        with self._cache_lock:
            hit = _lookup_wb_locked(
                acct_cur,
                self._snapshot_gen,
                self.trade_client,
                inv_sig_cur,
                snap_ep_cur,
                time.time(),
            )
        if hit is not None:
            return hit

        acquired = self._orders_fetch_lock.acquire(timeout=6.0)
        try:
            with self._cache_lock:
                gen_before = self._snapshot_gen
                tc_before = self.trade_client
                acct_before = str(self.account_id or "")
                fs_before = self._filled_since_cache
                ft_before = self._filled_today_cache
                inv_sig_before = _compute_orders_cache_inv_sig(self, acct_before)
                snap_ep_before = self.get_last_snapshot_epoch()
                hit2 = _lookup_wb_locked(
                    acct_before,
                    gen_before,
                    tc_before,
                    inv_sig_before,
                    snap_ep_before,
                    time.time(),
                )
            if hit2 is not None:
                return hit2
            if not tc_before or not acct_before:
                return None

            wb_raw_orders = []
            wb_seen_ids = set()
            wb_fetch_ok = False
            t0 = time.monotonic()

            def _extract_wb_items(payload):
                items = (
                    payload
                    if isinstance(payload, list)
                    else payload.get("data", payload.get("orders", []))
                    if isinstance(payload, dict)
                    else []
                )
                if not isinstance(items, list):
                    return [], None
                added = []
                for it in items:
                    if not isinstance(it, dict):
                        continue
                    sub_ords = it.get("orders")
                    has_own_qty = any(
                        it.get(k) is not None
                        for k in (
                            "filled_quantity",
                            "filled_qty",
                            "total_filled_quantity",
                            "filledQuantity",
                        )
                    )
                    if isinstance(sub_ords, list) and sub_ords and not has_own_qty:
                        for sub_it in sub_ords:
                            if isinstance(sub_it, dict):
                                added.append(sub_it)
                    else:
                        added.append(it)
                next_tok = None
                if isinstance(payload, dict):
                    next_tok = (
                        payload.get("pagination_key")
                        or payload.get("next_pagination_key")
                        or payload.get("next_page_token")
                    )
                return added, next_tok

            def _register_wb_batch(batch_list):
                new_cnt = 0
                last_cid = None
                for item_o in batch_list:
                    cid_v = str(
                        item_o.get("client_order_id")
                        or item_o.get("order_id")
                        or ""
                    ).strip()
                    if cid_v:
                        last_cid = (
                            str(item_o.get("client_order_id") or "").strip()
                            or last_cid
                        )
                        if cid_v in wb_seen_ids:
                            continue
                        wb_seen_ids.add(cid_v)
                    else:
                        ptr_k = f"PTR_{id(item_o)}"
                        if ptr_k in wb_seen_ids:
                            continue
                        wb_seen_ids.add(ptr_k)
                    wb_raw_orders.append(item_o)
                    new_cnt += 1
                return new_cnt, last_cid

            if hasattr(tc_before, "order_v3") and hasattr(
                tc_before.order_v3, "get_order_history"
            ):
                last_cid_cursor = None
                for _ in range(10):
                    try:
                        if last_cid_cursor:
                            res_h = tc_before.order_v3.get_order_history(
                                account_id=acct_before,
                                page_size=100,
                                start_date=today_str,
                                end_date=today_str,
                                last_client_order_id=last_cid_cursor,
                            )
                        else:
                            res_h = tc_before.order_v3.get_order_history(
                                account_id=acct_before,
                                page_size=100,
                                start_date=today_str,
                                end_date=today_str,
                            )
                    except TypeError:
                        if last_cid_cursor:
                            break
                        res_h = tc_before.order_v3.get_order_history(
                            account_id=acct_before, page_size=100
                        )
                    if res_h is None or getattr(res_h, "status_code", None) != 200:
                        break
                    wb_fetch_ok = True
                    b_items, _ = _extract_wb_items(res_h.json())
                    if not b_items:
                        break
                    n_added, next_cid = _register_wb_batch(b_items)
                    if n_added <= 0 or len(b_items) < 100 or not next_cid:
                        break
                    last_cid_cursor = next_cid

            if (
                not wb_fetch_ok
                and hasattr(tc_before, "order_v3")
                and hasattr(tc_before.order_v3, "list_order_history")
            ):
                pg_key = None
                seen_pg = set()
                for _ in range(10):
                    if pg_key:
                        if pg_key in seen_pg:
                            break
                        seen_pg.add(pg_key)
                        res_lh = tc_before.order_v3.list_order_history(
                            acct_before, pagination_key=pg_key
                        )
                    else:
                        res_lh = tc_before.order_v3.list_order_history(
                            acct_before
                        )
                    if res_lh is None or getattr(res_lh, "status_code", None) != 200:
                        break
                    wb_fetch_ok = True
                    b_items, next_pg = _extract_wb_items(res_lh.json())
                    if not b_items:
                        break
                    n_added, _ = _register_wb_batch(b_items)
                    if n_added <= 0 or not next_pg:
                        break
                    pg_key = str(next_pg)

            if (
                not wb_fetch_ok
                and hasattr(tc_before, "order_v2")
                and hasattr(tc_before.order_v2, "get_order_history")
            ):
                last_cid_v2 = None
                for _ in range(10):
                    try:
                        if last_cid_v2:
                            res_v2 = tc_before.order_v2.get_order_history(
                                account_id=acct_before,
                                page_size=100,
                                start_date=today_str,
                                end_date=today_str,
                                last_client_order_id=last_cid_v2,
                            )
                        else:
                            res_v2 = tc_before.order_v2.get_order_history(
                                account_id=acct_before,
                                page_size=100,
                                start_date=today_str,
                                end_date=today_str,
                            )
                    except TypeError:
                        if last_cid_v2:
                            break
                        res_v2 = tc_before.order_v2.get_order_history(
                            account_id=acct_before, page_size=100
                        )
                    if res_v2 is None or getattr(res_v2, "status_code", None) != 200:
                        break
                    wb_fetch_ok = True
                    b_items, _ = _extract_wb_items(res_v2.json())
                    if not b_items:
                        break
                    n_added, next_cid = _register_wb_batch(b_items)
                    if n_added <= 0 or len(b_items) < 100 or not next_cid:
                        break
                    last_cid_v2 = next_cid

            if (
                not wb_fetch_ok
                and hasattr(tc_before, "order")
                and hasattr(tc_before.order, "list_today_orders")
            ):
                last_cid_td = None
                for _ in range(10):
                    if last_cid_td:
                        res_td = tc_before.order.list_today_orders(
                            acct_before,
                            page_size=100,
                            last_client_order_id=last_cid_td,
                        )
                    else:
                        res_td = tc_before.order.list_today_orders(
                            acct_before, page_size=100
                        )
                    if res_td is None or getattr(res_td, "status_code", None) != 200:
                        break
                    wb_fetch_ok = True
                    b_items, _ = _extract_wb_items(res_td.json())
                    if not b_items:
                        break
                    n_added, next_cid = _register_wb_batch(b_items)
                    if n_added <= 0 or len(b_items) < 100 or not next_cid:
                        break
                    last_cid_td = next_cid

            if not wb_fetch_ok:
                return None

            dt_ms = (time.monotonic() - t0) * 1000.0
            if (
                dt_ms >= 250.0
                or first_poll_of_launch
                or not _initial_positions_verified
            ):
                log_event(
                    "PERF",
                    f"Webull order_history fetched {len(wb_raw_orders)} order(s) in {dt_ms:.0f}ms.",
                )
            with self._cache_lock:
                if (
                    self._snapshot_gen == gen_before
                    and self.trade_client is tc_before
                    and str(self.account_id or "") == acct_before
                ):
                    if len(self._raw_orders_window_cache) > 24:
                        self._raw_orders_window_cache.clear()
                    self._raw_orders_window_cache[(acct_before, gen_before, today_str)] = (
                        time.time(),
                        snap_ep_before,
                        tc_before,
                        fs_before,
                        ft_before,
                        inv_sig_before,
                        list(wb_raw_orders),
                    )
            return wb_raw_orders
        except Exception:
            return None
        finally:
            if acquired:
                try:
                    self._orders_fetch_lock.release()
                except Exception:
                    pass

    def has_any_filled_orders_today(self):
        """Returns False ONLY when the Webull API confirms zero orders have been
        filled (or partially filled) on today's US/Eastern calendar date.
        Defaults to True on any API error so baseline fee-drift absorption is
        100% fail-safe."""
        self._ensure_orders_cache_infra()
        if not self.trade_client or not self.account_id:
            return True
        today_str = get_today_str()
        gen_cur = int(getattr(self, "_snapshot_gen", 0))
        tc_cur = self.trade_client
        inv_sig_cur = _compute_orders_cache_inv_sig(self, str(self.account_id))
        cache_map = self._filled_today_cache
        c_key = (str(self.account_id), today_str)
        now_ts = time.time()
        cached = cache_map.get(c_key)
        if isinstance(cached, tuple) and len(cached) >= 5 and cached[2] is tc_cur:
            c_ts, c_val = float(cached[0]), bool(cached[1])
            if c_val:
                return True
            if (
                cached[3] == gen_cur
                and cached[4] == inv_sig_cur
                and (now_ts - c_ts) < 30.0
            ):
                return False
        try:
            orders = self._get_orders_window_cached()
            if not isinstance(orders, list):
                return True
            for o in orders:
                if not isinstance(o, dict):
                    continue
                st = str(
                    o.get("status") or o.get("order_status") or ""
                ).upper()
                try:
                    fq = float(
                        o.get("filled_quantity")
                        or o.get("filled_qty")
                        or o.get("total_filled_quantity")
                        or o.get("filledQuantity")
                        or 0.0
                    )
                except Exception:
                    fq = 0.0
                if fq <= 0.0 and st not in (
                    "FILLED",
                    "PARTIAL_FILLED",
                    "PARTIALLY_FILLED",
                ):
                    continue
                raw_t = str(
                    o.get("filled_time")
                    or o.get("update_time")
                    or o.get("create_time")
                    or o.get("placed_time")
                    or today_str
                )
                if (
                    today_str in raw_t
                    or not re.search(r"\d{4}-\d{2}-\d{2}", raw_t)
                    or SchwabAdapter._order_ts_to_eastern_date(raw_t) == today_str
                ):
                    if (
                        self.trade_client is tc_cur
                        and int(getattr(self, "_snapshot_gen", 0)) == gen_cur
                    ):
                        cache_map[c_key] = (
                            now_ts,
                            True,
                            tc_cur,
                            gen_cur,
                            inv_sig_cur,
                        )
                    return True
            if (
                self.trade_client is tc_cur
                and int(getattr(self, "_snapshot_gen", 0)) == gen_cur
            ):
                cache_map[c_key] = (
                    now_ts,
                    False,
                    tc_cur,
                    gen_cur,
                    inv_sig_cur,
                )
            return False
        except Exception:
            return True

    @staticmethod
    def _webull_ts_to_epoch(raw_ts):
        if raw_ts is None:
            return 0.0
        if isinstance(raw_ts, (int, float)):
            v = float(raw_ts)
            return v / 1000.0 if v > 1e12 else v
        s = str(raw_ts).strip()
        if not s:
            return 0.0
        if re.fullmatch(r"\d+(?:\.\d+)?", s):
            v = float(s)
            return v / 1000.0 if v > 1e12 else v
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            elif re.search(r"[+-]\d{4}$", s):
                s = s[:-2] + ":" + s[-2:]
            dt = datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return float(dt.timestamp())
        except Exception:
            return 0.0

    def has_non_ignored_closing_fills_since(
        self, since_epoch, was_flat_at_save=True
    ):
        """Returns True ONLY when the Webull API confirms at least one non-ignored
        closing order (or any non-ignored fill if the session saved while in a
        trade) executed on today's ET date at or after `since_epoch`."""
        if (
            not self.trade_client
            or not self.account_id
            or since_epoch is None
            or float(since_epoch) <= 0.0
        ):
            return False
        cutoff = float(since_epoch) - 2.0
        try:
            orders = self._get_orders_window_cached()
            if not isinstance(orders, list):
                return False
            for o in orders:
                if not isinstance(o, dict):
                    continue
                st = str(
                    o.get("status") or o.get("order_status") or ""
                ).upper()
                try:
                    fq = float(
                        o.get("filled_quantity")
                        or o.get("filled_qty")
                        or o.get("total_filled_quantity")
                        or o.get("filledQuantity")
                        or 0.0
                    )
                except Exception:
                    fq = 0.0
                if fq <= 0.0 and st not in (
                    "FILLED",
                    "PARTIAL_FILLED",
                    "PARTIALLY_FILLED",
                ):
                    continue
                raw_t = (
                    o.get("filled_time")
                    or o.get("update_time")
                    or o.get("create_time")
                    or o.get("placed_time")
                )
                ep = self._webull_ts_to_epoch(raw_t)
                if ep <= 0.0 or ep < cutoff:
                    continue
                o_itype = str(
                    o.get("instrument_type")
                    or o.get("asset_type")
                    or "EQUITY"
                ).upper()
                o_is_opt = ("OPT" in o_itype) or bool(o.get("legs"))
                if o_is_opt:
                    o_meta = self._parse_option_contract_meta(o)
                    o_sym = (
                        o_meta.get("display_sym")
                        or o_meta.get("raw_symbol", "")
                    )
                else:
                    o_sym = (
                        o.get("symbol")
                        or (o.get("ticker") or {}).get("symbol")
                        or ""
                    )
                o_sym = str(o_sym or "").strip()
                if not o_sym or is_position_ignored(o_sym, is_opt=o_is_opt):
                    continue
                o_side = str(o.get("side") or o.get("action") or "").upper()
                o_intent = str(
                    o.get("position_intent") or o.get("intent") or ""
                ).upper()
                is_closing = (
                    o_side == "SELL"
                    or "CLOSE" in o_intent
                    or "COVER" in o_intent
                )
                if (not was_flat_at_save) or is_closing:
                    return True
            return False
        except Exception:
            return False

    def fetch_filled_orders_since(self, since_epoch, fast_recent_only=False):
        """Fetches normalized filled Webull orders on today's ET date at or after
        `since_epoch` (using single-flight cached paginated order_v3.get_order_history
        with clean SDK fallbacks). Returns a chronologically sorted list of fill dicts,
        or None on API failure."""
        self._ensure_orders_cache_infra()
        if (
            not self.trade_client
            or not self.account_id
            or since_epoch is None
            or float(since_epoch) <= 0.0
        ):
            return None
        today_str = get_today_str()
        cutoff = float(since_epoch) - 2.0
        gen_start = int(getattr(self, "_snapshot_gen", 0))
        tc_start = self.trade_client
        inv_sig = _compute_orders_cache_inv_sig(self, str(self.account_id))
        fs_cache = self._filled_since_cache
        fs_key = (
            str(self.account_id),
            today_str,
            round(cutoff, 0),
            gen_start,
            inv_sig,
        )
        now_ts = time.time()
        fs_hit = fs_cache.get(fs_key)
        if (
            fs_hit is not None
            and len(fs_hit) >= 3
            and fs_hit[2] is self.trade_client
            and (now_ts - float(fs_hit[0])) < 6.0
        ):
            return json.loads(json.dumps(fs_hit[1]))

        try:
            eff_ord_ttl = (
                60.0 if (_off_session_reconciled and fast_recent_only) else 8.0
            )
            wb_raw_orders = self._get_orders_window_cached(
                ttl_sec=eff_ord_ttl
            )
            if not isinstance(wb_raw_orders, list):
                return None

            wb_out = []
            wb_seq = 0
            for o_idx, o in enumerate(wb_raw_orders):
                st = str(
                    o.get("status") or o.get("order_status") or ""
                ).upper()
                try:
                    fq = float(
                        o.get("filled_quantity")
                        or o.get("filled_qty")
                        or o.get("total_filled_quantity")
                        or o.get("filledQuantity")
                        or 0.0
                    )
                except Exception:
                    fq = 0.0
                if fq <= 0.0 and st not in (
                    "FILLED",
                    "PARTIAL_FILLED",
                    "PARTIALLY_FILLED",
                ):
                    continue
                if fq <= 0.0:
                    try:
                        fq = float(
                            o.get("quantity") or o.get("total_quantity") or 0.0
                        )
                    except Exception:
                        fq = 0.0
                if fq <= 0.0:
                    continue

                raw_t = (
                    o.get("filled_time")
                    or o.get("update_time")
                    or o.get("create_time")
                    or o.get("placed_time")
                )
                ep = self._webull_ts_to_epoch(raw_t)
                if ep <= 0.0 or ep < cutoff:
                    continue
                et_d = _utc_to_eastern_naive(
                    datetime.fromtimestamp(ep, tz=timezone.utc)
                ).strftime("%Y-%m-%d")
                if et_d != today_str:
                    continue

                oid_raw = str(
                    o.get("client_order_id") or o.get("order_id") or ""
                ).strip()
                legs_arr = o.get("legs")
                if isinstance(legs_arr, list) and len(legs_arr) > 1:
                    any_unignored_ml = False
                    for lg_m in legs_arr:
                        if not isinstance(lg_m, dict):
                            continue
                        lg_meta = self._parse_option_contract_meta(lg_m)
                        lg_ds = (
                            lg_meta.get("display_sym")
                            or lg_meta.get("raw_symbol")
                            or str(lg_m.get("symbol") or "").strip()
                        )
                        lg_opt = (
                            "OPT"
                            in str(
                                lg_m.get("instrument_type")
                                or o.get("instrument_type")
                                or "OPTION"
                            ).upper()
                        )
                        if not lg_ds or not is_position_ignored(lg_ds, is_opt=lg_opt):
                            any_unignored_ml = True
                            break
                    if not any_unignored_ml:
                        continue
                    wb_seq += 1
                    ml_id = oid_raw or f"ML_{ep:.3f}_{o_idx}"
                    wb_out.append(
                        {
                            "order_key": f"WB_ML:{ml_id}",
                            "order_id": oid_raw,
                            "symbol": "COMBO (OPT)",
                            "raw_symbol": "COMBO",
                            "asset_type": "OPTION",
                            "multiplier": 100.0,
                            "side": str(o.get("side") or "BUY").upper(),
                            "instruction": str(
                                o.get("position_intent") or o.get("side") or ""
                            ).upper(),
                            "total_filled_qty": fq,
                            "price": None,
                            "fill_epoch": ep,
                            "multi_leg_unknown": True,
                            "_seq": wb_seq,
                        }
                    )
                    continue

                o_itype = str(
                    o.get("instrument_type")
                    or o.get("asset_type")
                    or "EQUITY"
                ).upper()
                o_is_opt = ("OPT" in o_itype) or bool(legs_arr)
                if o_is_opt:
                    o_meta = self._parse_option_contract_meta(o)
                    disp_sym = (
                        o_meta.get("display_sym")
                        or o_meta.get("raw_symbol", "")
                    )
                    raw_sym = o_meta.get("raw_symbol") or disp_sym
                    tag_sym = (
                        disp_sym
                        if str(disp_sym).endswith(" (OPT)")
                        else f"{disp_sym} (OPT)"
                    )
                else:
                    disp_sym = str(
                        o.get("symbol")
                        or (o.get("ticker") or {}).get("symbol")
                        or ""
                    ).strip()
                    raw_sym = disp_sym
                    tag_sym = disp_sym
                if not disp_sym or is_position_ignored(disp_sym, is_opt=o_is_opt):
                    continue

                o_side = str(o.get("side") or o.get("action") or "").upper()
                if o_side not in ("BUY", "SELL"):
                    continue
                o_intent = str(
                    o.get("position_intent") or o.get("intent") or o_side
                ).upper()

                wb_px = None
                for px_k in (
                    "avg_filled_price",
                    "filled_price",
                    "avg_price",
                    "average_price",
                    "deal_avg_price",
                ):
                    if o.get(px_k) is not None and str(o.get(px_k)).strip() != "":
                        try:
                            c_px = float(o.get(px_k))
                            if c_px > 0.0:
                                wb_px = c_px
                                break
                        except Exception:
                            pass

                synth_id = oid_raw or f"SYNTH:{raw_sym}:{o_side}:{raw_t}"
                wb_seq += 1
                wb_out.append(
                    {
                        "order_key": f"WB_ORD:{synth_id}",
                        "order_id": oid_raw,
                        "symbol": tag_sym,
                        "raw_symbol": raw_sym,
                        "asset_type": "OPTION" if o_is_opt else "EQUITY",
                        "multiplier": 100.0 if o_is_opt else 1.0,
                        "side": o_side,
                        "instruction": o_intent,
                        "total_filled_qty": fq,
                        "price": wb_px,
                        "fill_epoch": ep,
                        "multi_leg_unknown": False,
                        "_seq": wb_seq,
                    }
                )

            wb_out.sort(key=lambda r: (float(r["fill_epoch"]), int(r["_seq"])))
            for r in wb_out:
                r.pop("_seq", None)
            with self._cache_lock:
                if (
                    int(getattr(self, "_snapshot_gen", 0)) == gen_start
                    and self.trade_client is tc_start
                ):
                    self._filled_since_cache[fs_key] = (
                        time.time(),
                        json.loads(json.dumps(wb_out)),
                        tc_start,
                    )
            return wb_out
        except Exception:
            return None

    @staticmethod
    def _parse_option_contract_meta(p):
        """Extracts normalized option contract metadata from a Webull position
        record (supporting both v2 'legs' arrays, top-level fields, and OCC symbols)."""
        legs = p.get("legs")
        leg0 = (
            legs[0]
            if isinstance(legs, list) and len(legs) > 0 and isinstance(legs[0], dict)
            else {}
        )
        raw_qty = (
            p.get("quantity")
            or p.get("position")
            or leg0.get("quantity")
            or leg0.get("position")
            or 0
        )
        try:
            qty = float(raw_qty)
        except Exception:
            qty = 0.0
        side_hint = str(
            p.get("side")
            or p.get("position_side")
            or leg0.get("side")
            or leg0.get("position_side")
            or ""
        ).upper()
        if qty > 0 and side_hint in ("SHORT", "SELL"):
            qty = -abs(qty)

        raw_sym = str(
            leg0.get("symbol")
            or p.get("symbol")
            or p.get("ticker", {}).get("symbol")
            or ""
        ).strip()
        opt_type = str(
            leg0.get("option_type")
            or p.get("option_type")
            or ""
        ).strip().upper()
        exp_date = str(
            leg0.get("option_expire_date")
            or p.get("option_expire_date")
            or leg0.get("expire_date")
            or p.get("expire_date")
            or ""
        ).strip()
        strike_raw = (
            leg0.get("option_exercise_pricestring")
            or leg0.get("option_exercise_price")
            or leg0.get("strike_price")
            or p.get("option_exercise_pricestring")
            or p.get("option_exercise_price")
            or p.get("strike_price")
            or ""
        )
        inst_id = str(
            leg0.get("instrument_id")
            or p.get("instrument_id")
            or p.get("ticker_id")
            or ""
        ).strip()

        underlying = raw_sym
        m_occ = re.match(
            r"^([A-Za-z]+)\s*(\d{2})(\d{2})(\d{2})([CPcp])(\d{8})$", raw_sym
        )
        if m_occ:
            underlying = m_occ.group(1).upper()
            if not exp_date:
                exp_date = f"20{m_occ.group(2)}-{m_occ.group(3)}-{m_occ.group(4)}"
            if not opt_type:
                opt_type = "CALL" if m_occ.group(5).upper() == "C" else "PUT"
            if not strike_raw:
                strike_val = int(m_occ.group(6)) / 1000.0
                strike_raw = f"{strike_val:g}"

        if opt_type.startswith("C"):
            opt_type = "CALL"
        elif opt_type.startswith("P"):
            opt_type = "PUT"

        strike_str = str(strike_raw).strip()
        if strike_str:
            try:
                sv = float(strike_str)
                strike_str = (
                    f"{int(sv)}" if abs(sv - round(sv)) < 1e-6 else f"{sv:g}"
                )
            except Exception:
                pass

        if underlying and exp_date and strike_str and opt_type:
            display_sym = f"{underlying} {exp_date} {strike_str}{opt_type[:1]}"
        else:
            display_sym = raw_sym or "UNKNOWN_OPT"

        return {
            "display_sym": display_sym,
            "qty": qty,
            "underlying": underlying,
            "option_type": opt_type,
            "option_expire_date": exp_date,
            "strike_price": strike_str,
            "instrument_id": inst_id,
            "raw_symbol": raw_sym,
        }

    def get_open_equity_positions(
        self,
        allow_stale_cache=True,
        pace_for_verify=False,
        cache_empty_ok=False,
    ):
        """Returns (symbol, qty, last_price) for EQUITIES ONLY, or None on API error."""
        snap_gen_at_start = self._snapshot_gen
        with self._cache_lock:
            cached = self._last_open_eq.get(self.account_id)
        if (
            allow_stale_cache
            and cached
            and (time.time() - cached[0]) < 0.45
            and (cached[1] or cache_empty_ok)
        ):
            return [
                item
                for item in cached[1]
                if not is_position_ignored(item[0], is_opt=False)
                and not is_uncloseable_fractional_qty(
                    self.account_id, item[0], item[1]
                )
            ]
        if (
            not pace_for_verify
            and allow_stale_cache
            and time.time() < self._rate_limit_until
            and cached
            and (time.time() - cached[0]) <= 2.5
            and (cached[1] or cache_empty_ok)
        ):
            return [
                item
                for item in cached[1]
                if not is_position_ignored(item[0], is_opt=False)
                and not is_uncloseable_fractional_qty(
                    self.account_id, item[0], item[1]
                )
            ]
        if pace_for_verify:
            self._pace_position_verify_call()
        try:
            res = self._call_get_positions()
            if res.status_code == 200:
                open_eq = []
                open_opt = []
                payload = res.json()
                pos_list = (
                    payload if isinstance(payload, list)
                    else payload.get("data", payload.get("positions", []))
                )
                for p in pos_list:
                    itype = str(
                        p.get("instrument_type")
                        or p.get("asset_type")
                        or "EQUITY"
                    ).upper()
                    is_opt = ("OPT" in itype) or bool(p.get("legs"))
                    if is_opt:
                        meta = self._parse_option_contract_meta(p)
                        if meta["qty"] != 0 and not is_position_ignored(
                            meta["display_sym"], is_opt=True
                        ):
                            open_opt.append(
                                (meta["display_sym"], meta["qty"], meta)
                            )
                        continue
                    sym = (
                        p.get("symbol")
                        or p.get("ticker", {}).get("symbol")
                        or ""
                    )
                    qty = self._normalize_webull_equity_qty(p, sym)
                    if qty != 0:
                        lp = float(
                            p.get("last_price")
                            or p.get("market_price")
                            or p.get("cost_price")
                            or 0.0
                        )
                        if (
                            sym
                            and not is_position_ignored(sym, is_opt=False)
                            and not is_uncloseable_fractional_qty(
                                self.account_id, sym, qty
                            )
                        ):
                            open_eq.append((sym, qty, lp))
                open_opt.sort(
                    key=lambda item: (0 if item[1] < 0 else 1, str(item[0]))
                )
                self._prune_pending_flatten_cids(
                    self.account_id,
                    {
                        **{sym: qty for sym, qty, _ in open_eq},
                        **{sym: qty for sym, qty, _ in open_opt},
                    },
                )
                self.last_positions_fetch_ok = True
                now_t = time.time()
                with self._cache_lock:
                    if self._snapshot_gen == snap_gen_at_start:
                        self._last_open_eq[self.account_id] = (now_t, list(open_eq))
                        self._last_open_opt[self.account_id] = (now_t, list(open_opt))
                return open_eq
            if res.status_code == 429:
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
            log_event(
                "ERROR",
                f"Webull get_open_equity_positions HTTP {res.status_code}"
            )
        except Exception as e:
            err_s = str(e)
            if "429" in err_s or "too many requests" in err_s.lower():
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
            log_event(
                "ERROR",
                f"Webull get_open_equity_positions exception: {e}"
            )
        self.last_positions_fetch_ok = False
        if allow_stale_cache:
            with self._cache_lock:
                cached = (
                    self._last_open_eq.get(self.account_id)
                    if self._snapshot_gen == snap_gen_at_start
                    else None
                )
            if cached and (time.time() - cached[0]) <= 10.0 and cached[1]:
                log_event(
                    "FLATTEN",
                    "Using cached Webull open equity snapshot (<10s) after API error."
                )
                return [
                    item
                    for item in cached[1]
                    if not is_position_ignored(item[0], is_opt=False)
                    and not is_uncloseable_fractional_qty(
                        self.account_id, item[0], item[1]
                    )
                ]
        return None

    def get_open_option_positions(
        self,
        allow_stale_cache=True,
        pace_for_verify=False,
        reuse_paired_eq_read=False,
    ):
        """Returns (display_sym, qty, meta) for OPTIONS ONLY sorted with short
        legs (qty < 0) first, or None on API error."""
        snap_gen_at_start = self._snapshot_gen
        with self._cache_lock:
            cached = self._last_open_opt.get(self.account_id)
        if (
            (allow_stale_cache or reuse_paired_eq_read)
            and cached
            and (time.time() - cached[0]) < 0.50
        ):
            return [
                item
                for item in cached[1]
                if not is_position_ignored(item[0], is_opt=True)
            ]
        if (
            not pace_for_verify
            and allow_stale_cache
            and time.time() < self._rate_limit_until
            and cached
            and (time.time() - cached[0]) <= 2.5
        ):
            return [
                item
                for item in cached[1]
                if not is_position_ignored(item[0], is_opt=True)
            ]
        if pace_for_verify:
            self._pace_position_verify_call()
        try:
            res = self._call_get_positions()
            if res.status_code == 200:
                open_eq = []
                open_opt = []
                payload = res.json()
                pos_list = (
                    payload if isinstance(payload, list)
                    else payload.get("data", payload.get("positions", []))
                )
                for p in pos_list:
                    itype = str(
                        p.get("instrument_type")
                        or p.get("asset_type")
                        or "EQUITY"
                    ).upper()
                    is_opt = ("OPT" in itype) or bool(p.get("legs"))
                    if is_opt:
                        meta = self._parse_option_contract_meta(p)
                        if meta["qty"] != 0 and not is_position_ignored(
                            meta["display_sym"], is_opt=True
                        ):
                            open_opt.append(
                                (meta["display_sym"], meta["qty"], meta)
                            )
                        continue
                    sym = (
                        p.get("symbol")
                        or p.get("ticker", {}).get("symbol")
                        or ""
                    )
                    qty = self._normalize_webull_equity_qty(p, sym)
                    if qty != 0:
                        lp = float(
                            p.get("last_price")
                            or p.get("market_price")
                            or p.get("cost_price")
                            or 0.0
                        )
                        if (
                            sym
                            and not is_position_ignored(sym, is_opt=False)
                            and not is_uncloseable_fractional_qty(
                                self.account_id, sym, qty
                            )
                        ):
                            open_eq.append((sym, qty, lp))
                open_opt.sort(
                    key=lambda item: (0 if item[1] < 0 else 1, str(item[0]))
                )
                self._prune_pending_flatten_cids(
                    self.account_id,
                    {
                        **{sym: qty for sym, qty, _ in open_eq},
                        **{sym: qty for sym, qty, _ in open_opt},
                    },
                )
                self.last_positions_fetch_ok = True
                now_t = time.time()
                with self._cache_lock:
                    if self._snapshot_gen == snap_gen_at_start:
                        self._last_open_eq[self.account_id] = (now_t, list(open_eq))
                        self._last_open_opt[self.account_id] = (now_t, list(open_opt))
                return open_opt
            if res.status_code == 429:
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
            log_event(
                "ERROR",
                f"Webull get_open_option_positions HTTP {res.status_code}"
            )
        except Exception as e:
            err_s = str(e)
            if "429" in err_s or "too many requests" in err_s.lower():
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
            log_event(
                "ERROR",
                f"Webull get_open_option_positions exception: {e}"
            )
        self.last_positions_fetch_ok = False
        if allow_stale_cache:
            with self._cache_lock:
                cached = (
                    self._last_open_opt.get(self.account_id)
                    if self._snapshot_gen == snap_gen_at_start
                    else None
                )
            if cached and (time.time() - cached[0]) <= 10.0 and cached[1]:
                log_event(
                    "FLATTEN",
                    "Using cached Webull open option snapshot (<10s) after API error."
                )
                return [
                    item
                    for item in cached[1]
                    if not is_position_ignored(item[0], is_opt=True)
                ]
        return None

    def submit_option_liquidation_batch(self, open_opt_positions):
        """Submits single-leg RTH Market option orders on Webull
        (BUY_TO_CLOSE on short legs first, then SELL_TO_CLOSE on long legs)."""
        submitted_ok = {}
        if not open_opt_positions:
            return submitted_ok
        if not is_market_hours():
            log_event(
                "GUARDRAIL",
                f"Cannot submit Webull option market flatten outside RTH "
                f"(9:30 AM – 4:00 PM ET): {[x[0] for x in open_opt_positions]}"
            )
            return submitted_ok

        self.invalidate_cached_snapshots()
        sorted_opts = sorted(
            open_opt_positions,
            key=lambda item: (0 if item[1] < 0 else 1, str(item[0])),
        )
        for item in sorted_opts:
            display_sym = str(item[0]).strip()
            qty = float(item[1])
            meta = item[2] if len(item) > 2 and isinstance(item[2], dict) else {}
            abs_q = int(abs(qty))
            if abs_q <= 0:
                continue

            attempt_ts = time.time()
            pend = self._pending_flatten_cids.get(
                (self.account_id, display_sym)
            )
            if pend and (attempt_ts - float(pend[1])) < 30.0:
                pend_sub_q = float(pend[2])
                pend_pos_q = float(pend[3]) if len(pend) > 3 else pend_sub_q
                pend_acc = bool(pend[4]) if len(pend) > 4 else False
                w_q, f_q = self.get_recent_exit_order_coverage(
                    display_sym,
                    is_short=(qty < 0),
                    since_epoch=pend[1],
                    is_opt=True,
                )
                same_stale_pos = abs(abs(qty) - abs(pend_pos_q)) <= 1e-6 and (
                    (qty < 0) == (pend_pos_q < 0) if len(pend) > 3 else True
                )
                if w_q >= (abs_q - 1e-6) or (
                    same_stale_pos
                    and (
                        (w_q + f_q) >= (abs_q - 1e-6)
                        or (
                            (pend_acc or self.last_coverage_lookup_failed)
                            and not self._last_cov_saw_dead_pend
                        )
                    )
                ):
                    log_event(
                        "FLATTEN",
                        f"Skipping duplicate Webull option close on {display_sym} "
                        f"(already working={w_q:g}, filled={f_q:g}).",
                    )
                    submitted_ok[display_sym] = float(max(w_q + f_q, pend_sub_q))
                    continue

            side = "BUY" if qty < 0 else "SELL"
            pos_intent = "BUY_TO_CLOSE" if qty < 0 else "SELL_TO_CLOSE"
            underlying = meta.get("underlying") or display_sym.split()[0]
            opt_type = meta.get("option_type") or ""
            exp_date = meta.get("option_expire_date") or ""
            strike_str = meta.get("strike_price") or ""
            inst_id = meta.get("instrument_id") or ""
            client_oid = uuid.uuid4().hex[:24]
            self._pending_flatten_cids[(self.account_id, display_sym)] = (
                client_oid,
                attempt_ts,
                float(abs_q),
                float(qty),
                False,
            )

            leg_item = {
                "instrument_type": "OPTION",
                "market": "US",
                "symbol": underlying,
                "side": side,
                "quantity": str(abs_q),
                "position_intent": pos_intent,
            }
            if opt_type:
                leg_item["option_type"] = opt_type
            if exp_date:
                leg_item["option_expire_date"] = exp_date
            if strike_str:
                leg_item["strike_price"] = strike_str
            if inst_id:
                leg_item["instrument_id"] = inst_id

            order_item = {
                "client_order_id": client_oid,
                "combo_type": "NORMAL",
                "option_strategy": "SINGLE",
                "instrument_type": "OPTION",
                "market": "US",
                "symbol": underlying,
                "order_type": "MARKET",
                "side": side,
                "position_intent": pos_intent,
                "quantity": str(abs_q),
                "time_in_force": "DAY",
                "support_trading_session": "CORE",
                "entrust_type": "QTY",
                "legs": [leg_item],
            }

            log_event(
                "ORDER_OUT",
                f"Submitting Webull RTH Option Market {pos_intent} (BETA): "
                f"{abs_q} {display_sym} ({_mask_last4(client_oid)})"
            )
            try:
                if hasattr(self.trade_client, "order_v3"):
                    r = self.trade_client.order_v3.place_order(
                        self.account_id, [order_item]
                    )
                elif hasattr(self.trade_client, "order_v2") and hasattr(
                    self.trade_client.order_v2, "place_option"
                ):
                    r = self.trade_client.order_v2.place_option(
                        self.account_id, [order_item]
                    )
                else:
                    r = self.trade_client.place_order(
                        self.account_id, order_item
                    )
                code = c_resp_code(r)
                if (
                    code not in (200, 201, "OK")
                    and hasattr(self.trade_client, "order_v2")
                    and hasattr(self.trade_client.order_v2, "place_option")
                ):
                    r2 = self.trade_client.order_v2.place_option(
                        self.account_id, [order_item]
                    )
                    code = c_resp_code(r2)
                    r = r2
                log_event(
                    "ORDER_RESP",
                    f"Webull Option {pos_intent} {display_sym} ({_mask_last4(client_oid)}) -> HTTP {code}"
                )
                if code in (200, 201, 202, "OK"):
                    self._pending_flatten_cids[
                        (self.account_id, display_sym)
                    ] = (
                        client_oid,
                        attempt_ts,
                        float(abs_q),
                        float(qty),
                        True,
                    )
                    submitted_ok[display_sym] = float(abs_q)
                else:
                    self._pending_flatten_cids.pop(
                        (self.account_id, display_sym), None
                    )
            except Exception as e:
                log_event(
                    "ERROR",
                    f"Webull option place_order exception ({display_sym}): {e}"
                )
                w_q, f_q = self.get_recent_exit_order_coverage(
                    display_sym,
                    is_short=(qty < 0),
                    since_epoch=attempt_ts,
                    is_opt=True,
                )
                if (w_q + f_q) > 0:
                    log_event(
                        "FLATTEN",
                        f"Verified timed-out Webull option close on {display_sym} is live/filled "
                        f"(working={w_q:g}, filled={f_q:g}); suppressing duplicate.",
                    )
                    submitted_ok[display_sym] = float(w_q + f_q)
                elif not self.last_coverage_lookup_failed:
                    self._pending_flatten_cids.pop(
                        (self.account_id, display_sym), None
                    )
        self.invalidate_cached_snapshots()
        return submitted_ok

    def submit_liquidation_batch(self, open_positions):
        submitted_ok = {}
        if not open_positions:
            return submitted_ok
        self.invalidate_cached_snapshots()
        use_market = is_market_hours()
        ext_quotes = {}
        if not use_market and self.data_client is not None:
            try:
                syms_to_quote = [
                    str(it[0]).strip()
                    for it in open_positions
                    if it and it[0]
                ]
                if (
                    syms_to_quote
                    and hasattr(self.data_client, "market_data")
                    and hasattr(self.data_client.market_data, "get_snapshot")
                ):
                    snap_res = self.data_client.market_data.get_snapshot(
                        syms_to_quote, "US_STOCK", extend_hour_required=True
                    )
                    if getattr(snap_res, "status_code", None) == 200:
                        snap_json = snap_res.json()
                        snap_list = (
                            snap_json
                            if isinstance(snap_json, list)
                            else snap_json.get("data", [])
                            if isinstance(snap_json, dict)
                            else []
                        )
                        if isinstance(snap_list, list):
                            for sq in snap_list:
                                if isinstance(sq, dict) and sq.get("symbol"):
                                    ext_quotes[str(sq["symbol"]).strip()] = sq
            except Exception as qe:
                log_event(
                    "WARN",
                    f"Webull DataClient snapshot fallback to position price: {qe}",
                )

        for item in open_positions:
            symbol = str(item[0]).strip()
            try:
                f_qty = float(item[1])
            except Exception:
                continue
            ref_lp = float(item[2]) if len(item) > 2 and item[2] else 0.0
            if abs(f_qty) <= 1e-9:
                continue
            if is_uncloseable_fractional_qty(self.account_id, symbol, f_qty):
                continue

            abs_total = abs(f_qty)
            whole_q = int(abs_total)
            is_pure_fractional = (whole_q == 0 and 0.0 < abs_total < 1.0)
            if is_pure_fractional and not use_market:
                mark_uncloseable_fractional_sym(
                    self.account_id, symbol, f_qty
                )
                continue

            order_qty = round(abs_total, 4) if is_pure_fractional else whole_q
            if order_qty <= 0:
                continue

            attempt_ts = time.time()
            pend = self._pending_flatten_cids.get((self.account_id, symbol))
            if pend and (attempt_ts - float(pend[1])) < 30.0:
                pend_sub_q = float(pend[2])
                pend_pos_q = float(pend[3]) if len(pend) > 3 else pend_sub_q
                pend_acc = bool(pend[4]) if len(pend) > 4 else False
                pend_use_mkt = bool(pend[5]) if len(pend) > 5 else use_market
                w_q, f_q = self.get_recent_exit_order_coverage(
                    symbol,
                    is_short=(f_qty < 0),
                    since_epoch=pend[1],
                    is_opt=False,
                )
                same_stale_pos = abs(abs(f_qty) - abs(pend_pos_q)) <= 1e-6 and (
                    (f_qty < 0) == (pend_pos_q < 0) if len(pend) > 3 else True
                )
                if w_q >= (order_qty - 1e-6) or (
                    same_stale_pos
                    and (
                        (w_q + f_q) >= (order_qty - 1e-6)
                        or (
                            (pend_acc or self.last_coverage_lookup_failed)
                            and pend_use_mkt == use_market
                            and not self._last_cov_saw_dead_pend
                        )
                    )
                ):
                    log_event(
                        "FLATTEN",
                        f"Skipping duplicate Webull exit order on {symbol} "
                        f"(already working={w_q:g}, filled={f_q:g}).",
                    )
                    submitted_ok[symbol] = float(max(w_q + f_q, pend_sub_q))
                    continue

            side = "SELL" if f_qty > 0 else "BUY"
            client_oid = uuid.uuid4().hex[:24]
            self._pending_flatten_cids[(self.account_id, symbol)] = (
                client_oid,
                attempt_ts,
                float(order_qty),
                float(f_qty),
                False,
                bool(use_market),
            )
            qty_str = format_order_qty_str(order_qty)

            if use_market:
                log_event(
                    "ORDER_OUT",
                    f"Submitting Webull RTH Market {side}: {qty_str} {symbol} ({_mask_last4(client_oid)})"
                )
                order_item = {
                    "client_order_id": client_oid,
                    "symbol": symbol,
                    "instrument_type": "EQUITY",
                    "market": "US",
                    "order_type": "MARKET",
                    "side": side,
                    "quantity": qty_str,
                    "time_in_force": "DAY",
                    "support_trading_session": "CORE",
                    "entrust_type": "QTY"
                }
            else:
                sq = ext_quotes.get(symbol, {})
                live_ref = 0.0
                for k_q in (
                    (
                        "extend_hour_bid_price",
                        "bid_price",
                        "bid",
                        "extend_hour_last_price",
                        "price",
                        "close",
                    )
                    if f_qty > 0
                    else (
                        "extend_hour_ask_price",
                        "ask_price",
                        "ask",
                        "extend_hour_last_price",
                        "price",
                        "close",
                    )
                ):
                    try:
                        v_q = float(sq.get(k_q) or 0.0)
                        if v_q > 0:
                            live_ref = v_q
                            break
                    except Exception:
                        pass
                eff_ref = live_ref if live_ref > 0 else ref_lp
                if eff_ref <= 0:
                    self._pending_flatten_cids.pop(
                        (self.account_id, symbol), None
                    )
                    log_event(
                        "ERROR",
                        f"No valid reference price found for {symbol} on Webull!"
                    )
                    continue
                lim_price = calc_ext_limit_price(
                    float(eff_ref), is_sell=(f_qty > 0)
                )
                lim_price_str = format_limit_price_str(lim_price)
                log_event(
                    "ORDER_OUT",
                    f"Submitting Webull EXT Limit {side}: {qty_str} {symbol} "
                    f"@ ${lim_price_str} (Ref: ${eff_ref}) ({_mask_last4(client_oid)})"
                )
                order_item = {
                    "client_order_id": client_oid,
                    "symbol": symbol,
                    "instrument_type": "EQUITY",
                    "market": "US",
                    "order_type": "LIMIT",
                    "limit_price": lim_price_str,
                    "side": side,
                    "quantity": qty_str,
                    "time_in_force": "DAY",
                    "support_trading_session": "ALL",
                    "extended_hours_trading": True,
                    "entrust_type": "QTY"
                }

            try:
                if hasattr(self.trade_client, "order_v3"):
                    r = self.trade_client.order_v3.place_order(
                        self.account_id, [order_item]
                    )
                else:
                    r = self.trade_client.place_order(
                        self.account_id, order_item
                    )
                code = c_resp_code(r)
                log_event(
                    "ORDER_RESP",
                    f"Webull {side} {symbol} ({_mask_last4(client_oid)}) -> HTTP {code}"
                )
                if code in (200, 201, 202, "OK"):
                    self._pending_flatten_cids[(self.account_id, symbol)] = (
                        client_oid,
                        attempt_ts,
                        float(order_qty),
                        float(f_qty),
                        True,
                        bool(use_market),
                    )
                    submitted_ok[symbol] = float(order_qty)
                else:
                    self._pending_flatten_cids.pop(
                        (self.account_id, symbol), None
                    )
                    if is_pure_fractional:
                        mark_uncloseable_fractional_sym(
                            self.account_id, symbol, f_qty
                        )
            except Exception as e:
                log_event("ERROR", f"Webull place_order exception: {e}")
                if is_pure_fractional:
                    self._pending_flatten_cids.pop(
                        (self.account_id, symbol), None
                    )
                    mark_uncloseable_fractional_sym(
                        self.account_id, symbol, f_qty
                    )
                    continue
                w_q, f_q = self.get_recent_exit_order_coverage(
                    symbol,
                    is_short=(f_qty < 0),
                    since_epoch=attempt_ts,
                    is_opt=False,
                )
                if (w_q + f_q) > 0:
                    log_event(
                        "FLATTEN",
                        f"Verified timed-out Webull exit order on {symbol} is live/filled "
                        f"(working={w_q:g}, filled={f_q:g}); suppressing duplicate.",
                    )
                    submitted_ok[symbol] = float(w_q + f_q)
                elif not self.last_coverage_lookup_failed:
                    self._pending_flatten_cids.pop(
                        (self.account_id, symbol), None
                    )
        self.invalidate_cached_snapshots()
        return submitted_ok

    @staticmethod
    def _extract_webull_equity_and_cash(b_data):
        """Extracts Total Account Value (Net Liquidation), Cash Balance, and
        Balance-Snapshot Market Value from Webull's balance payload without
        ever mistaking Market Value of positions for Total Account Value."""
        def to_f(val):
            try:
                return float(val) if val is not None and val != "" else None
            except Exception:
                return None

        top_mkt = to_f(
            b_data.get("total_market_value")
            or b_data.get("market_value")
        )

        # 1. Check direct top-level net liquidation fields
        for k in (
            "total_net_liquidation_value",
            "net_liquidation_value",
            "total_net_liquidation",
            "net_liquidation",
            "total_asset",
            "total_value",
            "account_value"
        ):
            v = to_f(b_data.get(k))
            if v is not None and v > 0:
                cash = to_f(
                    b_data.get("total_cash_balance")
                    or b_data.get("cash_balance")
                    or b_data.get("total_cash")
                )
                return v, cash, top_mkt

        # 2. Check inside account_currency_assets (USD)
        assets = b_data.get("account_currency_assets")
        if isinstance(assets, list) and assets:
            for item in assets:
                sub_mkt = to_f(
                    item.get("market_value")
                    or item.get("total_market_value")
                )
                for k in (
                    "net_liquidation_value",
                    "total_net_liquidation_value",
                    "net_liquidation",
                    "total_asset"
                ):
                    v = to_f(item.get(k))
                    if v is not None and v > 0:
                        cash = to_f(
                            item.get("cash_balance")
                            or item.get("total_cash_balance")
                            or item.get("total_cash")
                        )
                        return v, cash, (sub_mkt if sub_mkt is not None else top_mkt)

        # 3. Fallback: Sum Cash Balance + Market Value
        cash = to_f(
            b_data.get("total_cash_balance")
            or b_data.get("cash_balance")
            or b_data.get("total_cash")
        )
        mkt = top_mkt or 0.0
        if cash is not None:
            return cash + mkt, cash, top_mkt

        if isinstance(assets, list) and assets:
            for item in assets:
                c_sub = to_f(
                    item.get("cash_balance")
                    or item.get("total_cash_balance")
                    or item.get("settled_cash")
                )
                m_sub_raw = to_f(
                    item.get("market_value")
                    or item.get("total_market_value")
                )
                m_sub = m_sub_raw or 0.0
                if c_sub is not None:
                    return c_sub + m_sub, c_sub, m_sub_raw

        return 0.0, None, None

    def fetch_account_data(self):
        """Returns (adj_eq, is_flat, open_pnl, pos_details, has_options)
        for Webull accounts."""
        self.last_snapshot_was_cached = False
        snap_gen_at_start = self._snapshot_gen
        start_acct_id = self.account_id
        now_ts = time.time()
        if now_ts < self._rate_limit_until:
            with self._cache_lock:
                cached_snap = (
                    self._last_good_snapshot.get(start_acct_id)
                    if self._snapshot_gen == snap_gen_at_start
                    else None
                )
            if cached_snap and (now_ts - cached_snap[0]) <= 15.0:
                self.last_snapshot_was_cached = True
                return cached_snap[1]
            self.last_error = "HTTP 429"
            return None, True, 0.0, {}, False

        try:
            self._reserve_pos_slot(own_gap=2.10, owner="dl")
            p_res = self._call_get_positions(acct_id=start_acct_id)
            if self.account_id != start_acct_id or broker_reconfig_in_progress:
                return None, True, 0.0, {}, False
            if p_res.status_code == 429:
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
                if (time.time() - self._last_429_log_ts) >= 30.0:
                    self._last_429_log_ts = time.time()
                    log_event(
                        "WARN",
                        "Webull rate limit (HTTP 429) — backing off 2.5s and holding last snapshot."
                    )
                with self._cache_lock:
                    cached_snap = (
                        self._last_good_snapshot.get(start_acct_id)
                        if self._snapshot_gen == snap_gen_at_start
                        else None
                    )
                if cached_snap and (time.time() - cached_snap[0]) <= 15.0:
                    self.last_snapshot_was_cached = True
                    return cached_snap[1]
                self.last_error = "HTTP 429"
                return None, True, 0.0, {}, False
            if p_res.status_code != 200:
                self.last_positions_fetch_ok = False
                self.last_error = (
                    f"HTTP {p_res.status_code}: {getattr(p_res, 'text', '')[:80]}"
                )
                log_event(
                    "ERROR",
                    f"Webull get_account_position HTTP {p_res.status_code}"
                )
                return None, True, 0.0, {}, False

            p_json = p_res.json()
            pos_list = (
                p_json if isinstance(p_json, list)
                else p_json.get("data", p_json.get("positions", []))
            )

            b_res = self._call_get_balance(acct_id=start_acct_id)
            if self.account_id != start_acct_id or broker_reconfig_in_progress:
                return None, True, 0.0, {}, False
            if b_res.status_code == 429:
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
                if (time.time() - self._last_429_log_ts) >= 30.0:
                    self._last_429_log_ts = time.time()
                    log_event(
                        "WARN",
                        "Webull balance rate limit (HTTP 429) — backing off 2.5s and holding last snapshot."
                    )
                with self._cache_lock:
                    cached_snap = (
                        self._last_good_snapshot.get(start_acct_id)
                        if self._snapshot_gen == snap_gen_at_start
                        else None
                    )
                if cached_snap and (time.time() - cached_snap[0]) <= 15.0:
                    self.last_snapshot_was_cached = True
                    return cached_snap[1]
                self.last_error = "HTTP 429"
                return None, True, 0.0, {}, False
            if b_res.status_code != 200:
                self.last_error = (
                    f"HTTP {b_res.status_code}: {getattr(b_res, 'text', '')[:80]}"
                )
                log_event(
                    "ERROR",
                    f"Webull get_account_balance HTTP {b_res.status_code}"
                )
                return None, True, 0.0, {}, False

            b_json = b_res.json()
            b_data = (
                b_json.get("data", b_json)
                if isinstance(b_json, dict) else {}
            )

            raw_eq, cash_bal, bal_mkt_val = (
                self._extract_webull_equity_and_cash(b_data)
            )
            wb_pos_dep = 0.0
            for dep_k in (
                "pending_deposit",
                "incoming_funds",
                "unsettled_deposit",
                "cash_receipts",
            ):
                try:
                    dv = b_data.get(dep_k)
                    if dv is not None and dv != "":
                        fval = float(dv)
                        if fval > wb_pos_dep:
                            wb_pos_dep = fval
                except Exception:
                    pass
            wb_neg_cf = 0.0
            try:
                cr_raw = b_data.get("cash_receipts")
                if cr_raw is not None and cr_raw != "":
                    cr_val = float(cr_raw)
                    if cr_val < 0.0:
                        wb_neg_cf = cr_val
            except Exception:
                pass
            wb_dep = round(wb_pos_dep + wb_neg_cf, 2)
            self._last_intraday_cash_flow[start_acct_id] = wb_dep
            raw_eq_true = raw_eq
            raw_eq = (
                (raw_eq_true - get_unanchored_cash_flow(wb_dep))
                if raw_eq_true is not None
                else None
            )
            if start_acct_id not in self._logged_accounts:
                self._logged_accounts.add(start_acct_id)
                log_event(
                    "SESSION",
                    f"Webull Balance Parsed -> TotalAccountValue=${_round_cents(raw_eq or 0.0):,.2f} "
                    f"(Cash=${cash_bal if cash_bal is not None else 0.0:,.2f})"
                )

            total_open_pnl = 0.0
            total_pos_mkt_val = 0.0
            total_raw_pos_mkt_val = 0.0
            pos_details = {}
            open_eq_cache = []
            open_opt_cache = []
            has_options = False

            for p in pos_list:
                itype = str(
                    p.get("instrument_type")
                    or p.get("asset_type")
                    or "EQUITY"
                ).upper()
                is_opt = ("OPT" in itype) or bool(p.get("legs"))
                opt_meta = self._parse_option_contract_meta(p) if is_opt else None
                sym = (
                    opt_meta["display_sym"]
                    if opt_meta is not None
                    else (
                        p.get("symbol")
                        or p.get("ticker", {}).get("symbol")
                        or "UNKNOWN"
                    )
                )
                qty = (
                    opt_meta["qty"]
                    if opt_meta is not None
                    else self._normalize_webull_equity_qty(p, sym)
                )
                if qty == 0:
                    continue
                if not is_opt and is_uncloseable_fractional_qty(
                    start_acct_id, sym, qty
                ):
                    continue
                if is_opt:
                    has_options = True
                    open_opt_cache.append(
                        (opt_meta["display_sym"], qty, opt_meta)
                    )
                mult = 100.0 if is_opt else 1.0

                avg_price = float(
                    p.get("cost_price")
                    or p.get("avg_price")
                    or p.get("average_price")
                    or 0.0
                )
                raw_lp = float(
                    p.get("last_price")
                    or p.get("market_price")
                    or avg_price
                )
                raw_mkt_val = float(
                    p.get("market_value") or (qty * raw_lp * mult)
                )
                acct_lp = (
                    abs(raw_mkt_val / (qty * mult))
                    if qty != 0 else avg_price
                )
                if not is_opt:
                    san_lp = sanitize_equity_live_price(
                        raw_last=raw_lp,
                        bid=p.get("bid_price") or p.get("bid"),
                        ask=p.get("ask_price") or p.get("ask"),
                        mark=p.get("market_price"),
                        net_qty=qty
                    )
                    lp = float(san_lp) if san_lp is not None else raw_lp
                    conf_lp = compute_book_confirmed_price(
                        lp=lp,
                        bid=p.get("bid_price") or p.get("bid"),
                        ask=p.get("ask_price") or p.get("ask"),
                        mark=p.get("market_price"),
                        acct_lp=acct_lp,
                        net_qty=qty
                    )
                    if sym and sym != "UNKNOWN":
                        open_eq_cache.append((sym, qty, lp))
                else:
                    lp = raw_lp
                    conf_lp = lp

                qty_val = (
                    int(qty)
                    if float(qty).is_integer()
                    else round(float(qty), 6)
                )
                lp = round(float(lp), 4)
                conf_lp = round(float(conf_lp), 4)
                pos_mkt_val = qty_val * lp * mult
                if abs(lp - raw_lp) > 0.0001:
                    pos_open_pnl = (
                        (lp - avg_price) * qty_val * mult
                        if avg_price > 0 else 0.0
                    )
                else:
                    if "unrealized_profit_loss" in p and p.get(
                        "unrealized_profit_loss"
                    ) is not None:
                        pos_open_pnl = float(p["unrealized_profit_loss"])
                    else:
                        pos_open_pnl = (
                            (lp - avg_price) * qty_val * mult
                            if avg_price > 0 else 0.0
                        )
                conf_open_pnl = (
                    (conf_lp - avg_price) * qty_val * mult
                    if avg_price > 0 else pos_open_pnl
                )
                total_raw_pos_mkt_val += raw_mkt_val
                total_pos_mkt_val += pos_mkt_val

                total_open_pnl += pos_open_pnl
                tag = f"{sym} (OPT)" if is_opt else sym
                raw_sym_val = (
                    opt_meta.get("raw_symbol", sym)
                    if opt_meta is not None
                    else sym
                )
                wb_st = str(
                    p.get("status")
                    or p.get("trade_status")
                    or p.get("security_status")
                    or (p.get("ticker") or {}).get("status")
                    or ""
                ).strip().upper()
                is_sym_halted = wb_st in (
                    "HALTED",
                    "HALT",
                    "PAUSED",
                    "SUSPENDED",
                    "SUSPEND",
                )
                pos_details[tag] = {
                    "symbol": sym,
                    "raw_symbol": raw_sym_val,
                    "qty": qty_val,
                    "avg": round(avg_price, 4),
                    "last": lp,
                    "open_pnl": round(pos_open_pnl, 2),
                    "confirmed_open_pnl": round(conf_open_pnl, 2),
                    "asset_type": "OPTION" if is_opt else "EQUITY",
                    "halted": is_sym_halted,
                }

            open_opt_cache.sort(
                key=lambda item: (0 if item[1] < 0 else 1, str(item[0]))
            )
            if self.account_id != start_acct_id or broker_reconfig_in_progress:
                return None, True, 0.0, {}, False
            self._prune_pending_flatten_cids(
                start_acct_id,
                {
                    item[0]: item[1]
                    for item in (open_eq_cache + open_opt_cache)
                },
            )
            self.last_positions_fetch_ok = True
            now_snap_t = time.time()
            self._last_raw_pos_details[start_acct_id] = json.loads(
                json.dumps(pos_details)
            )
            if hasattr(self, "_last_snapshot_epoch") and isinstance(
                self._last_snapshot_epoch, dict
            ):
                self._last_snapshot_epoch[start_acct_id] = now_snap_t
            self._prev_pos_qty_map[start_acct_id] = {
                s_k.replace(" (OPT)", ""): d_v["qty"]
                for s_k, d_v in pos_details.items()
            }

            ref_bal_mkt_val = (
                bal_mkt_val
                if (bal_mkt_val is not None and len(pos_details) > 0)
                else total_raw_pos_mkt_val
            )
            unrounded_raw_adj_eq = (
                (raw_eq + (total_pos_mkt_val - ref_bal_mkt_val))
                if (raw_eq is not None and raw_eq > 0)
                else None
            )
            unrounded_true_raw_adj_eq = (
                (raw_eq_true + (total_pos_mkt_val - ref_bal_mkt_val))
                if (raw_eq_true is not None and raw_eq_true > 0)
                else None
            )
            used_webull_raw_adj = False
            if cash_bal is not None and cash_bal > 0:
                unrounded_cash_plus_pos = cash_bal + total_pos_mkt_val
                if (
                    unrounded_raw_adj_eq is not None
                    and abs(unrounded_cash_plus_pos - unrounded_raw_adj_eq) > 15.0
                ):
                    unrounded_adj_eq = unrounded_raw_adj_eq
                    used_webull_raw_adj = True
                else:
                    unrounded_adj_eq = unrounded_cash_plus_pos
                if (
                    unrounded_true_raw_adj_eq is not None
                    and abs(unrounded_cash_plus_pos - unrounded_true_raw_adj_eq)
                    > 15.0
                ):
                    true_live_eq = unrounded_true_raw_adj_eq
                else:
                    true_live_eq = unrounded_cash_plus_pos
            else:
                if unrounded_raw_adj_eq is not None:
                    unrounded_adj_eq = unrounded_raw_adj_eq
                    used_webull_raw_adj = True
                else:
                    unrounded_adj_eq = float(raw_eq or 0.0)
                if unrounded_true_raw_adj_eq is not None:
                    true_live_eq = unrounded_true_raw_adj_eq
                else:
                    true_live_eq = float(raw_eq_true or 0.0)

            flat_tol = (
                0.01 if (used_webull_raw_adj and len(pos_details) > 0) else 0.0
            )
            self._last_unrounded_true_live_eq[start_acct_id] = true_live_eq
            self._last_flat_rounding_tol[start_acct_id] = flat_tol
            self._last_raw_adj_eq[start_acct_id] = _round_cents(unrounded_adj_eq)
            (
                adj_eq,
                is_flat,
                tot_open_pnl,
                filt_pos,
                has_opt,
                filt_eq,
                filt_opt,
            ) = _apply_ignored_positions_to_snapshot(
                unrounded_adj_eq, pos_details, open_eq_cache, open_opt_cache
            )

            self.last_error = ""
            res_tuple = (
                adj_eq,
                is_flat,
                tot_open_pnl,
                filt_pos,
                has_opt
            )
            with self._cache_lock:
                if self._snapshot_gen == snap_gen_at_start:
                    self._last_open_eq[start_acct_id] = (now_snap_t, filt_eq)
                    self._last_open_opt[start_acct_id] = (now_snap_t, filt_opt)
                    self._last_good_snapshot[start_acct_id] = (
                        time.time(), res_tuple
                    )
            return res_tuple
        except Exception as e:
            err_s = str(e)
            if "429" in err_s or "too many requests" in err_s.lower():
                self._rate_limit_until = max(
                    self._rate_limit_until, time.time() + 2.5
                )
                if (time.time() - self._last_429_log_ts) >= 30.0:
                    self._last_429_log_ts = time.time()
                    log_event(
                        "WARN",
                        "Webull rate limit (HTTP 429) — backing off 2.5s and holding last snapshot."
                    )
                with self._cache_lock:
                    cached_snap = (
                        self._last_good_snapshot.get(start_acct_id)
                        if self._snapshot_gen == snap_gen_at_start
                        else None
                    )
                if cached_snap and (time.time() - cached_snap[0]) <= 15.0:
                    self.last_snapshot_was_cached = True
                    return cached_snap[1]
            self.last_error = err_s
            log_event("ERROR", f"Webull account fetch exception: {e}")
            return None, True, 0.0, {}, False


class DemoBrokerAdapter:
    """Interactive in-memory Paper/Simulator Broker Adapter ('DEMO').
    Allows new users without live API credentials (or existing traders rehearsing
    rulebooks) to test Open PnL Stops, Daily Stops, Profit Ratchets, Tilt Streaks,
    LULD Halt Watch, Emergency Flatten Now, and Done for Today without risking
    capital, modifying live session baselines, or locking their Windows PC."""

    name = "DEMO"
    DEMO_ACCOUNT_ID = "DEMO_SIM_01"

    def __init__(self, start_cash=25000.0):
        self.account_id = self.DEMO_ACCOUNT_ID
        self.accounts = [
            {"id": self.DEMO_ACCOUNT_ID, "label": "Demo Paper Account (...SIM1)"}
        ]
        self._start_cash = float(start_cash)
        self._cash_balance = float(start_cash)
        self._positions = {}
        self._working_orders = []
        self._filled_orders = []
        self._halt_until_ts = {}
        self._last_raw_pos_details = {}
        self._last_raw_adj_eq = {}
        self._last_intraday_cash_flow = {}
        self._last_snapshot_epoch = {}
        self.last_preserved_close_qty = {}
        self.last_cancel_failed_syms = set()
        self.last_coverage_lookup_failed = False
        self._last_cov_saw_dead_pend = False
        self.last_positions_fetch_ok = True
        self.last_snapshot_was_cached = False
        self._last_flatten_outcome = "FLAT"
        self._post_flatten_opt_verify = None
        self._fast_auth_deferred = False
        self.last_error = ""
        self._lock = threading.RLock()

    def invalidate_cached_snapshots(self):
        return None

    def authenticate(self, fast_cached_accounts=None, allow_interactive_oauth=True):
        self.last_positions_fetch_ok = True
        return True

    connect = authenticate

    def reconnect_session(self):
        return True

    def verify_accounts_live(self):
        return True

    def get_cached_trading_permission(self):
        return ("VERIFIED", "Demo Simulator order routing active.")

    def check_trading_permission_preview(self, force=False):
        return ("VERIFIED", "Demo Simulator order routing active.")

    def get_last_raw_pos_details(self):
        with self._lock:
            return json.loads(
                json.dumps(self._last_raw_pos_details.get(self.account_id, {}))
            )

    def get_last_raw_positions_snapshot(self):
        return self.get_last_raw_pos_details(), self.get_last_raw_adj_eq()

    def get_last_raw_adj_eq(self):
        with self._lock:
            val = self._last_raw_adj_eq.get(self.account_id)
            return float(val) if val is not None else self._cash_balance

    def get_last_true_live_eq(self):
        return self.get_last_raw_adj_eq()

    def get_flat_rounding_tolerance(self):
        return 0.0

    def get_last_intraday_cash_flow(self):
        return float(self._last_intraday_cash_flow.get(self.account_id, 0.0))

    def get_last_snapshot_epoch(self):
        snap_map = getattr(self, "_last_snapshot_epoch", None)
        if isinstance(snap_map, dict):
            return float(snap_map.get(self.account_id, 0.0) or 0.0)
        if isinstance(snap_map, (int, float)):
            return float(snap_map)
        return 0.0

    def _settle_expired_halts(self):
        now_t = time.time()
        expired = [
            s for s, exp_t in list(self._halt_until_ts.items()) if now_t >= exp_t
        ]
        for s in expired:
            self._halt_until_ts.pop(s, None)
            still_working = []
            for wo in self._working_orders:
                if wo.get("symbol") == s:
                    p = self._positions.pop(s, None) or self._positions.pop(
                        f"{s} (OPT)", None
                    )
                    if p is not None:
                        mult = 100.0 if p.get("asset_type") == "OPTION" else 1.0
                        pnl = (
                            (float(p["last"]) - float(p["avg"]))
                            * float(p["qty"])
                            * mult
                        )
                        self._cash_balance = round(self._cash_balance + pnl, 2)
                    wo["status"] = "FILLED"
                    wo["filled_qty"] = float(wo.get("qty", 0.0))
                    wo["filled_ts"] = now_t
                    self._filled_orders.append(wo)
                    log_event(
                        "FLATTEN",
                        f"[DEMO] LULD halt expired on {s} — queued exit order filled.",
                    )
                else:
                    still_working.append(wo)
            self._working_orders = still_working

    def sim_open_position(
        self, symbol="NVDA", qty=100, price=120.0, asset_type="EQUITY"
    ):
        with self._lock:
            sym = str(symbol).strip().upper()
            q = float(qty)
            px = round(max(0.05, float(price)), 4)
            is_opt = str(asset_type).upper() == "OPTION"
            key = f"{sym} (OPT)" if is_opt and not sym.endswith(" (OPT)") else sym
            raw_sym = sym[:-6].strip() if sym.endswith(" (OPT)") else sym
            mult = 100.0 if is_opt else 1.0
            fill_px = px
            if key in self._positions:
                cur = self._positions[key]
                old_q = float(cur["qty"])
                fill_px = round(max(0.05, float(cur["last"])), 4)
                new_q = old_q + q
                if abs(new_q) < 1e-6:
                    pnl = (fill_px - float(cur["avg"])) * old_q * mult
                    self._cash_balance = round(self._cash_balance + pnl, 2)
                    self._positions.pop(key, None)
                else:
                    if (old_q > 0 and q > 0) or (old_q < 0 and q < 0):
                        cur["avg"] = round(
                            (abs(old_q) * float(cur["avg"]) + abs(q) * fill_px)
                            / abs(new_q),
                            4,
                        )
                    elif old_q * new_q < 0:
                        pnl = (fill_px - float(cur["avg"])) * old_q * mult
                        self._cash_balance = round(self._cash_balance + pnl, 2)
                        cur["avg"] = fill_px
                    else:
                        closed_abs = min(abs(old_q), abs(q))
                        closed_signed = closed_abs if old_q > 0 else -closed_abs
                        pnl = (fill_px - float(cur["avg"])) * closed_signed * mult
                        self._cash_balance = round(self._cash_balance + pnl, 2)
                    cur["qty"] = int(round(new_q)) if new_q.is_integer() else new_q
                    cur["last"] = fill_px
            else:
                self._positions[key] = {
                    "symbol": raw_sym,
                    "raw_symbol": raw_sym,
                    "qty": int(round(q)) if q.is_integer() else q,
                    "avg": px,
                    "last": px,
                    "asset_type": "OPTION" if is_opt else "EQUITY",
                }
            log_event(
                "SESSION",
                f"[DEMO] Simulated position opened/updated: {q:+g} {raw_sym} @ ${fill_px:,.2f} ({'OPTION' if is_opt else 'EQUITY'}).",
            )

    def has_open_positions(self):
        with self._lock:
            self._settle_expired_halts()
            return bool(self._positions)

    def peek_demo_snapshot(self):
        """Pure read-only snapshot of simulated positions for UI chrome updates.
        Never mutates _positions, _working_orders, _cash_balance, or logs."""
        with self._lock:
            tot_open_pnl = 0.0
            pos_summary = []
            for _k, p in self._positions.items():
                sym = p["symbol"]
                qty = p["qty"]
                avg = float(p["avg"])
                lp = float(p["last"])
                is_opt = p.get("asset_type") == "OPTION"
                mult = 100.0 if is_opt else 1.0
                opnl = round((lp - avg) * float(qty) * mult, 2)
                tot_open_pnl += opnl
                pos_summary.append((sym, qty, is_opt, opnl))
            return (not bool(pos_summary)), round(tot_open_pnl, 2), pos_summary

    def sim_nudge_pnl(self, delta_dollars, log_nudge=False):
        with self._lock:
            if not self._positions:
                self.sim_open_position("NVDA", 100, 125.0, "EQUITY")
            chosen_p = None
            for _k, cand_p in self._positions.items():
                cq = float(cand_p["qty"])
                cmult = 100.0 if cand_p.get("asset_type") == "OPTION" else 1.0
                cdenom = cq * cmult
                if abs(cdenom) <= 1e-6:
                    continue
                cand_old = float(cand_p["last"])
                cand_new = max(
                    0.05, round(cand_old + (float(delta_dollars) / cdenom), 4)
                )
                if abs(cand_new - cand_old) > 1e-9:
                    chosen_p = cand_p
                    break
            if chosen_p is None:
                first_k = next(iter(self._positions.keys()))
                chosen_p = self._positions[first_k]
            p = chosen_p
            q = float(p["qty"])
            mult = 100.0 if p.get("asset_type") == "OPTION" else 1.0
            denom = q * mult
            applied_delta = 0.0
            pos_opnl = 0.0
            if abs(denom) > 1e-6:
                old_lp = float(p["last"])
                new_lp = max(0.05, round(old_lp + (float(delta_dollars) / denom), 4))
                p["last"] = new_lp
                applied_delta = round((new_lp - old_lp) * denom, 2)
                pos_opnl = round((new_lp - float(p["avg"])) * q * mult, 2)
                if log_nudge:
                    log_event(
                        "SESSION",
                        f"[DEMO] Nudged {p['symbol']} by {format_dollar(applied_delta)} (req {format_dollar(delta_dollars)}) -> Last: ${new_lp:,.2f}, Pos Open PnL: {format_dollar(pos_opnl)}.",
                    )
            return applied_delta, p["symbol"], pos_opnl

    def sim_close_all_manual(self):
        with self._lock:
            self._halt_until_ts.clear()
            self._working_orders.clear()
            for _k, p in list(self._positions.items()):
                mult = 100.0 if p.get("asset_type") == "OPTION" else 1.0
                pnl = (float(p["last"]) - float(p["avg"])) * float(p["qty"]) * mult
                self._cash_balance = round(self._cash_balance + pnl, 2)
            self._positions.clear()
            self._last_raw_pos_details[self.account_id] = {}
            log_event(
                "SESSION",
                f"[DEMO] Manually closed all simulated positions flat (Cash=${self._cash_balance:,.2f}).",
            )

    def sim_set_halt(self, symbol, halt_seconds=18.0, duration_sec=None):
        with self._lock:
            sym = str(symbol).strip().upper()
            dur = float(duration_sec) if duration_sec is not None else float(halt_seconds)
            self._halt_until_ts[sym] = time.time() + max(1.0, dur)
            log_event(
                "SESSION",
                f"[DEMO] Simulated LULD trading halt engaged on {sym} for {dur:.0f}s.",
            )

    def is_halted(self, symbol=None):
        with self._lock:
            self._settle_expired_halts()
            if symbol is not None:
                return str(symbol).strip().upper() in self._halt_until_ts
            return bool(self._halt_until_ts)

    def get_halt_remaining_seconds(self, symbol=None):
        with self._lock:
            self._settle_expired_halts()
            now_t = time.time()
            if symbol is not None:
                exp = self._halt_until_ts.get(str(symbol).strip().upper())
                return max(0.0, float(exp - now_t)) if exp is not None else 0.0
            if not self._halt_until_ts:
                return 0.0
            return max(0.0, max(float(v - now_t) for v in self._halt_until_ts.values()))

    def has_any_filled_orders_today(self):
        with self._lock:
            return len(self._filled_orders) > 0

    def has_non_ignored_closing_fills_since(
        self, since_epoch, was_flat_at_save=True
    ):
        return False

    def fetch_filled_orders_since(self, since_epoch, fast_recent_only=False):
        return []

    def sim_reset_account(self, start_cash=25000.0):
        with self._lock:
            self._start_cash = float(start_cash)
            self._cash_balance = float(start_cash)
            self._positions.clear()
            self._working_orders.clear()
            self._filled_orders.clear()
            self._halt_until_ts.clear()
            self._last_raw_pos_details.clear()
            self._last_raw_adj_eq[self.account_id] = float(start_cash)

    def get_open_equity_positions(
        self,
        allow_stale_cache=True,
        pace_for_verify=False,
        cache_empty_ok=False,
    ):
        with self._lock:
            self._settle_expired_halts()
            res = []
            for k, p in self._positions.items():
                if p.get("asset_type") != "OPTION":
                    sym = p["symbol"]
                    if not is_position_ignored(sym, is_opt=False):
                        res.append((sym, p["qty"], p["last"]))
            return res

    def get_open_option_positions(
        self,
        allow_stale_cache=True,
        pace_for_verify=False,
        reuse_paired_eq_read=False,
    ):
        with self._lock:
            self._settle_expired_halts()
            res = []
            for k, p in self._positions.items():
                if p.get("asset_type") == "OPTION":
                    sym = p["symbol"]
                    if not is_position_ignored(k, is_opt=True):
                        res.append((sym, p["qty"], p["last"], p.get("raw_symbol", sym)))
            res.sort(key=lambda item: (0 if item[1] < 0 else 1, str(item[0])))
            return res

    def cancel_all_working_orders(
        self, preserve_market_close_map=None, cancel_options=False
    ):
        with self._lock:
            self._settle_expired_halts()
            self.last_preserved_close_qty = {}
            self.last_cancel_failed_syms = set()
            preserve_map = preserve_market_close_map or {}
            kept = []
            for wo in self._working_orders:
                sym = wo.get("symbol")
                if sym in preserve_map:
                    self.last_preserved_close_qty[sym] = abs(float(wo.get("qty", 0.0)))
                    kept.append(wo)
            self._working_orders = kept

    def get_recent_exit_order_coverage(
        self, symbol, is_short=False, since_epoch=0.0, is_opt=False
    ):
        with self._lock:
            self._settle_expired_halts()
            self.last_coverage_lookup_failed = False
            self._last_cov_saw_dead_pend = False
            sym = str(symbol).strip().upper()
            w_q = sum(
                abs(float(wo.get("qty", 0.0)))
                for wo in self._working_orders
                if wo.get("symbol") == sym
            )
            f_q = sum(
                abs(float(fo.get("filled_qty", 0.0)))
                for fo in self._filled_orders
                if fo.get("symbol") == sym and float(fo.get("filled_ts", 0.0)) >= (since_epoch - 2.0)
            )
            return float(w_q), float(f_q)

    def submit_liquidation_batch(self, open_positions):
        with self._lock:
            self._settle_expired_halts()
            submitted = {}
            now_t = time.time()
            for item in (open_positions or []):
                sym = str(item[0]).strip().upper()
                qty = float(item[1])
                abs_q = abs(qty)
                if abs_q <= 1e-6:
                    continue
                if sym in self._halt_until_ts and now_t < self._halt_until_ts[sym]:
                    if not any(wo.get("symbol") == sym for wo in self._working_orders):
                        self._working_orders.append(
                            {
                                "symbol": sym,
                                "qty": abs_q,
                                "is_short": qty < 0,
                                "status": "WORKING",
                                "created_ts": now_t,
                            }
                        )
                    log_event(
                        "ORDER_OUT",
                        f"[DEMO] Queued Market Close on halted {sym} ({qty:+g} sh) — waiting for LULD resume...",
                    )
                    submitted[sym] = abs_q
                    continue
                p = self._positions.pop(sym, None)
                if p is not None:
                    pnl = (float(p["last"]) - float(p["avg"])) * float(p["qty"])
                    self._cash_balance = round(self._cash_balance + pnl, 2)
                self._filled_orders.append(
                    {
                        "symbol": sym,
                        "filled_qty": abs_q,
                        "filled_ts": now_t,
                    }
                )
                log_event(
                    "ORDER_RESP",
                    f"[DEMO] Filled simulated equity exit for {sym} ({qty:+g} sh) -> HTTP 200",
                )
                submitted[sym] = abs_q
            return submitted

    def submit_option_liquidation_batch(self, open_options):
        with self._lock:
            submitted = {}
            now_t = time.time()
            ordered = sorted(
                list(open_options or []),
                key=lambda item: (0 if float(item[1]) < 0 else 1, str(item[0])),
            )
            for item in ordered:
                sym = str(item[0]).strip().upper()
                qty = float(item[1])
                abs_q = abs(qty)
                if abs_q <= 1e-6:
                    continue
                key = f"{sym} (OPT)" if not sym.endswith(" (OPT)") else sym
                p = self._positions.pop(key, None) or self._positions.pop(sym, None)
                if p is not None:
                    pnl = (
                        (float(p["last"]) - float(p["avg"]))
                        * float(p["qty"])
                        * 100.0
                    )
                    self._cash_balance = round(self._cash_balance + pnl, 2)
                instr = "BUY_TO_CLOSE" if qty < 0 else "SELL_TO_CLOSE"
                self._filled_orders.append(
                    {
                        "symbol": sym,
                        "filled_qty": abs_q,
                        "filled_ts": now_t,
                    }
                )
                log_event(
                    "ORDER_RESP",
                    f"[DEMO] Filled simulated option {instr} for {sym} ({qty:+g} contracts) -> HTTP 200",
                )
                submitted[sym] = abs_q
            return submitted

    def fetch_account_data(self):
        with self._lock:
            self._settle_expired_halts()
            pos_details = {}
            open_eq_cache = []
            open_opt_cache = []
            tot_open_pnl = 0.0
            for k, p in self._positions.items():
                sym = p["symbol"]
                qty = p["qty"]
                avg = float(p["avg"])
                lp = float(p["last"])
                is_opt = p.get("asset_type") == "OPTION"
                mult = 100.0 if is_opt else 1.0
                opnl = round((lp - avg) * float(qty) * mult, 2)
                tot_open_pnl += opnl
                tag = f"{sym} (OPT)" if is_opt and not sym.endswith(" (OPT)") else sym
                pos_details[tag] = {
                    "symbol": sym,
                    "raw_symbol": p.get("raw_symbol", sym),
                    "qty": qty,
                    "avg": avg,
                    "last": lp,
                    "open_pnl": opnl,
                    "confirmed_open_pnl": opnl,
                    "asset_type": "OPTION" if is_opt else "EQUITY",
                    "halted": bool(sym in self._halt_until_ts),
                }
                if is_opt:
                    open_opt_cache.append((sym, qty, lp, p.get("raw_symbol", sym)))
                else:
                    open_eq_cache.append((sym, qty, lp))
            open_opt_cache.sort(
                key=lambda item: (0 if item[1] < 0 else 1, str(item[0]))
            )
            raw_eq = round(self._cash_balance + tot_open_pnl, 2)
            self._last_raw_pos_details[self.account_id] = json.loads(
                json.dumps(pos_details)
            )
            self._last_raw_adj_eq[self.account_id] = raw_eq
            if hasattr(self, "_last_snapshot_epoch") and isinstance(
                self._last_snapshot_epoch, dict
            ):
                self._last_snapshot_epoch[self.account_id] = time.time()
            (
                adj_eq,
                is_flat,
                filt_open_pnl,
                filt_pos,
                has_opt,
                _filt_eq,
                _filt_opt,
            ) = _apply_ignored_positions_to_snapshot(
                raw_eq, pos_details, open_eq_cache, open_opt_cache
            )
            self.last_positions_fetch_ok = True
            self.last_error = ""
            return adj_eq, is_flat, filt_open_pnl, filt_pos, has_opt


def c_resp_code(res):
    if res is None:
        return "ERR"
    code = getattr(res, "status_code", None)
    if code is not None:
        return code
    if isinstance(res, dict):
        if (
            res.get("success") is True
            or res.get("order_id")
            or res.get("client_order_id")
            or ("data" in res and res.get("data") is not None)
        ):
            return "OK"
        return res.get("code") or res.get("status_code") or res.get("msg") or "ERR"
    return "ERR"


