    def _norm_pf_num(raw_s, signed=False, is_int=False):
        s = str(raw_s).strip()
        if not s:
            return ("RAW", "")
        try:
            v = float(s)
            if not math.isfinite(v):
                return ("RAW", s)
        except Exception:
            return ("RAW", s)
        if v == 0.0:
            v = 0.0
        if is_int:
            return ("INT", int(round(abs(v))))
        return ("FLT", round(v if signed else abs(v), 4))

