    def play_selected_test_audio():
        choice = var_audio_test.get()
        sel_voice_id = TTS_LABEL_TO_ID.get(var_tts_voice.get(), "Zira")
        active_parent = _prefs_modal_refs.get("dlg")
        try:
            if active_parent is None or not active_parent.winfo_exists():
                active_parent = pf
        except Exception:
            active_parent = pf
        if choice == "Warning Siren (Short Preview)":
            def _siren_sample():
                try:
                    for _ in range(4):
                        winsound.Beep(2600, 180)
                        time.sleep(0.04)
                except Exception:
                    pass
            threading.Thread(target=_siren_sample, daemon=True).start()
        elif choice == "Connection Lost Tone (2-Tone)":
            threading.Thread(
                target=lambda: play_disconnect_tone_once(force=True),
                daemon=True,
            ).start()
        elif choice == "Upside Tier Chime":
            play_upside_tier_chime(force=True)
        elif choice == "Voice: Lockout Alert":
            speak_async(
                "Open P and L stop triggered. Locked out for 2 minutes. Initial flat check passed.",
                force=True,
                voice_override=sel_voice_id,
                interrupt=True,
            )
        elif choice == "Voice: 15s Sweep Clear":
            speak_async(
                "15 second sweep clear, account confirmed flat.",
                force=True,
                voice_override=sel_voice_id,
                interrupt=True,
            )
        elif choice == "Voice: 1m Warning":
            speak_async(
                "1 minute remaining until unlock.",
                force=True,
                voice_override=sel_voice_id,
                interrupt=True,
            )
        elif choice == "Voice: 30s Warning":
            speak_async(
                "30 seconds remaining until unlock.",
                force=True,
                voice_override=sel_voice_id,
                interrupt=True,
            )
        elif choice == "Unlock Chime (3-Tone)":
            threading.Thread(
                target=lambda: play_unlock_chimes(force=True), daemon=True
            ).start()
        elif choice == "Full 10s Dry-Run Lockout":
            if dry_run_lock_active or cooldown_active:
                return
            if is_in_trade_tamper_locked():
                messagebox.showwarning(
                    "In Trade — Dry-Run Disabled",
                    "Dry-Run OS Lockout is disabled while an active daytrade is open.\n\n"
                    "Close your trade first so you are 100% flat before testing an OS lockout.",
                    parent=active_parent,
                )
                return
            if not _confirm_dry_run_lockout():
                return
            log_event(
                "SESSION",
                "User triggered 10-second Dry-Run OS Lockout test from Pre-Flight.",
            )

            def _dry_run_seq():
                global dry_run_lock_active
                dry_run_lock_active = True
                overlay = None
                try:
                    pf.after(
                        0,
                        lambda: (
                            _sync_prefs_modal_state(),
                            refresh_smart_dimming(),
                        ),
                    )
                except Exception:
                    pass
                try:
                    sim_broker = str(var_broker.get() or "SCHWAB").upper()
                    overlay = PenaltyBoxBriefingOverlay(
                        mode="DRY_RUN",
                        title="PENALTY BOX LOCKOUT PREVIEW — 10s DRY-RUN TEST",
                        reason="Simulated Guardrail Breach (10-Second Dry-Run Test)",
                        context_str=(
                            "Safe Simulation Mode — Zero broker orders sent or canceled "
                            "(Baseline & W/L stats untouched)"
                        ),
                        lock_mins=10.0 / 60.0,
                        ui_anchor=pf,
                        flat_enabled=True,
                        is_dry_run=True,
                        briefing_sec=10.0,
                    )
                    overlay.open()
                    for _ in range(4):
                        winsound.Beep(2600, 180)
                        time.sleep(0.04)
                    overlay.mark_flat_confirmed(broker_name=sim_broker)
                    speak_async(
                        "Dry run lockout test started. Penalty box briefing active. "
                        "Windows will lock in 10 seconds.",
                        force=True,
                        voice_override=sel_voice_id,
                        interrupt=True,
                    )
                    was_bypassed = overlay.wait_out_briefing_or_bypass(
                        briefing_sec=10.0
                    )
                    try:
                        ctypes.windll.user32.LockWorkStation()
                    except Exception:
                        pass
                    time.sleep(0.35)
                    speak_async(
                        (
                            "Bypass detected. Windows screen locked for 10 seconds."
                            if was_bypassed
                            else "Windows screen locked for 10 seconds."
                        ),
                        force=True,
                        voice_override=sel_voice_id,
                        interrupt=True,
                    )
                    lock_started_ts = time.time()
                    end_t = lock_started_ts + 10.0
                    confirmed_locked = is_workstation_locked()
                    last_early_unlock_ts = 0.0
                    while time.time() < end_t:
                        now_ts = time.time()
                        rem = max(0, int(round(end_t - now_ts)))
                        currently_locked = is_workstation_locked()
                        if currently_locked:
                            confirmed_locked = True
                        else:
                            try:
                                ctypes.windll.user32.LockWorkStation()
                            except Exception:
                                pass
                            if (
                                confirmed_locked
                                and (now_ts - lock_started_ts) >= 1.5
                                and rem >= 1
                                and (now_ts - last_early_unlock_ts) >= 2.0
                            ):
                                confirmed_locked = False
                                last_early_unlock_ts = now_ts
                                log_event(
                                    "SESSION",
                                    f"Early unlock attempt detected during 10s Dry-Run Lockout "
                                    f"({rem}s remaining) — workstation immediately re-locked.",
                                )
                                time.sleep(0.30)
                                rem_voice = max(1, int(round(end_t - time.time())))
                                speak_async(
                                    _format_exact_remaining_voice_msg(rem_voice),
                                    force=True,
                                    voice_override=sel_voice_id,
                                    interrupt=True,
                                )
                        time.sleep(0.20)
                    stop_active_tts()
                    play_unlock_chimes(force=True)
                    speak_async(
                        "Dry run lockout complete. You may unlock your screen.",
                        force=True,
                        voice_override=sel_voice_id,
                        interrupt=True,
                    )
                    log_event(
                        "SESSION",
                        "10-second Dry-Run OS Lockout test completed cleanly.",
                    )
                except Exception:
                    pass
                finally:
                    if overlay is not None:
                        try:
                            overlay.close()
                        except Exception:
                            pass
                    dry_run_lock_active = False
                    try:
                        pf.after(
                            0,
                            lambda: (
                                _sync_prefs_modal_state(),
                                refresh_smart_dimming(),
                            ),
                        )
                    except Exception:
                        pass

            threading.Thread(target=_dry_run_seq, daemon=True).start()

    def _toggle_hud_breach_visual_sim(refresh_btn_fn=None):
        global breach_visual_sim_active
        breach_visual_sim_active = not bool(breach_visual_sim_active)
        sim_on = bool(breach_visual_sim_active)
        log_event(
            "SESSION",
            f"User toggled HUD Breach Mode visual simulation {'ON' if sim_on else 'OFF'} "
            f"(safe visual preview — 0 orders).",
        )
        _sync_hud_breach_banner(current_is_flat)
        if mute_btn is not None and not alarm_active and not cooldown_active:
            apply_idle_button_config(mute_btn)
        if callable(refresh_btn_fn):
            try:
                refresh_btn_fn()
            except Exception:
                pass
        try:
            _refresh_card3_prefs_summary()
        except Exception:
            pass
        if default_status_lbl is not None and default_status_lbl.winfo_exists():
            if sim_on:
                default_status_lbl.config(
                    text="🚨 HUD Breach Mode Preview is ACTIVE (0 orders) — toggle OFF anytime in Preferences & Audio.",
                    fg="#f87171",
                )
            else:
                default_status_lbl.config(
                    text="✓ HUD Breach Mode visual simulation turned OFF.",
                    fg="#58d68d",
                )

