    try:
        pf.update_idletasks()
        pf_w = int(pf.winfo_reqwidth())
        pf_h = int(pf.winfo_reqheight())
        px, py = get_saved_preflight_position(
            pf_w, pf_h, fallback_widget=pf
        )
        if px is not None and py is not None:
            pf.geometry(f"{pf_w}x{pf_h}+{int(px)}+{int(py)}")
            apply_dark_title_bar(pf)
            pf.deiconify()
            pf.lift()
        else:
            center_dialog_over_parent(
                pf, parent=parent, width=pf_w, height=pf_h, grab=False
            )
    except Exception:
        try:
            pf.deiconify()
        except Exception:
            pass

    _pf_initial_shown["done"] = True

    if eff_startup_boot:
        def _boot_lift_pf():
            try:
                if (
                    not pf_timer_state.get("closing")
                    and pf.winfo_exists()
                    and pf.grab_current() is None
                ):
                    pf.attributes("-topmost", False)
                    pf.attributes("-topmost", True)
                    pf.lift()
            except Exception:
                pass

        try:
            pf.after(600, _boot_lift_pf)
        except Exception:
            pass

    if parent is None:
        _clear_boot_pending_marker()
        if _IS_MAIN_PROCESS:
            start_background_update_check(pf, cancel_pf_fn=_cancel_pf_timers)

        if _pf_initial_shown.get("needs_bg_sync") or getattr(
            active_adapter, "_fast_auth_deferred", False
        ):
            _bg_sync_epoch = get_adapter_epoch()
            _bg_init_acct_id = str(getattr(active_adapter, "account_id", "") or "")

            def _bg_sync_abort():
                return should_abort_startup_retry(
                    pf_timer_state.get("closing"),
                    launched["status"],
                    get_adapter_epoch(),
                    _bg_sync_epoch,
                )

            def _bg_preflight_broker_sync():
                ad = active_adapter
                if ad is None or _bg_sync_abort():
                    return
                verified_accts = False
                resolved_acct_id = str(getattr(ad, "account_id", "") or "")
                boot_retried_net = False
                if getattr(ad, "_fast_auth_deferred", False) and hasattr(
                    ad, "verify_accounts_live"
                ):
                    _max_v_tries = 6 if eff_startup_boot else 1
                    for _v_try in range(_max_v_tries):
                        if _bg_sync_abort():
                            return
                        verified_accts = bool(ad.verify_accounts_live())
                        if _bg_sync_abort():
                            return
                        if verified_accts:
                            break
                        if _v_try + 1 < _max_v_tries:
                            boot_retried_net = True
                            if sleep_with_startup_abort(3.0, _bg_sync_abort):
                                return
                    if verified_accts and ad.accounts:
                        saved_id = (
                            config.get("brokers", {})
                            .get(ad.name, {})
                            .get("selected_account_id", "")
                        )
                        valid_ids = [a["id"] for a in ad.accounts]
                        if saved_id in valid_ids:
                            resolved_acct_id = saved_id
                        elif valid_ids:
                            resolved_acct_id = valid_ids[0]
                    if verified_accts:
                        pf_timer_state["bg_auth_pending"] = (
                            ad,
                            _bg_sync_epoch,
                            verified_accts,
                            resolved_acct_id,
                        )
                snap = None
                bg_prefetched_fills = None
                bg_prefetched_closing = None
                bg_prefetched_win = None
                acct_changed_from_init = bool(
                    _bg_init_acct_id and resolved_acct_id and resolved_acct_id != _bg_init_acct_id
                )
                if pf_timer_state.get("closing") or launched["status"]:
                    if launched["status"] and verified_accts:
                        pf_timer_state.pop("bg_auth_pending", None)
                        _enqueue_postlaunch_preflight_auth(
                            ad, _bg_sync_epoch, verified_accts, resolved_acct_id
                        )
                    return
                if (
                    _pf_initial_shown.get("needs_bg_sync")
                    and resolved_acct_id
                    and not acct_changed_from_init
                    and get_adapter_epoch() == _bg_sync_epoch
                ):
                    _max_s_tries = 6 if eff_startup_boot else 1
                    for _s_try in range(_max_s_tries):
                        if _bg_sync_abort():
                            return
                        try:
                            snap = ad.fetch_account_data()
                            if pf_timer_state.get("closing") or launched["status"]:
                                if launched["status"] and verified_accts:
                                    pf_timer_state.pop("bg_auth_pending", None)
                                    _enqueue_postlaunch_preflight_auth(
                                        ad, _bg_sync_epoch, verified_accts, resolved_acct_id
                                    )
                                return
                            if (
                                snap
                                and snap[0] is not None
                                and snap[0] > 0
                                and get_adapter_epoch() == _bg_sync_epoch
                            ):
                                if _is_untouched_fee_drift_candidate(
                                    snap[0], snap[1], adapter_override=ad
                                ) and hasattr(ad, "has_any_filled_orders_today"):
                                    ad.has_any_filled_orders_today()
                                eff_bg_since = (
                                    float(_reconciled_through_epoch)
                                    if float(_reconciled_through_epoch or 0.0) > 0.0
                                    else float(_restored_session_saved_epoch or 0.0)
                                )
                                if eff_bg_since > 0.0 and hasattr(
                                    ad, "fetch_filled_orders_since"
                                ):
                                    bg_ref_flat = (
                                        last_flat_equity
                                        if last_flat_equity is not None and float(last_flat_equity) > 0.0
                                        else start_equity
                                    )
                                    bg_use_fast = bool(
                                        snap[1]
                                        and _restored_session_was_flat
                                        and bg_ref_flat is not None
                                        and float(bg_ref_flat) > 0.0
                                        and abs(round(float(snap[0]) - float(bg_ref_flat), 2)) < 0.01
                                        and (time.time() - eff_bg_since) < (30.0 * 3600.0)
                                    )
                                    bg_prefetched_win = "36h" if bg_use_fast else "58d"
                                    bg_prefetched_fills = _call_fetch_filled_orders_since(
                                        ad, eff_bg_since, fast_recent_only=bg_use_fast
                                    )
                                    if bg_use_fast and (
                                        bg_prefetched_fills is None
                                        or len(bg_prefetched_fills) > 0
                                    ):
                                        bg_prefetched_win = "58d"
                                        bg_prefetched_fills = _call_fetch_filled_orders_since(
                                            ad, eff_bg_since, fast_recent_only=False
                                        )
                                    if (
                                        bg_prefetched_fills is None
                                        and snap[1]
                                        and hasattr(
                                            ad,
                                            "has_non_ignored_closing_fills_since",
                                        )
                                    ):
                                        bg_prefetched_closing = bool(
                                            ad.has_non_ignored_closing_fills_since(
                                                eff_bg_since,
                                                was_flat_at_save=_restored_session_was_flat,
                                            )
                                        )
                                break
                        except Exception:
                            snap = None
                            bg_prefetched_fills = None
                            bg_prefetched_closing = None
                            bg_prefetched_win = None
                        if _s_try + 1 < _max_s_tries:
                            boot_retried_net = True
                            if sleep_with_startup_abort(3.0, _bg_sync_abort):
                                return

                if launched["status"] and verified_accts:
                    pf_timer_state.pop("bg_auth_pending", None)
                    _enqueue_postlaunch_preflight_auth(
                        ad, _bg_sync_epoch, verified_accts, resolved_acct_id
                    )
                    return

                def _finish_bg_sync_on_ui():
                    global start_equity, last_flat_equity, prev_flat_realized_pnl
                    global settled_realized_pnl, anchor_cash_flow, force_reanchor
                    global _initial_positions_verified, current_is_flat
                    if pf_timer_state.get("closing") or launched["status"]:
                        if launched["status"] and verified_accts:
                            pf_timer_state.pop("bg_auth_pending", None)
                            _enqueue_postlaunch_preflight_auth(
                                ad, _bg_sync_epoch, verified_accts, resolved_acct_id
                            )
                        return
                    try:
                        if not pf.winfo_exists():
                            return
                    except Exception:
                        return
                    if active_adapter is not ad or get_adapter_epoch() != _bg_sync_epoch:
                        return
                    if resolved_acct_id:
                        ad.account_id = resolved_acct_id
                    if verified_accts and ad.accounts:
                        pf_timer_state.pop("bg_auth_pending", None)
                        b_n = ad.name
                        if (
                            config.get("brokers", {})
                            .get(b_n, {})
                            .get("cached_accounts")
                            != ad.accounts
                        ):
                            config["brokers"][b_n]["cached_accounts"] = [
                                dict(a) for a in ad.accounts
                            ]
                            save_config(config)
                        log_event(
                            "SESSION",
                            f"{b_n} API authenticated ({len(ad.accounts)} account(s) found).",
                        )
                        populate_account_dropdown()
                        if boot_retried_net and _IS_MAIN_PROCESS:
                            start_background_update_check(
                                pf, cancel_pf_fn=_cancel_pf_timers
                            )
                    if acct_changed_from_init:
                        _pf_initial_shown["needs_bg_sync"] = False
                        refresh_baseline_preview(force_restore=True)
                        return
                    if not _pf_initial_shown.get("needs_bg_sync"):
                        return
                    _pf_initial_shown["needs_bg_sync"] = False
                    if snap is None:
                        return
                    eq_now, is_fl_now, live_opnl, live_pos_now, _ = snap
                    if eq_now is not None and eq_now > 0:
                        if getattr(active_adapter, "last_positions_fetch_ok", True):
                            _initial_positions_verified = True
                        current_is_flat = bool(is_fl_now)
                    had_svd = bool(_preexisting_state.get("had_saved", False))
                    if (
                        had_svd
                        and start_equity is not None
                        and start_equity > 0
                    ):
                        _preexisting_state["raw_eq"] = (
                            ad.get_last_raw_adj_eq()
                            if hasattr(ad, "get_last_raw_adj_eq")
                            else eq_now
                        )
                        if eq_now is not None and eq_now > 0:
                            if is_fl_now:
                                if not _maybe_absorb_untouched_flat_fee_drift(
                                    eq_now, is_fl_now
                                ):
                                    _reconcile_off_session_activity(
                                        eq_now,
                                        True,
                                        0.0,
                                        {},
                                        prefetched_fills=bg_prefetched_fills,
                                        prefetched_closing_confirmed=bg_prefetched_closing,
                                        allow_network=False,
                                        prefetched_window=bg_prefetched_win,
                                    )
                            else:
                                _reconcile_off_session_activity(
                                    eq_now,
                                    False,
                                    live_open_pnl=live_opnl,
                                    pos_details=live_pos_now,
                                    prefetched_fills=bg_prefetched_fills,
                                    prefetched_closing_confirmed=bg_prefetched_closing,
                                    allow_network=False,
                                    prefetched_window=bg_prefetched_win,
                                )
                        _card3_base_cache["eq_str"] = (
                            f"${start_equity:,.2f} (Saved)"
                        )
                    else:
                        _preexisting_state["raw_eq"] = eq_now
                        raw_pos = ad.get_last_raw_pos_details()
                        if (
                            var_ignore_preexisting.get()
                            and raw_pos
                            and not is_demo_mode_active(ad)
                        ):
                            ignored_positions.clear()
                            for tag, d in raw_pos.items():
                                ignored_positions[tag] = (
                                    build_ignored_position_entry(
                                        tag, d, lock_existing_open_pnl=False
                                    )
                                )
                            live_opnl = 0.0
                            current_is_flat = True
                        if eq_now is not None and eq_now > 0:
                            start_equity = round(eq_now - live_opnl, 2)
                            anchor_cash_flow = ad.get_last_intraday_cash_flow()
                            force_reanchor = True
                            _card3_base_cache["eq_str"] = (
                                f"${start_equity:,.2f} (Live)"
                            )
                        else:
                            _card3_base_cache["eq_str"] = (
                                "Will anchor on first API poll"
                            )
                    _refresh_ignored_positions_pill()
                    _render_card3_telemetry_live(force=True)
                    _trigger_trade_perm_probe(force_recheck=False)

                try:
                    pf.after(0, _finish_bg_sync_on_ui)
                except Exception:
                    if launched["status"] and verified_accts:
                        bg_p_fb = pf_timer_state.pop("bg_auth_pending", None)
                        if isinstance(bg_p_fb, tuple):
                            _enqueue_postlaunch_preflight_auth(*bg_p_fb)

            threading.Thread(
                target=_bg_preflight_broker_sync, daemon=True
            ).start()
        elif eff_startup_boot and active_adapter is None:
            def_auth_boot_msg = str(_last_boot_deferred_auth_msg or "").strip()
            if def_auth_boot_msg:
                if default_status_lbl is not None:
                    try:
                        default_status_lbl.config(
                            text=f"🔑 {def_auth_boot_msg}", fg="#fbbf24"
                        )
                    except Exception:
                        pass
            else:
                boot_rc_b = str(
                    var_broker.get() or config.get("active_broker", "SCHWAB")
                ).upper()
                boot_rc_cfg = config.get("brokers", {}).get(boot_rc_b, {})
                if (
                    boot_rc_b in ("SCHWAB", "WEBULL")
                    and boot_rc_cfg.get("app_key")
                    and boot_rc_cfg.get("app_secret")
                ):
                    if default_status_lbl is not None:
                        try:
                            default_status_lbl.config(
                                text=f"⏳ Waiting for network to connect {boot_rc_b}...",
                                fg="#7dd3fc",
                            )
                        except Exception:
                            pass
                    _boot_rc_ep = get_adapter_epoch()
                    _boot_rc_watch = {"broker": boot_rc_b}

                    def _on_boot_rc_broker_var(*_):
                        try:
                            _boot_rc_watch["broker"] = str(
                                var_broker.get() or ""
                            ).upper()
                        except Exception:
                            pass

                    var_broker.trace_add("write", _on_boot_rc_broker_var)

                    def _boot_rc_abort():
                        return should_abort_startup_retry(
                            pf_timer_state.get("closing"),
                            launched["status"],
                            get_adapter_epoch(),
                            _boot_rc_ep,
                            cur_broker=_boot_rc_watch["broker"],
                            expected_broker=boot_rc_b,
                        )

                    def _bg_startup_reconnect_worker():
                        for _rc_i in range(22):
                            wait_s = 3.0 if _rc_i == 0 else 4.0
                            if sleep_with_startup_abort(wait_s, _boot_rc_abort):
                                return
                            if active_adapter is not None:
                                return
                            new_rc_ad = connect_broker_adapter(
                                boot_rc_b,
                                parent=None,
                                force_wizard=False,
                                fast_startup=False,
                                suppress_error_modal=True,
                                allow_interactive_oauth=False,
                            )
                            if _boot_rc_abort():
                                return
                            def_msg_rc = str(
                                _last_boot_deferred_auth_msg or ""
                            ).strip()
                            if new_rc_ad is None and def_msg_rc:
                                def _show_def_rc_on_ui(msg_t=def_msg_rc):
                                    if _boot_rc_abort() or active_adapter is not None:
                                        return
                                    if default_status_lbl is not None:
                                        try:
                                            default_status_lbl.config(
                                                text=f"🔑 {msg_t}", fg="#fbbf24"
                                            )
                                        except Exception:
                                            pass

                                try:
                                    pf.after(0, _show_def_rc_on_ui)
                                except Exception:
                                    pass
                                return
                            if new_rc_ad is not None:
                                def _finish_boot_reconnect_on_ui(ad_res=new_rc_ad):
                                    global active_adapter, _initial_positions_verified
                                    if (
                                        _boot_rc_abort()
                                        or active_adapter is not None
                                    ):
                                        return
                                    try:
                                        if not pf.winfo_exists():
                                            return
                                    except Exception:
                                        return
                                    with _in_flight_poll_lock:
                                        _bump_adapter_epoch()
                                        _deferred_alarms.clear()
                                        _pf_initial_shown["needs_bg_sync"] = False
                                        _initial_positions_verified = False
                                        active_adapter = ad_res
                                        config["active_broker"] = boot_rc_b
                                        populate_account_dropdown()
                                        refresh_baseline_preview(force_restore=True)
                                    _sync_broker_acct_pills()
                                    _fp_hooks["schedule"]()
                                    if default_status_lbl is not None:
                                        try:
                                            default_status_lbl.config(
                                                text=f"✓ Connected {boot_rc_b} automatically once network came online.",
                                                fg="#34d399",
                                            )
                                        except Exception:
                                            pass
                                    if _IS_MAIN_PROCESS:
                                        start_background_update_check(
                                            pf, cancel_pf_fn=_cancel_pf_timers
                                        )

                                try:
                                    pf.after(0, _finish_boot_reconnect_on_ui)
                                except Exception:
                                    pass
                                return

                        def _show_offline_rc_on_ui():
                            if _boot_rc_abort() or active_adapter is not None:
                                return
                            if default_status_lbl is not None:
                                try:
                                    default_status_lbl.config(
                                        text=f"⚠️ Still offline — could not reach {boot_rc_b} at startup. Click API Keys or retry when online.",
                                        fg="#fbbf24",
                                    )
                                except Exception:
                                    pass

                        try:
                            pf.after(0, _show_offline_rc_on_ui)
                        except Exception:
                            pass

                    threading.Thread(
                        target=_bg_startup_reconnect_worker, daemon=True
                    ).start()

    if post_daily_breach_prompt:
        pf.after(150, show_daily_breach_return_notice)
    elif (
        parent is None
        and config.get("seen_layout_tour_version") != LAYOUT_TOUR_VERSION
    ):
        pf.after(
            180,
            lambda: (
                show_layout_tour_dialog()
                if (pf.winfo_exists() and pf.grab_current() is None)
                else None
            ),
        )

    if parent is None:
        pf.mainloop()
        return launched["status"]
    return True


