    _sync_hud_bottom_bar_layout()

    _feed_tick_state = {"last_mono": 0.0}

    def _tick_loss_streak_hud():
        """Updates the live Loss Streak countdown timer on the HUD at 200ms
        resolution when a streak is active (eliminating 1s phase-drift jitter),
        refreshes Option C feed-freshness LED/age at ~1s cadence, and saves
        session state if a loss timestamp ages out."""
        try:
            if not root.winfo_exists():
                return
            if _hud_hidden_by_overlay:
                ov_chk = _active_penalty_box_overlay
                if (
                    ov_chk is None
                    or getattr(ov_chk, "closed", True)
                    or (
                        getattr(ov_chk, "_build_done", False)
                        and not _has_live_penalty_overlay_window()
                    )
                ):
                    _restore_hud_after_overlay(lift_hud=True)
            if consecutive_api_failures == 0 and not api_disconnect_alerted:
                prev_cnt = len(recent_loss_timestamps)
                active_cols = get_active_hud_columns(config)
                if (
                    prev_cnt > 0
                    or "loss_streak" in active_cols
                    or acct_badge_mode == 1
                ):
                    st_txt, st_bg = format_loss_streak_multiline()
                    disp_bg = "#262a2e" if st_bg in ("#2c3e50", "#1f538d") else st_bg
                    for idx, cid in enumerate(active_cols):
                        if cid == "loss_streak" and idx < len(hud_ui_labels):
                            if (
                                hud_ui_labels[idx].cget("text") != st_txt
                                or hud_ui_labels[idx].cget("bg") != disp_bg
                            ):
                                hud_ui_labels[idx].config(text=st_txt, bg=disp_bg)
                    if acct_badge_mode == 1:
                        refresh_acct_badge()
                    if len(recent_loss_timestamps) != prev_cnt:
                        save_session_state()
            now_tick_m = time.monotonic()
            adv_feed = (now_tick_m - _feed_tick_state["last_mono"]) >= 0.90
            if adv_feed:
                _feed_tick_state["last_mono"] = now_tick_m
            _apply_hud_status_pill_state(mute_btn, advance_streak=adv_feed)
            if adv_feed:
                refresh_tip_fn = getattr(mute_btn, "_refresh_tooltip_feed_fn", None)
                if callable(refresh_tip_fn):
                    refresh_tip_fn()
        except Exception:
            pass
        try:
            fast_hud_tick = bool(
                len(recent_loss_timestamps) > 0
                or pending_halt_breach is not None
                or active_non_breach_halted_syms
            )
            next_ms = 200 if fast_hud_tick else 1000
            root.after(next_ms, _tick_loss_streak_hud)
        except Exception:
            pass

    root.after(200, _tick_loss_streak_hud)

    hb_state = {"warned": False}

    def _check_data_loop_heartbeat():
        """Monitors last_data_loop_heartbeat from the Tk mainloop every 5s and
        surfaces a non-destructive stall warning if the polling loop has not
        advanced for >45 seconds (never spawns a second data_loop thread)."""
        try:
            if not root.winfo_exists():
                return
            fh_hb = _get_feed_health_state(advance_streak=False)
            if fh_hb["is_stalled"]:
                if not hb_state["warned"]:
                    hb_state["warned"] = True
                    log_event(
                        "WARN",
                        f"Data loop heartbeat stalled ({fh_hb['hb_age']:.1f}s since last poll iteration).",
                    )
                if not cooldown_active and not alarm_active:
                    _apply_hud_status_pill_state(mute_btn, advance_streak=False)
            elif hb_state["warned"]:
                hb_state["warned"] = False
                log_event(
                    "SESSION",
                    "Data loop heartbeat recovered and resumed polling.",
                )
                if not cooldown_active and not alarm_active:
                    _apply_hud_status_pill_state(mute_btn, advance_streak=False)
        except Exception:
            pass
        try:
            root.after(5000, _check_data_loop_heartbeat)
        except Exception:
            pass

    root.after(5000, _check_data_loop_heartbeat)

    threading.Thread(
        target=data_loop,
        args=(ui_labels, mute_btn, settings_btn, close_btn, root),
        daemon=True
    ).start()

    try:
        saved_cd_end = float(config.get("active_cooldown_end_epoch", 0.0) or 0.0)
        rem_cd_sec = saved_cd_end - time.time()
        if rem_cd_sec > 2.0:
            rem_cd_mins = max(0.08, rem_cd_sec / 60.0)
            saved_cd_lbl = str(
                config.get("active_cooldown_label") or "RESUMED LOCKOUT"
            )
            log_event(
                "GUARDRAIL",
                f"Resuming unfinished OS lockout timer from disk "
                f"({rem_cd_sec:.0f}s remaining · {saved_cd_lbl}).",
            )
            root.after(
                150,
                lambda m=rem_cd_mins, lbl=saved_cd_lbl: start_cooldown_lock(
                    m,
                    mute_btn,
                    label_prefix=lbl,
                    adapter=active_adapter,
                    was_flat_at_lock_start=current_is_flat,
                ),
            )
        elif saved_cd_end > 0.0:
            config["active_cooldown_end_epoch"] = 0.0
            config["active_cooldown_label"] = ""
            save_config(config)
    except Exception:
        pass

    root.mainloop()


