UPDATE_CHECK_STAMP_PATH = os.path.join(USER_HOME, ".enforcer_update_check_ts")
_SINGLE_INSTANCE_MUTEX_HANDLE = None
SINGLE_INSTANCE_MUTEX_NAME = "Local\\PnLEnforcerBeta_SingleInstance_Mutex"


def _is_another_instance_running():
    """Probes whether another instance of PnL Enforcer currently holds the
    Windows kernel mutex without holding a new handle open."""
    if _SINGLE_INSTANCE_MUTEX_HANDLE is not None:
        return False
    try:
        kernel32 = ctypes.windll.kernel32
        h = kernel32.CreateMutexW(None, False, SINGLE_INSTANCE_MUTEX_NAME)
        last_err = kernel32.GetLastError()
        if h:
            kernel32.CloseHandle(h)
        return last_err == 183  # ERROR_ALREADY_EXISTS
    except Exception:
        return False


def _release_single_instance_mutex():
    """Releases the current process's single-instance mutex handle (used right
    before restarting into a newly downloaded update)."""
    global _SINGLE_INSTANCE_MUTEX_HANDLE
    if _SINGLE_INSTANCE_MUTEX_HANDLE:
        try:
            ctypes.windll.kernel32.CloseHandle(_SINGLE_INSTANCE_MUTEX_HANDLE)
        except Exception:
            pass
        _SINGLE_INSTANCE_MUTEX_HANDLE = None


def _ensure_single_instance_or_exit():
    """Acquires the Windows kernel single-instance mutex for the lifetime of
    this process. If another instance of PnL Enforcer is already running, logs
    a guardrail block, shows a topmost warning popup, and exits cleanly."""
    global _SINGLE_INSTANCE_MUTEX_HANDLE
    if _SINGLE_INSTANCE_MUTEX_HANDLE is not None:
        return
    try:
        kernel32 = ctypes.windll.kernel32
        handle = kernel32.CreateMutexW(None, False, SINGLE_INSTANCE_MUTEX_NAME)
        last_err = kernel32.GetLastError()
        if last_err == 183:  # ERROR_ALREADY_EXISTS
            if handle:
                kernel32.CloseHandle(handle)
            log_event(
                "GUARDRAIL",
                "BLOCKED: Attempted to launch a second instance of PnL Enforcer "
                "while an instance is already running.",
            )
            try:
                alert_root = tk.Tk()
                alert_root.withdraw()
                alert_root.attributes("-topmost", True)
                messagebox.showwarning(
                    "PnL Enforcer Already Running",
                    "An instance of PnL Enforcer is already open on your PC.\n\n"
                    "To prevent duplicate flatten orders and double-logged trades, "
                    "only one instance can run at a time.\n\n"
                    "Please close the existing PnL Enforcer HUD or Pre-Flight window first.",
                    parent=alert_root,
                )
                alert_root.destroy()
            except Exception:
                print(
                    "\n[BLOCKED] PnL Enforcer is already running! "
                    "Please close the existing window first.\n"
                )
            sys.exit(0)
        _SINGLE_INSTANCE_MUTEX_HANDLE = handle
    except SystemExit:
        raise
    except Exception:
        pass


def _fetch_available_update_payload(skip_if_recent=False):
    """Checks GitHub / Gist for a newer APP_VERSION off the UI thread.
    Returns (best_ver, best_bytes, cl_bytes, cl_text, ts) if a newer version
    exists, or None if up to date / offline."""
    try:
        now_ts = time.time()
        if skip_if_recent and os.path.exists(UPDATE_CHECK_STAMP_PATH):
            try:
                with open(UPDATE_CHECK_STAMP_PATH, "r", encoding="utf-8") as sf:
                    last_chk = float(sf.read().strip() or "0")
                if (now_ts - last_chk) < 25.0:
                    return None
            except Exception:
                pass
        try:
            with open(UPDATE_CHECK_STAMP_PATH, "w", encoding="utf-8") as sf:
                sf.write(f"{now_ts:.3f}")
        except Exception:
            pass

        import urllib.request
        ts = int(now_ts)
        is_beta = _is_beta_channel_build()
        active_gist_id = (
            BETA_GIST_BUNDLE_ID if is_beta else MAIN_GIST_BUNDLE_ID
        )
        active_enforcer_raw = (
            BETA_GIST_ENFORCER_RAW_URL if is_beta else GIST_ENFORCER_RAW_URL
        )
        active_raw_base = (
            BETA_GITHUB_RAW_BASE if is_beta else GITHUB_RAW_BASE
        )
        candidate_urls = []
        g_meta = None
        best_ver = None
        best_bytes = None
        try:
            api_req = urllib.request.Request(
                f"https://api.github.com/gists/{active_gist_id}",
                headers={
                    "User-Agent": f"PnL-Enforcer-Updater/{APP_VERSION}",
                    "Accept": "application/vnd.github+json",
                },
            )
            with urllib.request.urlopen(api_req, timeout=3) as api_resp:
                g_meta = json.loads(
                    api_resp.read().decode("utf-8", errors="replace")
                )
            enf_meta = g_meta.get("files", {}).get("enforcer.py", {})
            if not enf_meta.get("truncated") and enf_meta.get("content"):
                c_bytes = enf_meta["content"].encode("utf-8")
                ok_g, g_ver, _g_err = _validate_enforcer_source_bytes(c_bytes)
                if ok_g and _parse_version_tuple(g_ver) > _parse_version_tuple(
                    APP_VERSION
                ):
                    best_ver = g_ver
                    best_bytes = c_bytes
                elif ok_g:
                    best_ver = g_ver
            live_raw = enf_meta.get("raw_url")
            if live_raw:
                candidate_urls.append(live_raw)
        except Exception:
            pass
        candidate_urls.extend([
            f"{active_enforcer_raw}?t={ts}",
            f"{active_raw_base}enforcer.py?t={ts}",
        ])

        if best_ver is None:
            for url in candidate_urls:
                try:
                    req = urllib.request.Request(
                        url,
                        headers={
                            "User-Agent": f"PnL-Enforcer-Updater/{APP_VERSION}",
                            "Cache-Control": "no-cache",
                        },
                    )
                    with urllib.request.urlopen(req, timeout=8) as resp:
                        head_bytes = resp.read(4096)
                        head_txt = head_bytes.decode("utf-8", errors="replace")
                        m_rem = re.search(
                            r'(?m)^APP_VERSION\s*=\s*["\']([^"\']+)["\']',
                            head_txt,
                        )
                        v_cand = (
                            m_rem.group(1).strip() if m_rem else APP_VERSION
                        )
                        if _parse_version_tuple(v_cand) <= _parse_version_tuple(
                            APP_VERSION
                        ):
                            if best_ver is None:
                                best_ver = v_cand
                            continue
                        rem_bytes = head_bytes + resp.read()
                    rem_txt = rem_bytes.decode("utf-8", errors="replace")
                    if (
                        "def data_loop" not in rem_txt
                        or 'if __name__ == "__main__":' not in rem_txt
                    ):
                        continue
                    try:
                        compile(rem_txt, "enforcer.py", "exec")
                    except SyntaxError:
                        continue
                    if (
                        best_ver is None
                        or _parse_version_tuple(v_cand)
                        > _parse_version_tuple(best_ver)
                    ):
                        best_ver = v_cand
                        best_bytes = rem_bytes
                except Exception:
                    continue

        if not os.path.exists(ICON_PATH):
            ico_bytes = _fetch_remote_doc_bytes("enforcer.ico", ts=ts)
            if ico_bytes:
                try:
                    with open(ICON_PATH, "wb") as icf:
                        icf.write(ico_bytes)
                except Exception:
                    pass

        if best_ver is None:
            print(f"Version check: v{APP_VERSION} (Offline / skipped)")
            return None

        if _parse_version_tuple(best_ver) <= _parse_version_tuple(APP_VERSION):
            print(f"Version check: v{APP_VERSION} (Up to date)")
            return None

        if not best_bytes:
            return None

        print(f"New update available: v{APP_VERSION} -> v{best_ver}")
        cl_bytes = None
        if isinstance(g_meta, dict):
            cl_meta = g_meta.get("files", {}).get("CHANGELOG.md", {})
            if not cl_meta.get("truncated") and cl_meta.get("content"):
                cl_bytes = cl_meta["content"].encode("utf-8")
        if not cl_bytes:
            cl_bytes = _fetch_remote_doc_bytes("CHANGELOG.md", ts=ts)
        cl_text = (
            cl_bytes.decode("utf-8", errors="replace") if cl_bytes else ""
        )
        return (best_ver, best_bytes, cl_bytes, cl_text, ts)
    except Exception:
        print(f"Version check: v{APP_VERSION} (Offline / skipped)")
        return None


def _install_update_payload(best_ver, best_bytes, cl_bytes, ts):
    """Validates best_bytes, backs up the current working enforcer.py / CHANGELOG.md
    to .prev (unless an unconfirmed boot_pending stamp is still active), records
    .enforcer_boot_pending.json for crash-safe startup recovery, writes the new
    update files atomically to SCRIPT_DIR, and returns target_py."""
    ok_new, parsed_new_v, new_err = _validate_enforcer_source_bytes(best_bytes)
    if not ok_new:
        raise ValueError(f"Refusing to install invalid update payload: {new_err}")

    script_dir = SCRIPT_DIR
    target_py = os.path.join(script_dir, "enforcer.py")
    target_cl = os.path.join(script_dir, "CHANGELOG.md")
    prev_py = _get_prev_enforcer_path()
    prev_cl = _get_prev_changelog_path()
    bp_path = _get_boot_pending_path()

    # Only overwrite .prev if the current script booted cleanly (no stale
    # boot_pending marker) OR no .prev backup exists yet, so a broken update
    # that never reached Pre-Flight can never overwrite a known-good backup.
    can_rotate_prev = (not os.path.exists(bp_path)) or (not os.path.isfile(prev_py))
    saved_prev_ver = ""
    wrote_new_prev = False
    if can_rotate_prev and os.path.isfile(target_py):
        try:
            with open(target_py, "rb") as cur_f:
                cur_bytes = cur_f.read()
            ok_cur, cur_ver, _cur_err = _validate_enforcer_source_bytes(cur_bytes)
            if ok_cur and cur_ver != (parsed_new_v or str(best_ver)):
                tmp_prev = f"{prev_py}.{os.getpid()}.tmp"
                with open(tmp_prev, "wb") as pf_out:
                    pf_out.write(cur_bytes)
                    pf_out.flush()
                    os.fsync(pf_out.fileno())
                os.replace(tmp_prev, prev_py)
                saved_prev_ver = cur_ver
                wrote_new_prev = True
                if os.path.isfile(target_cl):
                    try:
                        with open(target_cl, "rb") as cur_cl_f:
                            cur_cl_b = cur_cl_f.read()
                        if cur_cl_b:
                            tmp_prev_cl = f"{prev_cl}.{os.getpid()}.tmp"
                            with open(tmp_prev_cl, "wb") as pcl_out:
                                pcl_out.write(cur_cl_b)
                            os.replace(tmp_prev_cl, prev_cl)
                    except Exception:
                        pass
        except Exception:
            pass

    existing_prev_ver = ""
    if not saved_prev_ver:
        rb_existing = get_rollback_backup_info()
        existing_prev_ver = rb_existing.get("prev_version") or ""
        saved_prev_ver = existing_prev_ver or APP_VERSION

    try:
        bp_payload = {
            "target_version": str(best_ver),
            "prev_version": str(saved_prev_ver),
            "installed_at": time.time(),
        }
        tmp_bp = f"{bp_path}.{os.getpid()}.tmp"
        with open(tmp_bp, "w", encoding="utf-8") as bpf:
            json.dump(bp_payload, bpf, indent=2)
            bpf.flush()
            os.fsync(bpf.fileno())
        os.replace(tmp_bp, bp_path)
    except Exception:
        pass

    tmp_py = f"{target_py}.{os.getpid()}.tmp"
    with open(tmp_py, "wb") as f:
        f.write(best_bytes)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp_py, target_py)

    if cl_bytes:
        try:
            tmp_cl = f"{target_cl}.{os.getpid()}.tmp"
            with open(tmp_cl, "wb") as cf:
                cf.write(cl_bytes)
            os.replace(tmp_cl, target_cl)
        except Exception:
            pass

    # When invoked from Launch_Enforcer.bat --console (--check-update), cmd.exe
    # is still executing Launch_Enforcer.bat and will resume at its prior byte
    # offset on return; skip rewriting Launch_Enforcer.bat in that mode so cmd
    # never lands mid-line (normal GUI updates rewrite Launch_Enforcer.bat safely).
    doc_list = (
        ("README.md", "LICENSE.txt", "enforcer.ico")
        if "--check-update" in sys.argv
        else ("Launch_Enforcer.bat", "README.md", "LICENSE.txt", "enforcer.ico")
    )
    for doc_name in doc_list:
        doc_bytes = _fetch_remote_doc_bytes(doc_name, ts=ts)
        if doc_bytes:
            try:
                doc_dst = os.path.join(script_dir, doc_name)
                doc_tmp = f"{doc_dst}.{os.getpid()}.tmp"
                with open(doc_tmp, "wb") as df:
                    df.write(doc_bytes)
                os.replace(doc_tmp, doc_dst)
            except Exception:
                pass

    skipped_prev = _peek_saved_skipped_update_version()
    if skipped_prev and _parse_version_tuple(best_ver) >= _parse_version_tuple(
        skipped_prev
    ):
        _record_skipped_update_version_on_disk("")

    if wrote_new_prev:
        bk_note = f"rollback backup v{saved_prev_ver} saved"
    elif existing_prev_ver:
        bk_note = f"existing rollback backup v{existing_prev_ver} preserved"
    else:
        bk_note = "fresh install — no prior script to back up"
    log_event(
        "SESSION",
        f"Installed update v{APP_VERSION} -> v{best_ver} ({bk_note}).",
    )
    print(f"[SUCCESS] Updated to PnL Enforcer v{best_ver} ({bk_note}).\n")
    return target_py


def _is_update_version_skipped(cand_ver):
    skipped_v = _peek_saved_skipped_update_version()
    if not skipped_v or not cand_ver:
        return False
    return _parse_version_tuple(cand_ver) == _parse_version_tuple(skipped_v)


def _peek_saved_check_updates_pref():
    """Reads check_updates_on_startup from CONFIG_PATH (defaults to True)."""
    try:
        if isinstance(config, dict) and "check_updates_on_startup" in config:
            return bool(config.get("check_updates_on_startup", True))
        if os.path.exists(CONFIG_PATH):
            with open(CONFIG_PATH, "r", encoding="utf-8") as f:
                data = json.load(f)
            return bool(data.get("check_updates_on_startup", True))
    except Exception:
        pass
    return True


def check_for_updates_cli(restart_on_update=False, skip_if_recent=False):
    """Checks GitHub / Gist for a newer APP_VERSION and pops up a GUI dialog
    (with Changelog preview + link) to download and install the latest files."""
    try:
        if not _peek_saved_check_updates_pref():
            return
        if _is_another_instance_running():
            return
        payload = _fetch_available_update_payload(skip_if_recent=skip_if_recent)
        if payload is None:
            return
        best_ver, best_bytes, cl_bytes, cl_text, ts = payload
        if _is_update_version_skipped(best_ver):
            print(
                f"Version check: v{best_ver} paused after rollback "
                f"(staying on v{APP_VERSION})."
            )
            return
        if show_update_available_dialog(APP_VERSION, best_ver, cl_text):
            target_py = _install_update_payload(
                best_ver, best_bytes, cl_bytes, ts
            )
            if restart_on_update:
                _release_single_instance_mutex()
                _spawn_updated_enforcer(target_py)
        else:
            print(f"[SKIPPED] Continuing with local v{APP_VERSION}...\n")
    except SystemExit:
        raise
    except Exception:
        print(f"Version check: v{APP_VERSION} (Offline / skipped)")


_manual_update_chk_busy = False


def check_for_updates_manual(parent_pf=None, from_live_hud=False, cancel_pf_fn=None):
    """Manual on-demand update check from Logs ▾ -> Check for Updates Now...
    Runs the network fetch off the UI thread, ignores skipped_update_version so
    users who rolled back can manually re-apply an update whenever ready, and
    enforces the same flat/unlocked guardrails."""
    global _manual_update_chk_busy
    hide_all_tooltips()
    if _manual_update_chk_busy:
        return False
    ok_sw, _sw_code, sw_msg = _check_version_switch_guardrails(
        from_live_hud=from_live_hud, action_label="In-app update", log_block=True
    )
    if not ok_sw:
        messagebox.showwarning("Update Check Locked", sw_msg, parent=parent_pf)
        return False

    _manual_update_chk_busy = True
    if parent_pf is not None:
        try:
            parent_pf.config(cursor="watch")
        except Exception:
            pass

    def _bg_fetch():
        global _manual_update_chk_busy
        payload = _fetch_available_update_payload(skip_if_recent=False)

        def _finish_on_ui():
            global _manual_update_chk_busy
            _manual_update_chk_busy = False
            if parent_pf is not None:
                try:
                    if not parent_pf.winfo_exists():
                        return
                    parent_pf.config(cursor="")
                except Exception:
                    return
            if payload is None:
                messagebox.showinfo(
                    "PnL Enforcer — Up to Date",
                    f"You are running the latest available version on this channel (v{APP_VERSION}), "
                    "or GitHub is currently unreachable.",
                    parent=parent_pf,
                )
                return
            best_ver, best_bytes, cl_bytes, cl_text, ts = payload
            ok_re, _re_c, re_msg = _check_version_switch_guardrails(
                from_live_hud=from_live_hud,
                action_label="In-app update",
                log_block=True,
            )
            if not ok_re:
                messagebox.showwarning(
                    "Update Check Locked", re_msg, parent=parent_pf
                )
                return
            if show_update_available_dialog(
                APP_VERSION, best_ver, cl_text, parent=parent_pf
            ):
                try:
                    target_py = _install_update_payload(
                        best_ver, best_bytes, cl_bytes, ts
                    )
                except Exception as exc:
                    messagebox.showerror(
                        "Update Install Failed",
                        f"Could not install v{best_ver}: {exc}",
                        parent=parent_pf,
                    )
                    return
                if callable(cancel_pf_fn):
                    try:
                        cancel_pf_fn()
                    except Exception:
                        pass
                if parent_pf is not None:
                    try:
                        parent_pf.destroy()
                    except Exception:
                        pass
                _release_single_instance_mutex()
                _spawn_updated_enforcer(target_py)

        if parent_pf is not None:
            try:
                parent_pf.after(10, _finish_on_ui)
                return
            except Exception:
                pass
        _manual_update_chk_busy = False

    threading.Thread(target=_bg_fetch, daemon=True).start()
    return True


def start_background_update_check(parent_pf, cancel_pf_fn=None):
    """Runs the version check in a background thread right after Pre-Flight
    opens so startup is instant, and pops up the interactive Update Available
    + Changelog modal over Pre-Flight only if a newer version is found."""
    if not _peek_saved_check_updates_pref():
        return

    def _worker():
        payload = _fetch_available_update_payload(skip_if_recent=True)
        if payload is None:
            return
        best_ver, best_bytes, cl_bytes, cl_text, ts = payload
        if _is_update_version_skipped(best_ver):
            print(
                f"Version check: v{best_ver} paused after rollback "
                f"(staying on v{APP_VERSION})."
            )
            return

        def _prompt_on_ui():
            try:
                if not parent_pf.winfo_exists():
                    return
                if parent_pf.grab_current() is not None:
                    parent_pf.after(300, _prompt_on_ui)
                    return
                ok_sw, _sw_c, _sw_m = _check_version_switch_guardrails(
                    from_live_hud=False, action_label="Update", log_block=False
                )
                if not ok_sw:
                    return
                if show_update_available_dialog(
                    APP_VERSION, best_ver, cl_text, parent=parent_pf
                ):
                    target_py = _install_update_payload(
                        best_ver, best_bytes, cl_bytes, ts
                    )
                    if cancel_pf_fn is not None:
                        try:
                            cancel_pf_fn()
                        except Exception:
                            pass
                    try:
                        parent_pf.destroy()
                    except Exception:
                        pass
                    _release_single_instance_mutex()
                    _spawn_updated_enforcer(target_py)
                else:
                    print(f"[SKIPPED] Continuing with local v{APP_VERSION}...\n")
            except SystemExit:
                raise
            except Exception:
                pass

        try:
            parent_pf.after(150, _prompt_on_ui)
        except Exception:
            pass

    threading.Thread(target=_worker, daemon=True).start()


_IS_MAIN_PROCESS = False
_DEBUG_CONSOLE_STREAMS_ATTACHED = False


def _peek_saved_debug_console_pref():
    """Reads show_debug_console from CONFIG_PATH before load_config() runs."""
    if "--console" in sys.argv:
        return True
    try:
        if os.path.exists(CONFIG_PATH):
            with open(CONFIG_PATH, "r", encoding="utf-8") as f:
                data = json.load(f)
            return bool(data.get("show_debug_console", False))
    except Exception:
        pass
    return False


def set_debug_console_visible(visible_bool, from_user_toggle=False):
    """Shows or hides the background Windows debug console window on the fly
    (allocating a console if launched via pythonw.exe and toggled ON in
    Preferences), while always keeping the console's 'X' Close button disabled
    so it can never be accidentally closed mid-session. Never un-minimizes an
    already-visible console unless `from_user_toggle=True`."""
    global _DEBUG_CONSOLE_STREAMS_ATTACHED
    if not _IS_MAIN_PROCESS and "--console" not in sys.argv:
        return
    try:
        kernel32 = ctypes.windll.kernel32
        user32 = ctypes.windll.user32
        hwnd = kernel32.GetConsoleWindow()
        want_show = bool(visible_bool or ("--console" in sys.argv))

        if want_show and not hwnd:
            if kernel32.AllocConsole():
                hwnd = kernel32.GetConsoleWindow()
                _DEBUG_CONSOLE_STREAMS_ATTACHED = False

        if not hwnd:
            return

        try:
            kernel32.SetConsoleTitleW(
                f"PnL Enforcer Beta v{APP_VERSION} — Debug Terminal"
            )
        except Exception:
            pass

        # Always grey out / remove SC_CLOSE (0xF060) on the console system menu
        h_menu = user32.GetSystemMenu(hwnd, False)
        if h_menu:
            user32.DeleteMenu(h_menu, 0xF060, 0x00000000)

        if want_show:
            if not _DEBUG_CONSOLE_STREAMS_ATTACHED:
                try:
                    con_out = open(
                        "CONOUT$",
                        "w",
                        encoding="utf-8",
                        errors="replace",
                        buffering=1,
                    )
                    sys.stdout = con_out
                    sys.stderr = _StderrToLogTee(con_out)
                    _DEBUG_CONSOLE_STREAMS_ATTACHED = True
                    if os.path.exists(LOG_PATH):
                        with open(
                            LOG_PATH, "r", encoding="utf-8", errors="replace"
                        ) as lf:
                            tail_lines = lf.readlines()[-25:]
                        for tl in tail_lines:
                            con_out.write(tl)
                except Exception:
                    pass
            already_vis = bool(user32.IsWindowVisible(hwnd))
            if from_user_toggle:
                if user32.IsIconic(hwnd):
                    user32.ShowWindow(hwnd, 9)  # SW_RESTORE
                user32.ShowWindow(hwnd, 5)      # SW_SHOW
            elif not already_vis:
                user32.ShowWindow(hwnd, 8)      # SW_SHOWNA (no focus steal / no restore)
        else:
            # SW_HIDE = 0
            user32.ShowWindow(hwnd, 0)
    except Exception:
        pass


def _configure_console_window(hide_unless_debug=True):
    """Hides the background Windows console window during normal GUI operation
    (unless '--console' is passed on the command line or 'show_debug_console' is
    enabled in Preferences) and disables the console window's 'X' Close button."""
    if not hide_unless_debug:
        try:
            hwnd = ctypes.windll.kernel32.GetConsoleWindow()
            if hwnd:
                h_menu = ctypes.windll.user32.GetSystemMenu(hwnd, False)
                if h_menu:
                    ctypes.windll.user32.DeleteMenu(h_menu, 0xF060, 0x00000000)
        except Exception:
            pass
        return
    set_debug_console_visible(_peek_saved_debug_console_pref())


def _spawn_updated_enforcer(target_py):
    """Launches the newly updated enforcer.py process without a visible console
    window (unless '--console' was passed or show_debug_console is enabled)."""
    want_con = _peek_saved_debug_console_pref()
    extra_args = [fl for fl in ("--console", "--startup") if fl in sys.argv]
    if not want_con:
        py_dir = os.path.dirname(os.path.abspath(sys.executable))
        pyw_cand = os.path.join(py_dir, "pythonw.exe")
        exe_use = pyw_cand if os.path.exists(pyw_cand) else sys.executable
        creation_flags = getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000)
        try:
            subprocess.Popen(
                [exe_use, target_py] + extra_args,
                creationflags=creation_flags,
            )
            sys.exit(0)
        except Exception:
            pass
    sys.exit(subprocess.call([sys.executable, target_py] + extra_args))


if __name__ == "__main__":
    _IS_MAIN_PROCESS = True
    if "--preview-update-dialog" in sys.argv:
        cl_local = ""
        cl_path = os.path.join(SCRIPT_DIR, "CHANGELOG.md")
        if os.path.exists(cl_path):
            with open(cl_path, "r", encoding="utf-8", errors="replace") as f:
                cl_local = f.read()
        show_update_available_dialog("0.9.10", APP_VERSION, cl_local)
        sys.exit(0)
    if "--check-update" in sys.argv:
        _configure_console_window(hide_unless_debug=False)
        check_for_updates_cli(restart_on_update=False, skip_if_recent=False)
        sys.exit(0)
    _configure_console_window(hide_unless_debug=True)
    _ensure_single_instance_or_exit()
    init_daily_log()
    print("\n=========================================")
    print(f"  INITIALIZING PnL ENFORCER BETA v{APP_VERSION}  ")
    print("=========================================\n")
    try:
        if not show_liability_waiver():
            _mark_boot_pending_bat_prompt_suppressed()
            log_event("SESSION", "Liability waiver declined. Exiting.")
            sys.exit(0)

        load_config(log_restore=True)
        if (not _config_load_corrupt) and bool(config.get("start_with_windows", False)):
            _sh_reg = sync_windows_startup_registry(True, refresh_only=True)
            if _sh_reg.get("changed"):
                log_event(
                    "CONFIG",
                    "Refreshed Windows Startup Registry path for PnLEnforcerBeta.",
                )
        active_adapter = run_startup_broker_connect(
            startup_boot=IS_WINDOWS_BOOT_STARTUP
        )

        # Always open Pre-Flight even if active_adapter is None so the user
        # is never locked out of the Broker dropdown or API Keys button.
        if show_preflight_window():
            log_event(
                "SESSION",
                f"Launching {len(get_active_hud_columns(config))}-Column HUD."
            )
            start_gui()
        else:
            log_event("SESSION", "Pre-Flight closed without launching. Exiting.")
            sys.exit(0)
    except Exception as e:
        tb_boot = " | ".join(
            ln.strip() for ln in traceback.format_exc().splitlines() if ln.strip()
        )
        log_event("ERROR", f"Startup failed: {e} ({tb_boot})")
        _offer_crash_boot_rollback(f"{type(e).__name__}: {e}")